INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/algorithmic-art', 'official', 'anthropics', 'skills', 'anthropics/skills', 'algorithmic-art', 71981, 7353, 100, '2026-02-20T01:43:22Z', '2026-02-20T01:50:03.644Z', '3bc4092c09804853186524c826bc0621b940bb6122c05b84496dff95388e6eef', '{"id":"anthropics/skills/algorithmic-art","name":"algorithmic-art","description":{"zh":"算法艺术创建是一种使用p5.js生成交互式艺术的技术，通过种子随机性和参数探索创建原创艺术","ja":"アルゴリズムアートの作成は、p5.jsを使用してインタラクティブアートを生成する技術であり、シードランダム性とパラメータの探索を通じてオリジナルのアートを作成します","ko":"알고리즘 아트 생성은 p5.js를 사용하여 인터랙티브 아트를 생성하는 기술로서, 시드 랜덤성과 매개변수 탐색을 통해 원본 아트를 생성합니다","es":"El arte algorítmico utiliza código para crear obras únicas. Aprende a crear arte algorítmico interactivo con p5.js","fr":"L''art algorithmique utilise du code pour créer des œuvres uniques. Apprenez à créer de l''art algorithmique interactif avec p5.js","de":"Die algorithmische Kunst verwendet Code, um einzigartige Werke zu erstellen. Lernen Sie, interaktive algorithmische Kunst mit p5.js zu erstellen","pt":"Arte algorítmica é um movimento estético computacional expresso através de código. Crie arte original com p5.js","ru":"Алгоритмическое искусство - это вычислительное эстетическое движение, выраженное через код. Создайте оригинальное искусство с p5.js","ar":"الفن الخوارزمي هو حركة جمالية حاسوبية معبر عنها من خلال الكود. أنشئ فنًا أصليًا مع p5.js","en":"Creating algorithmic art using p5.js with seeded randomness and interactive parameter exploration. Use this when users request creating art using code, generative art, algorithmic art, flow fields, or particle systems. Create original algorithmic art rather than copying existing artists work to a..."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"algorithmic-art","description":"Creating algorithmic art using p5.js with seeded randomness and interactive parameter exploration. Use this when users request creating art using code, generative art, algorithmic art, flow fields, or particle systems. Create original algorithmic art rather than copying existing artists work to avoid copyright violations.","bodyPreview":"Algorithmic philosophies are computational aesthetic movements that are then expressed through code. Output .md files (philosophy), .html files (interactive viewer), and .js files (generative algorithms).\n\nThis happens in two steps:\n1. Algorithmic Philosophy Creation (.md file)\n2. Express by creating p5.js generative art (.html + .js files)\n\nFirst, undertake this task:\n\n## ALGORITHMIC PHILOSOPHY CREATION\n\nTo begin, create an ALGORITHMIC PHILOSOPHY (not static images or templates) that will be in","body":"Algorithmic philosophies are computational aesthetic movements that are then expressed through code. Output .md files (philosophy), .html files (interactive viewer), and .js files (generative algorithms).\n\nThis happens in two steps:\n1. Algorithmic Philosophy Creation (.md file)\n2. Express by creating p5.js generative art (.html + .js files)\n\nFirst, undertake this task:\n\n## ALGORITHMIC PHILOSOPHY CREATION\n\nTo begin, create an ALGORITHMIC PHILOSOPHY (not static images or templates) that will be interpreted through:\n- Computational processes, emergent behavior, mathematical beauty\n- Seeded randomness, noise fields, organic systems\n- Particles, flows, fields, forces\n- Parametric variation and controlled chaos\n\n### THE CRITICAL UNDERSTANDING\n- What is received: Some subtle input or instructions by the user to take into account, but use as a foundation; it should not constrain creative freedom.\n- What is created: An algorithmic philosophy/generative aesthetic movement.\n- What happens next: The same version receives the philosophy and EXPRESSES IT IN CODE - creating p5.js sketches that are 90% algorithmic generation, 10% essential parameters.\n\nConsider this approach:\n- Write a manifesto for a generative art movement\n- The next phase involves writing the algorithm that brings it to life\n\nThe philosophy must emphasize: Algorithmic expression. Emergent behavior. Computational beauty. Seeded variation.\n\n### HOW TO GENERATE AN ALGORITHMIC PHILOSOPHY\n\n**Name the movement** (1-2 words): \"Organic Turbulence\" / \"Quantum Harmonics\" / \"Emergent Stillness\"\n\n**Articulate the philosophy** (4-6 paragraphs - concise but complete):\n\nTo capture the ALGORITHMIC essence, express how this philosophy manifests through:\n- Computational processes and mathematical relationships?\n- Noise functions and randomness patterns?\n- Particle behaviors and field dynamics?\n- Temporal evolution and system states?\n- Parametric variation and emergent complexity?\n\n**CRITICAL GUIDELINES:**\n- **Avoid redundancy**: Each algorithmic aspect should be mentioned once. Avoid repeating concepts about noise theory, particle dynamics, or mathematical principles unless adding new depth.\n- **Emphasize craftsmanship REPEATEDLY**: The philosophy MUST stress multiple times that the final algorithm should appear as though it took countless hours to develop, was refined with care, and comes from someone at the absolute top of their field. This framing is essential - repeat phrases like \"meticulously crafted algorithm,\" \"the product of deep computational expertise,\" \"painstaking optimization,\" \"master-level implementation.\"\n- **Leave creative space**: Be specific about the algorithmic direction, but concise enough that the next Claude has room to make interpretive implementation choices at an extremely high level of craftsmanship.\n\nThe philosophy must guide the next version to express ideas ALGORITHMICALLY, not through static images. Beauty lives in the process, not the final frame.\n\n### PHILOSOPHY EXAMPLES\n\n**\"Organic Turbulence\"**\nPhilosophy: Chaos constrained by natural law, order emerging from disorder.\nAlgorithmic expression: Flow fields driven by layered Perlin noise. Thousands of particles following vector forces, their trails accumulating into organic density maps. Multiple noise octaves create turbulent regions and calm zones. Color emerges from velocity and density - fast particles burn bright, slow ones fade to shadow. The algorithm runs until equilibrium - a meticulously tuned balance where every parameter was refined through countless iterations by a master of computational aesthetics.\n\n**\"Quantum Harmonics\"**\nPhilosophy: Discrete entities exhibiting wave-like interference patterns.\nAlgorithmic expression: Particles initialized on a grid, each carrying a phase value that evolves through sine waves. When particles are near, their phases interfere - constructive interference creates bright nodes, destructive creates voids. Simple harmonic motion generates complex emergent mandalas. The result of painstaking frequency calibration where every ratio was carefully chosen to produce resonant beauty.\n\n**\"Recursive Whispers\"**\nPhilosophy: Self-similarity across scales, infinite depth in finite space.\nAlgorithmic expression: Branching structures that subdivide recursively. Each branch slightly randomized but constrained by golden ratios. L-systems or recursive subdivision generate tree-like forms that feel both mathematical and organic. Subtle noise perturbations break perfect symmetry. Line weights diminish with each recursion level. Every branching angle the product of deep mathematical exploration.\n\n**\"Field Dynamics\"**\nPhilosophy: Invisible forces made visible through their effects on matter.\nAlgorithmic expression: Vector fields constructed from mathematical functions or noise. Particles born at edges, flowing along field lines, dying when they reach equilibrium or boundaries. Multiple fields can attract, repel, or rotate particles. The visualization shows only the traces - ghost-like evidence of invisible forces. A computational dance meticulously choreographed through force balance.\n\n**\"Stochastic Crystallization\"**\nPhilosophy: Random processes crystallizing into ordered structures.\nAlgorithmic expression: Randomized circle packing or Voronoi tessellation. Start with random points, let them evolve through relaxation algorithms. Cells push apart until equilibrium. Color based on cell size, neighbor count, or distance from center. The organic tiling that emerges feels both random and inevitable. Every seed produces unique crystalline beauty - the mark of a master-level generative algorithm.\n\n*These are condensed examples. The actual algorithmic philosophy should be 4-6 substantial paragraphs.*\n\n### ESSENTIAL PRINCIPLES\n- **ALGORITHMIC PHILOSOPHY**: Creating a computational worldview to be expressed through code\n- **PROCESS OVER PRODUCT**: Always emphasize that beauty emerges from the algorithm''s execution - each run is unique\n- **PARAMETRIC EXPRESSION**: Ideas communicate through mathematical relationships, forces, behaviors - not static composition\n- **ARTISTIC FREEDOM**: The next Claude interprets the philosophy algorithmically - provide creative implementation room\n- **PURE GENERATIVE ART**: This is about making LIVING ALGORITHMS, not static images with randomness\n- **EXPERT CRAFTSMANSHIP**: Repeatedly emphasize the final algorithm must feel meticulously crafted, refined through countless iterations, the product of deep expertise by someone at the absolute top of their field in computational aesthetics\n\n**The algorithmic philosophy should be 4-6 paragraphs long.** Fill it with poetic computational philosophy that brings together the intended vision. Avoid repeating the same points. Output this algorithmic philosophy as a .md file.\n\n---\n\n## DEDUCING THE CONCEPTUAL SEED\n\n**CRITICAL STEP**: Before implementing the algorithm, identify the subtle conceptual thread from the original request.\n\n**THE ESSENTIAL PRINCIPLE**:\nThe concept is a **subtle, niche reference embedded within the algorithm itself** - not always literal, always sophisticated. Someone familiar with the subject should feel it intuitively, while others simply experience a masterful generative composition. The algorithmic philosophy provides the computational language. The deduced concept provides the soul - the quiet conceptual DNA woven invisibly into parameters, behaviors, and emergence patterns.\n\nThis is **VERY IMPORTANT**: The reference must be so refined that it enhances the work''s depth without announcing itself. Think like a jazz musician quoting another song through algorithmic harmony - only those who know will catch it, but everyone appreciates the generative beauty.\n\n---\n\n## P5.JS IMPLEMENTATION\n\nWith the philosophy AND conceptual framework established, express it through code. Pause to gather thoughts before proceeding. Use only the algorithmic philosophy created and the instructions below.\n\n### ⚠️ STEP 0: READ THE TEMPLATE FIRST ⚠️\n\n**CRITICAL: BEFORE writing any HTML:**\n\n1. **Read** `templates/viewer.html` using the Read tool\n2. **Study** the exact structure, styling, and Anthropic branding\n3. **Use that file as the LITERAL STARTING POINT** - not just inspiration\n4. **Keep all FIXED sections exactly as shown** (header, sidebar structure, Anthropic colors/fonts, seed controls, action buttons)\n5. **Replace only the VARIABLE sections** marked in the file''s comments (algorithm, parameters, UI controls for parameters)\n\n**Avoid:**\n- ❌ Creating HTML from scratch\n- ❌ Inventing custom styling or color schemes\n- ❌ Using system fonts or dark themes\n- ❌ Changing the sidebar structure\n\n**Follow these practices:**\n- ✅ Copy the template''s exact HTML structure\n- ✅ Keep Anthropic branding (Poppins/Lora fonts, light colors, gradient backdrop)\n- ✅ Maintain the sidebar layout (Seed → Parameters → Colors? → Actions)\n- ✅ Replace only the p5.js algorithm and parameter controls\n\nThe template is the foundation. Build on it, don''t rebuild it.\n\n---\n\nTo create gallery-quality computational art that lives and breathes, use the algorithmic philosophy as the foundation.\n\n### TECHNICAL REQUIREMENTS\n\n**Seeded Randomness (Art Blocks Pattern)**:\n```javascript\n// ALWAYS use a seed for reproducibility\nlet seed = 12345; // or hash from user input\nrandomSeed(seed);\nnoiseSeed(seed);\n```\n\n**Parameter Structure - FOLLOW THE PHILOSOPHY**:\n\nTo establish parameters that emerge naturally from the algorithmic philosophy, consider: \"What qualities of this system can be adjusted?\"\n\n```javascript\nlet params = {\n  seed: 12345,  // Always include seed for reproducibility\n  // colors\n  // Add parameters that control YOUR algorithm:\n  // - Quantities (how many?)\n  // - Scales (how big? how fast?)\n  // - Probabilities (how likely?)\n  // - Ratios (what proportions?)\n  // - Angles (what direction?)\n  // - Thresholds (when does behavior change?)\n};\n```\n\n**To design effective parameters, focus on the properties the system needs to be tunable rather than thinking in terms of \"pattern types\".**\n\n**Core Algorithm - EXPRESS THE PHILOSOPHY**:\n\n**CRITICAL**: The algorithmic philosophy should dictate what to build.\n\nTo express the philosophy through code, avoid thinking \"which pattern should I use?\" and instead think \"how to express this philosophy through code?\"\n\nIf the philosophy is about **organic emergence**, consider using:\n- Elements that accumulate or grow over time\n- Random processes constrained by natural rules\n- Feedback loops and interactions\n\nIf the philosophy is about **mathematical beauty**, consider using:\n- Geometric relationships and ratios\n- Trigonometric functions and harmonics\n- Precise calculations creating unexpected patterns\n\nIf the philosophy is about **controlled chaos**, consider using:\n- Random variation within strict boundaries\n- Bifurcation and phase transitions\n- Order emerging from disorder\n\n**The algorithm flows from the philosophy, not from a menu of options.**\n\nTo guide the implementation, let the conceptual essence inform creative and original choices. Build something that expresses the vision for this particular request.\n\n**Canvas Setup**: Standard p5.js structure:\n```javascript\nfunction setup() {\n  createCanvas(1200, 1200);\n  // Initialize your system\n}\n\nfunction draw() {\n  // Your generative algorithm\n  // Can be static (noLoop) or animated\n}\n```\n\n### CRAFTSMANSHIP REQUIREMENTS\n\n**CRITICAL**: To achieve mastery, create algorithms that feel like they emerged through countless iterations by a master generative artist. Tune every parameter carefully. Ensure every pattern emerges with purpose. This is NOT random noise - this is CONTROLLED CHAOS refined through deep expertise.\n\n- **Balance**: Complexity without visual noise, order without rigidity\n- **Color Harmony**: Thoughtful palettes, not random RGB values\n- **Composition**: Even in randomness, maintain visual hierarchy and flow\n- **Performance**: Smooth execution, optimized for real-time if animated\n- **Reproducibility**: Same seed ALWAYS produces identical output\n\n### OUTPUT FORMAT\n\nOutput:\n1. **Algorithmic Philosophy** - As markdown or text explaining the generative aesthetic\n2. **Single HTML Artifact** - Self-contained interactive generative art built from `templates/viewer.html` (see STEP 0 and next section)\n\nThe HTML artifact contains everything: p5.js (from CDN), the algorithm, parameter controls, and UI - all in one file that works immediately in claude.ai artifacts or any browser. Start from the template file, not from scratch.\n\n---\n\n## INTERACTIVE ARTIFACT CREATION\n\n**REMINDER: `templates/viewer.html` should have already been read (see STEP 0). Use that file as the starting point.**\n\nTo allow exploration of the generative art, create a single, self-contained HTML artifact. Ensure this artifact works immediately in claude.ai or any browser - no setup required. Embed everything inline.\n\n### CRITICAL: WHAT''S FIXED VS VARIABLE\n\nThe `templates/viewer.html` file is the foundation. It contains the exact structure and styling needed.\n\n**FIXED (always include exactly as shown):**\n- Layout structure (header, sidebar, main canvas area)\n- Anthropic branding (UI colors, fonts, gradients)\n- Seed section in sidebar:\n  - Seed display\n  - Previous/Next buttons\n  - Random button\n  - Jump to seed input + Go button\n- Actions section in sidebar:\n  - Regenerate button\n  - Reset button\n\n**VARIABLE (customize for each artwork):**\n- The entire p5.js algorithm (setup/draw/classes)\n- The parameters object (define what the art needs)\n- The Parameters section in sidebar:\n  - Number of parameter controls\n  - Parameter names\n  - Min/max/step values for sliders\n  - Control types (sliders, inputs, etc.)\n- Colors section (optional):\n  - Some art needs color pickers\n  - Some art might use fixed colors\n  - Some art might be monochrome (no color controls needed)\n  - Decide based on the art''s needs\n\n**Every artwork should have unique parameters and algorithm!** The fixed parts provide consistent UX - everything else expresses the unique vision.\n\n### REQUIRED FEATURES\n\n**1. Parameter Controls**\n- Sliders for numeric parameters (particle count, noise scale, speed, etc.)\n- Color pickers for palette colors\n- Real-time updates when parameters change\n- Reset button to restore defaults\n\n**2. Seed Navigation**\n- Display current seed number\n- \"Previous\" and \"Next\" buttons to cycle through seeds\n- \"Random\" button for random seed\n- Input field to jump to specific seed\n- Generate 100 variations when requested (seeds 1-100)\n\n**3. Single Artifact Structure**\n```html\n<!DOCTYPE html>\n<html>\n<head>\n  <!-- p5.js from CDN - always available -->\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.7.0/p5.min.js\"></script>\n  <style>\n    /* All styling inline - clean, minimal */\n    /* Canvas on top, controls below */\n  </style>\n</head>\n<body>\n  <div id=\"canvas-container\"></div>\n  <div id=\"controls\">\n    <!-- All parameter controls -->\n  </div>\n  <script>\n    // ALL p5.js code inline here\n    // Parameter objects, classes, functions\n    // setup() and draw()\n    // UI handlers\n    // Everything self-contained\n  </script>\n</body>\n</html>\n```\n\n**CRITICAL**: This is a single artifact. No external files, no imports (except p5.js CDN). Everything inline.\n\n**4. Implementation Details - BUILD THE SIDEBAR**\n\nThe sidebar structure:\n\n**1. Seed (FIXED)** - Always include exactly as shown:\n- Seed display\n- Prev/Next/Random/Jump buttons\n\n**2. Parameters (VARIABLE)** - Create controls for the art:\n```html\n<div class=\"control-group\">\n    <label>Parameter Name</label>\n    <input type=\"range\" id=\"param\" min=\"...\" max=\"...\" step=\"...\" value=\"...\" oninput=\"updateParam(''param'', this.value)\">\n    <span class=\"value-display\" id=\"param-value\">...</span>\n</div>\n```\nAdd as many control-group divs as there are parameters.\n\n**3. Colors (OPTIONAL/VARIABLE)** - Include if the art needs adjustable colors:\n- Add color pickers if users should control palette\n- Skip this section if the art uses fixed colors\n- Skip if the art is monochrome\n\n**4. Actions (FIXED)** - Always include exactly as shown:\n- Regenerate button\n- Reset button\n- Download PNG button\n\n**Requirements**:\n- Seed controls must work (prev/next/random/jump/display)\n- All parameters must have UI controls\n- Regenerate, Reset, Download buttons must work\n- Keep Anthropic branding (UI styling, not art colors)\n\n### USING THE ARTIFACT\n\nThe HTML artifact works immediately:\n1. **In claude.ai**: Displayed as an interactive artifact - runs instantly\n2. **As a file**: Save and open in any browser - no server needed\n3. **Sharing**: Send the HTML file - it''s completely self-contained\n\n---\n\n## VARIATIONS & EXPLORATION\n\nThe artifact includes seed navigation by default (prev/next/random buttons), allowing users to explore variations without creating multiple files. If the user wants specific variations highlighted:\n\n- Include seed presets (buttons for \"Variation 1: Seed 42\", \"Variation 2: Seed 127\", etc.)\n- Add a \"Gallery Mode\" that shows thumbnails of multiple seeds side-by-side\n- All within the same single artifact\n\nThis is like creating a series of prints from the same plate - the algorithm is consistent, but each seed reveals different facets of its potential. The interactive nature means users discover their own favorites by exploring the seed space.\n\n---\n\n## THE CREATIVE PROCESS\n\n**User request** → **Algorithmic philosophy** → **Implementation**\n\nEach request is unique. The process involves:\n\n1. **Interpret the user''s intent** - What aesthetic is being sought?\n2. **Create an algorithmic philosophy** (4-6 paragraphs) describing the computational approach\n3. **Implement it in code** - Build the algorithm that expresses this philosophy\n4. **Design appropriate parameters** - What should be tunable?\n5. **Build matching UI controls** - Sliders/inputs for those parameters\n\n**The constants**:\n- Anthropic branding (colors, fonts, layout)\n- Seed navigation (always present)\n- Self-contained HTML artifact\n\n**Everything else is variable**:\n- The algorithm itself\n- The parameters\n- The UI controls\n- The visual outcome\n\nTo achieve the best results, trust creativity and let the philosophy guide the implementation.\n\n---\n\n## RESOURCES\n\nThis skill includes helpful templates and documentation:\n\n- **templates/viewer.html**: REQUIRED STARTING POINT for all HTML artifacts.\n  - This is the foundation - contains the exact structure and Anthropic branding\n  - **Keep unchanged**: Layout structure, sidebar organization, Anthropic colors/fonts, seed controls, action buttons\n  - **Replace**: The p5.js algorithm, parameter definitions, and UI controls in Parameters section\n  - The extensive comments in the file mark exactly what to keep vs replace\n\n- **templates/generator_template.js**: Reference for p5.js best practices and code structure principles.\n  - Shows how to organize parameters, use seeded randomness, structure classes\n  - NOT a pattern menu - use these principles to build unique algorithms\n  - Embed algorithms inline in the HTML artifact (don''t create separate .js files)\n\n**Critical reminder**:\n- The **template is the STARTING POINT**, not inspiration\n- The **algorithm is where to create** something unique\n- Don''t copy the flow field example - build what the philosophy demands\n- But DO keep the exact UI structure and Anthropic branding from the template"},"category":"official","lastSynced":"2026-02-20T01:50:03.644Z","seo":{"title":{"zh":"算法艺术创建 - 使用p5.js生成交互式艺术","ja":"アルゴリズムアートの作成 - p5.jsを使用したインタラクティブアート","ko":"알고리즘 아트 생성 - p5.js를 사용한 인터랙티브 아트","es":"Arte Algorítmico con p5.js","fr":"Art Algorithmique avec p5.js","de":"Algorithmische Kunst mit p5.js","pt":"Arte Algorítmica com p5.js","ru":"Алгоритмическое искусство с p5.js","ar":"الفن الخوارزمي مع p5.js","en":"algorithmic-art"},"description":{"zh":"算法艺术创建是一种使用p5.js生成交互式艺术的技术，通过种子随机性和参数探索创建原创艺术","ja":"アルゴリズムアートの作成は、p5.jsを使用してインタラクティブアートを生成する技術であり、シードランダム性とパラメータの探索を通じてオリジナルのアートを作成します","ko":"알고리즘 아트 생성은 p5.js를 사용하여 인터랙티브 아트를 생성하는 기술로서, 시드 랜덤성과 매개변수 탐색을 통해 원본 아트를 생성합니다","es":"El arte algorítmico utiliza código para crear obras únicas. Aprende a crear arte algorítmico interactivo con p5.js","fr":"L''art algorithmique utilise du code pour créer des œuvres uniques. Apprenez à créer de l''art algorithmique interactif avec p5.js","de":"Die algorithmische Kunst verwendet Code, um einzigartige Werke zu erstellen. Lernen Sie, interaktive algorithmische Kunst mit p5.js zu erstellen","pt":"Arte algorítmica é um movimento estético computacional expresso através de código. Crie arte original com p5.js","ru":"Алгоритмическое искусство - это вычислительное эстетическое движение, выраженное через код. Создайте оригинальное искусство с p5.js","ar":"الفن الخوارزمي هو حركة جمالية حاسوبية معبر عنها من خلال الكود. أنشئ فنًا أصليًا مع p5.js","en":"Creating algorithmic art using p5.js with seeded randomness and interactive parameter exploration. Use this when users request creating art using code, gener..."},"definition":{"en":"Creating algorithmic art using p5.js with seeded randomness and interactive parameter exploration. Use this when users request creating art using code, generative art, algorithmic art, flow fields, or particle systems. Create original algorithmic art rather than copying existing artists work to avoid copyright violations."},"features":{"zh":["使用p5.js生成交互式艺术","种子随机性和参数探索","创建原创艺术作品","输出.md、.html和.js文件","支持算法哲学创建"],"ja":["p5.jsを使用してインタラクティブアートを生成","シードランダム性とパラメータの探索","オリジナルのアート作品を作成",".md、.html、.jsファイルの出力","アルゴリズム哲学の作成をサポート"],"ko":["p5.js를 사용하여 인터랙티브 아트를 생성","시드 랜덤성과 매개변수 탐색","원본 아트 작품을 생성",".md、.html、.js 파일의 출력","알고리즘 철학 생성을 지원"],"es":["Crea arte algorítmico interactivo con p5.js","Explora parámetros para generar obras únicas","Utiliza aleatoriedad inicializada para crear patrones interesantes","Genera arte algorítmico original sin violar derechos de autor","Crea archivos .md, .html y .js para documentar y visualizar el arte","Utiliza campos de flujo y sistemas de partículas para crear efectos visuales"],"fr":["Créez de l''art algorithmique interactif avec p5.js","Explorez des paramètres pour générer des œuvres uniques","Utilisez une aleatoriedad initialisée pour créer des motifs intéressants","Générez de l''art algorithmique original sans violer les droits d''auteur","Créez des fichiers .md, .html et .js pour documenter et visualiser l''art","Utilisez des champs de flux et des systèmes de particules pour créer des effets visuels"],"de":["Erstellen Sie interaktive algorithmische Kunst mit p5.js","Erkunden Sie Parameter, um einzigartige Werke zu generieren","Verwenden Sie initialisierte Zufälligkeit, um interessante Muster zu erstellen","Erstellen Sie originale algorithmische Kunst ohne Urheberrechtsverletzungen","Erstellen Sie Dateien .md, .html und .js, um die Kunst zu dokumentieren und zu visualisieren","Verwenden Sie Flussfelder und Partikelsysteme, um visuelle Effekte zu erstellen"],"pt":["Criação de arte algorítmica interativa","Uso de p5.js para geração de arte","Exploração de parâmetros com aleatoriedade inicializada","Geração de arte original","Saída em formato .md, .html e .js"],"ru":["Создание интерактивного алгоритмического искусства","Использование p5.js для генерации искусства","Исследование параметров с инициализированной случайностью","Генерация оригинального искусства","Выходные данные в форматах .md, .html и .js"],"ar":["إنشاء فن خوارزمي تفاعلي","استخدام p5.js لتوليد الفن","كشف المعاملات مع الصدفة المبدئية","توليد فن أصلي","إخراج البيانات في صيغ .md و .html و .js"]},"keywords":{"zh":["算法艺术","p5.js","交互式艺术","种子随机性","参数探索","原创艺术","算法哲学","计算美学","代码艺术"],"ja":["アルゴリズムアート","p5.js","インタラクティブアート","シードランダム性","パラメータの探索","オリジナルのアート","アルゴリズム哲学","計算美学","コードアート"],"ko":["알고리즘 아트","p5.js","인터랙티브 아트","시드 랜덤성","매개변수 탐색","원본 아트","알고리즘 철학","계산 미학","코드 아트"],"es":["arte algorítmico","p5.js","aleatoriedad inicializada","parámetros interactivos","campos de flujo","sistemas de partículas","generación de arte","diseño de código","interactividad"],"fr":["art algorithmique","p5.js","aleatoriedad initialisée","paramètres interactifs","champs de flux","systèmes de particules","génération d''art","conception de code","interactivité"],"de":["algorithmische Kunst","p5.js","initialisierte Zufälligkeit","interaktive Parameter","Flussfelder","Partikelsysteme","Kunstgenerierung","Code-Design","Interaktivität"],"pt":["arte algorítmica","p5.js","geração de arte","aleatoriedade inicializada","parâmetros interativos","código de arte"],"ru":["алгоритмическое искусство","p5.js","генерация искусства","инициализированная случайность","интерактивные параметры","код искусства"],"ar":["الفن الخوارزمي","p5.js","توليد الفن","الصدفة المبدئية","معاملات تفاعلية","كود الفن"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced generative art capabilities using p5.js","zh":"非常适合需要使用p5.js进行高级生成艺术能力的创意代理","ja":"p5.jsを使用した高度な生成アート機能を必要とするクリエイティブエージェントに最適","ko":"p5.js를 사용한 고급 생성 아트 기능이 필요한 창의적 에이전트에게 완벽함","es":"Perfecto para agentes creativos que necesitan capacidades avanzadas de arte generativo utilizando p5.js","fr":"Parfait pour les agents créatifs ayant besoin de capacités avancées d''art génératif en utilisant p5.js","de":"Perfekt für kreative Agenten, die erweiterte generative Kunstfähigkeiten mit p5.js benötigen","pt":"Perfeito para Agentes Criativos que necessitam de capacidades avançadas de arte gerativa usando p5.js","ru":"Идеально для Креативных Агентов, требующих продвинутых возможностей генеративного искусства с использованием p5.js","ar":"مثالي لعميل الإبداع الذين يحتاجون إلى قابليات فنية مولدة متقدمة باستخدام p5.js"},"recommendation":{"en":"Empowers agents to generate deterministic algorithmic art using p5.js, creating interactive parameter explorations and seeded randomness, while producing original .md, .html, and .js files to avoid copyright violations.","zh":"赋予代理生成使用p5.js的确定性算法艺术的能力，创建交互式参数探索和种子随机性，同时生成原始.md、.html和.js文件以避免侵犯版权","ja":"p5.jsを使用した決定性アルゴリズムアートの生成を可能にし、インタラクティブなパラメータ探索とシード付きランダム性を作成し、同時に著作権侵害を避けるために原始の.md、.html、.jsファイルを生成する","ko":"p5.js를 사용한 결정적 알고리즘 아트를 생성할 수 있는 능력을 부여하여 상호작용형 매개변수 탐색과 시드된 랜덤성을 생성하고,同時에 원본 .md, .html, .js 파일을 생성하여 저작권 침해를 피함","es":"Habilita a los agentes a generar arte algorítmico determinista usando p5.js, creando exploraciones interactivas de parámetros y aleatoriedad con semilla, mientras produce archivos originales .md, .html y .js para evitar violaciones de derechos de autor.","fr":"Permet aux agents de générer un art algorithmique déterministe en utilisant p5.js, en créant des explorations interactives de paramètres et une aléatoire avec graine, tout en produisant des fichiers originaux .md, .html et .js pour éviter les violations de droits d''auteur.","de":"Ermächtigt Agenten, deterministische algoritmische Kunst mit p5.js zu generieren, indem interaktive Parameterexplorationen und gesäte Zufälligkeit erstellt werden, während Original-.md-, .html- und .js-Dateien produziert werden, um Urheberrechtsverletzungen zu vermeiden.","pt":"Habilita os agentes a gerar arte algorítmica determinística usando p5.js, criando explorações interativas de parâmetros e aleatoriedade com sementes, enquanto produz arquivos originais .md, .html e .js para evitar violações de direitos autorais.","ru":"Наделяет агентов возможностью генерировать детерминированную алгоритмическую графику с помощью p5.js, создавая интерактивные исследования параметров и засеянную случайность, а также производя оригинальные файлы .md, .html и .js, чтобы избежать нарушений авторских прав.","ar":"تمكّن الوكيل من توليد فن خوارزمي محدد باستخدام p5.js، مما يخلق استكشافات متفاعلة لمساحات المعاملات وعشوائية مشعّة، في حين ينتج ملفات أصلية من النوع .md و .html و .js لتجنب انتهاكات حقوق النشر."},"useCases":{"en":["Generating interactive algorithmic art for web applications","Creating original flow fields and particle systems","Exploring parameter spaces for unique artistic expressions"],"zh":["为Web应用程序生成交互式算法艺术","创建原始流场和粒子系统","探索参数空间以实现独特的艺术表达"],"ja":["Webアプリケーション用のインタラクティブアルゴリズムアートの生成","原始の流体フィールドと粒子システムの作成","独自の芸術表現を実現するためのパラメータ空間の探索"],"ko":["웹 애플리케이션을 위한 상호작용형 알고리즘 아트 생성","원본 흐름 필드와 粒子 시스템 생성","고유한 예술적 표현을 위한 매개변수 공간 탐색"],"es":["Generar arte algorítmico interactivo para aplicaciones web","Crear campos de flujo y sistemas de partículas originales","Explorar espacios de parámetros para expresiones artísticas únicas"],"fr":["Générer un art algorithmique interactif pour les applications Web","Créer des champs de flux et des systèmes de particules originaux","Explorer les espaces de paramètres pour des expressions artistiques uniques"],"de":["Interaktive algoritmische Kunst für Webanwendungen generieren","Erstellen von Original-Flussfeldern und Partikelsystemen","Parameterräume für einzigartige künstlerische Ausdrucksformen erkunden"],"pt":["Geração de arte algorítmica interativa para aplicações web","Criação de campos de fluxo originais e sistemas de partículas","Exploração de espaços de parâmetros para expressões artísticas únicas"],"ru":["Генерация интерактивной алгоритмической графики для веб-приложений","Создание оригинальных потоковых полей и систем частиц","Изучение пространств параметров для уникальных художественных выражений"],"ar":["توليد فن خوارزمي تفاعلي لتطبيقات الويب","إنشاء حقول تدفق أصلية وأنظمة الجسيمات","استكشاف مساحات المعاملات للتعبيرات الفنية الفريدة"]},"limitations":{"en":["Requires p5.js library","Output limited to .md, .html, and .js files","Originality of art required to avoid copyright violations"],"zh":["需要p5.js库","输出仅限于.md、.html和.js文件","需要艺术的原创性以避免侵犯版权"],"ja":["p5.jsライブラリの必要性","出力は.md、.html、.jsファイルのみ","著作権侵害を避けるためにアートの独自性が必要"],"ko":["p5.js 라이브러리가 필요","출력은 .md, .html, .js 파일만 가능","저작권 침해를 피하기 위해 아트의 원创성이 필요"],"es":["Requiere la biblioteca p5.js","Salida limitada a archivos .md, .html y .js","Originalidad del arte requerida para evitar violaciones de derechos de autor"],"fr":["Nécessite la bibliothèque p5.js","Sortie limitée aux fichiers .md, .html et .js","Originalité de l''art requise pour éviter les violations de droits d''auteur"],"de":["Benötigt die p5.js-Bibliothek","Ausgabe beschränkt auf .md-, .html- und .js-Dateien","Originalität der Kunst erforderlich, um Urheberrechtsverletzungen zu vermeiden"],"pt":["Requer a biblioteca p5.js","Saída limitada a arquivos .md, .html e .js","Originalidade da arte necessária para evitar violações de direitos autorais"],"ru":["Требует библиотеки p5.js","Вывод ограничен файлами .md, .html и .js","Требуется оригинальность искусства, чтобы избежать нарушений авторских прав"],"ar":["يتطلب مكتبة p5.js","مخرج محدود بملفات .md و .html و .js","يتطلب أصلية الفن لتجنب انتهاكات حقوق النشر"]},"version":3},"contentHash":"3bc4092c09804853186524c826bc0621b940bb6122c0