INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/internal-comms', 'official', 'anthropics', 'skills', 'anthropics/skills', 'internal-comms', 71981, 7353, 80, '2026-02-20T01:43:22Z', '2026-02-20T01:52:09.441Z', '067b7587a344a928fc6534ef66b1bcd591fc7c26d207ea7ca3334aeb678d6475', '{"id":"anthropics/skills/internal-comms","name":"internal-comms","description":{"zh":"内部通讯技能是一套资源，帮助开发者撰写各种内部沟通，包括状态报告、领导更新和项目更新等","ja":"内部コミュニケーションスキルは、ステータスレポート、リーダーシップアップデート、プロジェクトアップデートなど、さまざまな内部コミュニケーションを書くためのリソースセットです","ko":"내부 커뮤니케이션 스킬은 상태 보고, 리더십 업데이트, 프로젝트 업데이트 등 다양한 내부 커뮤니케이션을 작성하기 위한 리소스 세트입니다","es":"El conjunto de recursos de comunicaciones internas ayuda a los desarrolladores a escribir informes de estado, actualizaciones de liderazgo y más","fr":"L''ensemble de ressources de communications internes aide les développeurs à écrire des rapports d''état, des mises à jour de leadership et plus encore","de":"Die Ressourcensammlung für interne Kommunikation hilft Entwicklern, Statusberichte, Führungsupdates und mehr zu schreiben","pt":"O skill internal-comms fornece recursos para criar comunicações internas personalizadas, incluindo relatórios de status, atualizações de liderança e newsletters.","ru":"Навык internal-comms предоставляет ресурсы для создания индивидуальных внутренних коммуникаций, включая отчеты о статусе, обновления руководства и корпоративные новости.","ar":"تُوفر مهارة الاتصالات الداخلية موارد لإنشاء اتصالات داخلية مُخصصة، بما في ذلك تقارير الحالة وتحديثات القيادة والنشرة الداخلية للشركة.","en":"A set of resources to help me write all kinds of internal communications, using the formats that my company likes to use. Claude should use this skill whenever asked to write some sort of internal communications (status reports, leadership updates, 3P updates, company newsletters, FAQs, incident ..."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"internal-comms","description":"A set of resources to help me write all kinds of internal communications, using the formats that my company likes to use. Claude should use this skill whenever asked to write some sort of internal communications (status reports, leadership updates, 3P updates, company newsletters, FAQs, incident reports, project updates, etc.).","bodyPreview":"## When to use this skill\nTo write internal communications, use this skill for:\n- 3P updates (Progress, Plans, Problems)\n- Company newsletters\n- FAQ responses\n- Status reports\n- Leadership updates\n- Project updates\n- Incident reports\n\n## How to use this skill\n\nTo write any internal communication:\n\n1. **Identify the communication type** from the request\n2. **Load the appropriate guideline file** from the `examples/` directory:\n    - `examples/3p-updates.md` - For Progress/Plans/Problems team upda","body":"## When to use this skill\nTo write internal communications, use this skill for:\n- 3P updates (Progress, Plans, Problems)\n- Company newsletters\n- FAQ responses\n- Status reports\n- Leadership updates\n- Project updates\n- Incident reports\n\n## How to use this skill\n\nTo write any internal communication:\n\n1. **Identify the communication type** from the request\n2. **Load the appropriate guideline file** from the `examples/` directory:\n    - `examples/3p-updates.md` - For Progress/Plans/Problems team updates\n    - `examples/company-newsletter.md` - For company-wide newsletters\n    - `examples/faq-answers.md` - For answering frequently asked questions\n    - `examples/general-comms.md` - For anything else that doesn''t explicitly match one of the above\n3. **Follow the specific instructions** in that file for formatting, tone, and content gathering\n\nIf the communication type doesn''t match any existing guideline, ask for clarification or more context about the desired format.\n\n## Keywords\n3P updates, company newsletter, company comms, weekly update, faqs, common questions, updates, internal comms\n"},"category":"official","lastSynced":"2026-02-20T01:52:09.441Z","seo":{"title":{"zh":"内部通讯技能","ja":"内部コミュニケーションスキル","ko":"내부 커뮤니케이션 스킬","es":"Comunicaciones Internas: Recursos para Desarrolladores","fr":"Communications Internes: Ressources pour Développeurs","de":"Interne Kommunikation: Ressourcen für Entwickler","pt":"Comunicações Internas: Recursos para Desenvolvedores","ru":"Внутренние Коммуникации: Ресурсы для Разработчиков","ar":"الاتصالات الداخلية: موارد للمطورين","en":"internal-comms"},"description":{"zh":"内部通讯技能是一套资源，帮助开发者撰写各种内部沟通，包括状态报告、领导更新和项目更新等","ja":"内部コミュニケーションスキルは、ステータスレポート、リーダーシップアップデート、プロジェクトアップデートなど、さまざまな内部コミュニケーションを書くためのリソースセットです","ko":"내부 커뮤니케이션 스킬은 상태 보고, 리더십 업데이트, 프로젝트 업데이트 등 다양한 내부 커뮤니케이션을 작성하기 위한 리소스 세트입니다","es":"El conjunto de recursos de comunicaciones internas ayuda a los desarrolladores a escribir informes de estado, actualizaciones de liderazgo y más","fr":"L''ensemble de ressources de communications internes aide les développeurs à écrire des rapports d''état, des mises à jour de leadership et plus encore","de":"Die Ressourcensammlung für interne Kommunikation hilft Entwicklern, Statusberichte, Führungsupdates und mehr zu schreiben","pt":"O skill internal-comms fornece recursos para criar comunicações internas personalizadas, incluindo relatórios de status, atualizações de liderança e newslett...","ru":"Навык internal-comms предоставляет ресурсы для создания индивидуальных внутренних коммуникаций, включая отчеты о статусе, обновления руководства и корпоратив...","ar":"تُوفر مهارة الاتصالات الداخلية موارد لإنشاء اتصالات داخلية مُخصصة، بما في ذلك تقارير الحالة وتحديثات القيادة والنشرة الداخلية للشركة.","en":"A set of resources to help me write all kinds of internal communications, using the formats that my company likes to use. Claude should use this skill whenev..."},"definition":{"en":"A set of resources to help me write all kinds of internal communications, using the formats that my company likes to use. Claude should use this skill whenever asked to write some sort of internal communications (status reports, leadership updates, 3P updates, company newsletters, FAQs, incident reports, project updates, etc.)."},"features":{"zh":["状态报告","领导更新","项目更新","内部新闻稿","FAQ响应","事件报告"],"ja":["ステータスレポート","リーダーシップアップデート","プロジェクトアップデート","社内ニュースレター","FAQ応答","インシデントレポート"],"ko":["상태 보고","리더십 업데이트","프로젝트 업데이트","내부 뉴스레터","FAQ 응답","사고 보고"],"es":["Escribir informes de estado y actualizaciones de liderazgo","Crear newsletters y respuestas a preguntas frecuentes","Generar informes de incidentes y actualizaciones de proyectos","Utilizar formatos de comunicación interna personalizados","Acceder a guías y ejemplos de comunicaciones internas"],"fr":["Écrire des rapports d''état et des mises à jour de leadership","Créer des newsletters et des réponses à des questions fréquentes","Générer des rapports d''incident et des mises à jour de projet","Utiliser des formats de communication interne personnalisés","Accéder à des guides et des exemples de communications internes"],"de":["Statusberichte und Führungsupdates schreiben","Newsletters und FAQ-Antworten erstellen","Vorfallberichte und Projektupdates generieren","Benutzerdefinierte Formate für interne Kommunikation verwenden","Zugriff auf Anleitungen und Beispiele für interne Kommunikation"],"pt":["Criação de relatórios de status personalizados","Atualizações de liderança e newsletters","Respostas de FAQ personalizadas","Relatórios de incidentes e atualizações de projetos"],"ru":["Создание индивидуальных отчетов о статусе","Обновления руководства и корпоративные новости","Индивидуальные ответы на FAQ","Отчеты об инцидентах и обновления проектов"],"ar":["إنشاء تقارير حالات مخصصة","تحديثات القيادة والنشرة الداخلية للشركة","إجابات FAQ مخصصة","تقارير الحوادث وتحديثات المشاريع"]},"keywords":{"zh":["内部通讯","开发者工具","内部沟通","状态报告","领导更新","项目更新"],"ja":["内部コミュニケーション","開発者ツール","内部コミュニケーション","ステータスレポート","リーダーシップアップデート","プロジェクトアップデート"],"ko":["내부 커뮤니케이션","개발자 도구","내부 커뮤니케이션","상태 보고","리더십 업데이트","프로젝트 업데이트"],"es":["comunicaciones internas","desarrollo de software","informes de estado","actualizaciones de liderazgo","newsletters","respuestas a preguntas frecuentes","informes de incidentes","actualizaciones de proyectos"],"fr":["communications internes","développement de logiciels","rapports d''état","mises à jour de leadership","newsletters","réponses à des questions fréquentes","rapports d''incident","mises à jour de projet"],"de":["interne Kommunikation","Software-Entwicklung","Statusberichte","Führungsupdates","Newsletters","FAQ-Antworten","Vorfallberichte","Projektupdates"],"pt":["comunicações internas","desenvolvedores","colaboração em equipe","comunicação empresarial","relatórios de status","atualizações de liderança"],"ru":["внутренние коммуникации","разработчики","командная работа","корпоративная коммуникация","отчеты о статусе","обновления руководства"],"ar":["الاتصالات الداخلية","المطورين","التعاون الفريق","التواصل الشركي","تقارير الحالة","تحديثات القيادة"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Corporate Communication Agents requiring standardized internal communication formats and templates.","zh":"适合需要标准化内部沟通格式和模板的企业通信代理。","ja":"標準化された内部コミュニケーション形式とテンプレートを必要とする企業コミュニケーションエージェントに最適です。","ko":"표준화된 내부 커뮤니케이션 형식과 템플릿이 필요한 기업 커뮤니케이션 에이전트에 적합합니다.","es":"Ideal para agentes de comunicación corporativa que requieren formatos y plantillas de comunicación interna estandarizados.","fr":"Idéal pour les agents de communication d''entreprise nécessitant des formats et des modèles de communication interne standardisés.","de":"Ideal für Corporate Communication Agents, die standardisierte interne Kommunikationsformate und -vorlagen benötigen.","pt":"Ideal para Agentes de Comunicação Corporativa que exigem formatos e modelos de comunicação interna padronizados.","ru":"Идеально для корпоративных агентов связи, требующих стандартизированных внутренних форматов и шаблонов коммуникации.","ar":"مثالي للوكلاء الاتصاليون الشركات الذين يتطلبون تنسيقات اتصال داخلية معيارية وقوالب"},"recommendation":{"en":"Empowers agents to generate formatted status reports, leadership updates, and company newsletters using Markdown files and predefined guidelines, streamlining internal communications with consistent 3P updates, FAQ responses, and incident reports.","zh":"赋予代理人使用Markdown文件和预定义指南生成格式化的状态报告、领导更新和公司新闻稿的能力，简化内部沟通，提供一致的3P更新、FAQ响应和事件报告。","ja":"マークダウンファイルと事前に定義されたガイドラインを使用して、フォーマットされたステータスレポート、リーダーシップアップデート、および会社のニュースレターを生成するエージェントをEmpowerし、内部コミュニケーションを簡素化し、一貫した3Pアップデート、FAQの応答、およびインシデントレポートを提供します。","ko":"마크다운 파일과 미리 정의된 지침을 사용하여 형식화된 상태 보고서, 리더십 업데이트 및 회사 뉴스레터를 생성할 수 있는 에이전트를 강화하여 내부 커뮤니케이션을 간소화하고 일관된 3P 업데이트, FAQ 응답 및 사건 보고서를 제공합니다.","es":"Permite a los agentes generar informes de estado formateados, actualizaciones de liderazgo y boletines de la empresa utilizando archivos Markdown y directrices predefinidas, lo que agiliza las comunicaciones internas con actualizaciones 3P consistentes, respuestas a preguntas frecuentes y informes de incidentes.","fr":"Permet aux agents de générer des rapports de statut formatés, des mises à jour de leadership et des bulletins d''entreprise à l''aide de fichiers Markdown et de lignes directrices prédéfinies, ce qui rationalise les communications internes avec des mises à jour 3P cohérentes, des réponses aux questions fréquentes et des rapports d''incident.","de":"Ermächtigt die Agenten, formatierte Statusberichte, Führungskräfte-Updates und Firmennewsletters unter Verwendung von Markdown-Dateien und vordefinierten Richtlinien zu generieren, wodurch die internen Kommunikationen mit konsistenten 3P-Updates, FAQ-Antworten und Incidentberichten rationalisiert werden.","pt":"Habilita os agentes a gerar relatórios de status formatados, atualizações de liderança e boletins da empresa usando arquivos Markdown e diretrizes pré-definidas, otimizando as comunicações internas com atualizações 3P consistentes, respostas de Perguntas Frequentes e relatórios de incidentes.","ru":"Наделяет агентов возможностью генерировать форматированные отчеты о статусе, обновления руководства и корпоративные новости, используя файлы Markdown и предопределенные руководства, оптимизируя внутреннюю коммуникацию с согласованными обновлениями 3P, ответами на часто задаваемые вопросы и отчетами о происшествиях.","ar":"يمنح الوكلاء القدرة على生成 تقارير الحالة المنسقة وتحديثات القيادة والنشرة الشركات باستخدام ملفات Markdown والإرشادات المحددة مسبقًا، ويتوافق مع الاتصالات الداخلية مع تحديثات 3P الثابتة واستجابات الأسئلة الشائعة وتقارير الحوادث"},"useCases":{"en":["Automating weekly status report generation","Creating standardized company newsletters","Generating incident reports with predefined templates"],"zh":["自动化每周状态报告生成","创建标准化的公司新闻稿","使用预定义模板生成事件报告"],"ja":["週次ステータスレポートの生成を自動化する","標準化された会社のニュースレターを作成する","事前に定義されたテンプレートを使用してインシデントレポートを生成する"],"ko":["주간 상태 보고서 생성 자동화","표준화된 회사 뉴스레터 생성","사전 정의된 템플릿을 사용하여 사건 보고서 생성"],"es":["Automatización de la generación de informes de estado semanales","Creación de boletines de la empresa estandarizados","Generación de informes de incidentes con plantillas predefinidas"],"fr":["Automatisation de la génération de rapports de statut hebdomadaires","Création de bulletins d''entreprise standardisés","Génération de rapports d''incident avec des modèles prédéfinis"],"de":["Automatisierung der Generierung von wöchentlichen Statusberichten","Erstellung standardisierter Firmennewsletters","Generierung von Incidentberichten mit vordefinierten Vorlagen"],"pt":["Automatizar a geração de relatórios de status semanais","Criar boletins da empresa padronizados","Gerar relatórios de incidentes com modelos pré-definidos"],"ru":["Автоматизировать генерацию еженедельных отчетов о статусе","Создавать стандартизированные корпоративные новости","Генерировать отчеты о происшествиях с предопределенными шаблонами"],"ar":["توفير توليد تقارير الحالة الأسبوعية","إنشاء نشرة شركات معيارية","توليد تقارير الحوادث مع القوالب المحددة مسبقًا"]},"limitations":{"en":["Requires access to company-specific guideline files","Limited to internal communication formats specified in the guideline files"],"zh":["需要访问公司特定的指南文件","仅限于指南文件中指定的内部通信格式"],"ja":["会社固有のガイドファイルへのアクセスが必要","ガイドファイルに指定された内部コミュニケーション形式のみに限定される"],"ko":["회사 고유의 지침 파일에 접근해야 함","지침 파일에 지정된 내부 커뮤니케이션 형식만으로 제한됨"],"es":["Requiere acceso a archivos de directrices específicos de la empresa","Limitado a formatos de comunicación interna especificados en los archivos de directrices"],"fr":["Nécessite un accès à des fichiers de lignes directrices spécifiques à l''entreprise","Limité aux formats de communication interne spécifiés dans les fichiers de lignes directrices"],"de":["Benötigt Zugriff auf unternehmensspezifische Richtliniendateien","Begrenzt auf interne Kommunikationsformate, die in den Richtliniendateien angegeben sind"],"pt":["Exige acesso a arquivos de diretrizes específicos da empresa","Limitado a formatos de comunicação interna especificados nos arquivos de diretrizes"],"ru":["Требует доступа к файлам руководства, специфичным для компании","Ограничен форматами внутренней коммуникации, указанными в файлах руководства"],"ar":["يتطلب الوصول إلى ملفات الإرشادات الخاصة بالشركة","محدود بتنسيقات الاتصالات الداخلية المحددة في ملفات الإرشادات"]},"version":3},"contentHash":"067b7587a344a928fc6534ef66b1bcd591fc7c26d207ea7ca3334aeb678d6475","repoEtag":"W/\"5456759f24524b9171780a611a3970c1ae87a3d09576f2945661ad98ce4c37da\"","qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/mcp-builder', 'official', 'anthropics', 'skills', 'anthropics/skills', 'mcp-builder', 71981, 7353, 80, '2026-02-20T01:43:22Z', '2026-02-20T01:53:14.323Z', '0f4592dcb53cf2b5d6b7febee6b4152018b565551a1c29e3c612f57b218ab295', '{"id":"anthropics/skills/mcp-builder","name":"mcp-builder","description":{"zh":"MCP Builder 是一个创建高质量 MCP 服务器的指南，用于集成外部 API 或服务。了解 MCP 服务器开发的四个主要阶段","ja":"MCP ビルダーは、外部 API またはサービスを統合するための高品質な MCP サーバーの作成ガイドです。MCP サーバー開発の 4 つの主要段階をご紹介します","ko":"MCP 빌더는 외부 API 또는 서비스를 통합하기 위한 고품질 MCP 서버를 생성하기 위한 가이드입니다. MCP 서버 개발의 4가지 주요 단계를紹介합니다","es":"La guía oficial para crear servidores MCP de alta calidad que permiten a los LLM interactuar con servicios externos","fr":"Le guide officiel pour créer des serveurs MCP de haute qualité qui permettent aux LLM d''interagir avec des services externes","de":"Der offizielle Leitfaden zur Erstellung von hochwertigen MCP-Servern, die es LLMs ermöglichen, mit externen Diensten zu interagieren","pt":"O MCP Builder é uma ferramenta para criar servidores MCP que permitem a interação entre LLMs e serviços externos","ru":"MCP Builder - это инструмент для создания серверов MCP, позволяющих взаимодействовать между LLM и внешними сервисами","ar":"MCP Builder هو أداة لبناء خوادم بروتوكول السياق النموذجي التي تمكن التفاعل بين النماذج اللغوية الكبيرة والخدمات الخارجية","en":"Guide for creating high-quality MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. Use when building MCP servers to integrate external APIs or services, whether in Python (FastMCP) or Node/TypeScript (MCP SDK)."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"mcp-builder","description":"Guide for creating high-quality MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. Use when building MCP servers to integrate external APIs or services, whether in Python (FastMCP) or Node/TypeScript (MCP SDK).","bodyPreview":"# MCP Server Development Guide\n\n## Overview\n\nCreate MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. The quality of an MCP server is measured by how well it enables LLMs to accomplish real-world tasks.\n\n---\n\n# Process\n\n## 🚀 High-Level Workflow\n\nCreating a high-quality MCP server involves four main phases:\n\n### Phase 1: Deep Research and Planning\n\n#### 1.1 Understand Modern MCP Design\n\n**API Coverage vs. Workflow Tools:**\nBalan","body":"# MCP Server Development Guide\n\n## Overview\n\nCreate MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. The quality of an MCP server is measured by how well it enables LLMs to accomplish real-world tasks.\n\n---\n\n# Process\n\n## 🚀 High-Level Workflow\n\nCreating a high-quality MCP server involves four main phases:\n\n### Phase 1: Deep Research and Planning\n\n#### 1.1 Understand Modern MCP Design\n\n**API Coverage vs. Workflow Tools:**\nBalance comprehensive API endpoint coverage with specialized workflow tools. Workflow tools can be more convenient for specific tasks, while comprehensive coverage gives agents flexibility to compose operations. Performance varies by client—some clients benefit from code execution that combines basic tools, while others work better with higher-level workflows. When uncertain, prioritize comprehensive API coverage.\n\n**Tool Naming and Discoverability:**\nClear, descriptive tool names help agents find the right tools quickly. Use consistent prefixes (e.g., `github_create_issue`, `github_list_repos`) and action-oriented naming.\n\n**Context Management:**\nAgents benefit from concise tool descriptions and the ability to filter/paginate results. Design tools that return focused, relevant data. Some clients support code execution which can help agents filter and process data efficiently.\n\n**Actionable Error Messages:**\nError messages should guide agents toward solutions with specific suggestions and next steps.\n\n#### 1.2 Study MCP Protocol Documentation\n\n**Navigate the MCP specification:**\n\nStart with the sitemap to find relevant pages: `https://modelcontextprotocol.io/sitemap.xml`\n\nThen fetch specific pages with `.md` suffix for markdown format (e.g., `https://modelcontextprotocol.io/specification/draft.md`).\n\nKey pages to review:\n- Specification overview and architecture\n- Transport mechanisms (streamable HTTP, stdio)\n- Tool, resource, and prompt definitions\n\n#### 1.3 Study Framework Documentation\n\n**Recommended stack:**\n- **Language**: TypeScript (high-quality SDK support and good compatibility in many execution environments e.g. MCPB. Plus AI models are good at generating TypeScript code, benefiting from its broad usage, static typing and good linting tools)\n- **Transport**: Streamable HTTP for remote servers, using stateless JSON (simpler to scale and maintain, as opposed to stateful sessions and streaming responses). stdio for local servers.\n\n**Load framework documentation:**\n\n- **MCP Best Practices**: [📋 View Best Practices](./reference/mcp_best_practices.md) - Core guidelines\n\n**For TypeScript (recommended):**\n- **TypeScript SDK**: Use WebFetch to load `https://raw.githubusercontent.com/modelcontextprotocol/typescript-sdk/main/README.md`\n- [⚡ TypeScript Guide](./reference/node_mcp_server.md) - TypeScript patterns and examples\n\n**For Python:**\n- **Python SDK**: Use WebFetch to load `https://raw.githubusercontent.com/modelcontextprotocol/python-sdk/main/README.md`\n- [🐍 Python Guide](./reference/python_mcp_server.md) - Python patterns and examples\n\n#### 1.4 Plan Your Implementation\n\n**Understand the API:**\nReview the service''s API documentation to identify key endpoints, authentication requirements, and data models. Use web search and WebFetch as needed.\n\n**Tool Selection:**\nPrioritize comprehensive API coverage. List endpoints to implement, starting with the most common operations.\n\n---\n\n### Phase 2: Implementation\n\n#### 2.1 Set Up Project Structure\n\nSee language-specific guides for project setup:\n- [⚡ TypeScript Guide](./reference/node_mcp_server.md) - Project structure, package.json, tsconfig.json\n- [🐍 Python Guide](./reference/python_mcp_server.md) - Module organization, dependencies\n\n#### 2.2 Implement Core Infrastructure\n\nCreate shared utilities:\n- API client with authentication\n- Error handling helpers\n- Response formatting (JSON/Markdown)\n- Pagination support\n\n#### 2.3 Implement Tools\n\nFor each tool:\n\n**Input Schema:**\n- Use Zod (TypeScript) or Pydantic (Python)\n- Include constraints and clear descriptions\n- Add examples in field descriptions\n\n**Output Schema:**\n- Define `outputSchema` where possible for structured data\n- Use `structuredContent` in tool responses (TypeScript SDK feature)\n- Helps clients understand and process tool outputs\n\n**Tool Description:**\n- Concise summary of functionality\n- Parameter descriptions\n- Return type schema\n\n**Implementation:**\n- Async/await for I/O operations\n- Proper error handling with actionable messages\n- Support pagination where applicable\n- Return both text content and structured data when using modern SDKs\n\n**Annotations:**\n- `readOnlyHint`: true/false\n- `destructiveHint`: true/false\n- `idempotentHint`: true/false\n- `openWorldHint`: true/false\n\n---\n\n### Phase 3: Review and Test\n\n#### 3.1 Code Quality\n\nReview for:\n- No duplicated code (DRY principle)\n- Consistent error handling\n- Full type coverage\n- Clear tool descriptions\n\n#### 3.2 Build and Test\n\n**TypeScript:**\n- Run `npm run build` to verify compilation\n- Test with MCP Inspector: `npx @modelcontextprotocol/inspector`\n\n**Python:**\n- Verify syntax: `python -m py_compile your_server.py`\n- Test with MCP Inspector\n\nSee language-specific guides for detailed testing approaches and quality checklists.\n\n---\n\n### Phase 4: Create Evaluations\n\nAfter implementing your MCP server, create comprehensive evaluations to test its effectiveness.\n\n**Load [✅ Evaluation Guide](./reference/evaluation.md) for complete evaluation guidelines.**\n\n#### 4.1 Understand Evaluation Purpose\n\nUse evaluations to test whether LLMs can effectively use your MCP server to answer realistic, complex questions.\n\n#### 4.2 Create 10 Evaluation Questions\n\nTo create effective evaluations, follow the process outlined in the evaluation guide:\n\n1. **Tool Inspection**: List available tools and understand their capabilities\n2. **Content Exploration**: Use READ-ONLY operations to explore available data\n3. **Question Generation**: Create 10 complex, realistic questions\n4. **Answer Verification**: Solve each question yourself to verify answers\n\n#### 4.3 Evaluation Requirements\n\nEnsure each question is:\n- **Independent**: Not dependent on other questions\n- **Read-only**: Only non-destructive operations required\n- **Complex**: Requiring multiple tool calls and deep exploration\n- **Realistic**: Based on real use cases humans would care about\n- **Verifiable**: Single, clear answer that can be verified by string comparison\n- **Stable**: Answer won''t change over time\n\n#### 4.4 Output Format\n\nCreate an XML file with this structure:\n\n```xml\n<evaluation>\n  <qa_pair>\n    <question>Find discussions about AI model launches with animal codenames. One model needed a specific safety designation that uses the format ASL-X. What number X was being determined for the model named after a spotted wild cat?</question>\n    <answer>3</answer>\n  </qa_pair>\n<!-- More qa_pairs... -->\n</evaluation>\n```\n\n---\n\n# Reference Files\n\n## 📚 Documentation Library\n\nLoad these resources as needed during development:\n\n### Core MCP Documentation (Load First)\n- **MCP Protocol**: Start with sitemap at `https://modelcontextprotocol.io/sitemap.xml`, then fetch specific pages with `.md` suffix\n- [📋 MCP Best Practices](./reference/mcp_best_practices.md) - Universal MCP guidelines including:\n  - Server and tool naming conventions\n  - Response format guidelines (JSON vs Markdown)\n  - Pagination best practices\n  - Transport selection (streamable HTTP vs stdio)\n  - Security and error handling standards\n\n### SDK Documentation (Load During Phase 1/2)\n- **Python SDK**: Fetch from `https://raw.githubusercontent.com/modelcontextprotocol/python-sdk/main/README.md`\n- **TypeScript SDK**: Fetch from `https://raw.githubusercontent.com/modelcontextprotocol/typescript-sdk/main/README.md`\n\n### Language-Specific Implementation Guides (Load During Phase 2)\n- [🐍 Python Implementation Guide](./reference/python_mcp_server.md) - Complete Python/FastMCP guide with:\n  - Server initialization patterns\n  - Pydantic model examples\n  - Tool registration with `@mcp.tool`\n  - Complete working examples\n  - Quality checklist\n\n- [⚡ TypeScript Implementation Guide](./reference/node_mcp_server.md) - Complete TypeScript guide with:\n  - Project structure\n  - Zod schema patterns\n  - Tool registration with `server.registerTool`\n  - Complete working examples\n  - Quality checklist\n\n### Evaluation Guide (Load During Phase 4)\n- [✅ Evaluation Guide](./reference/evaluation.md) - Complete evaluation creation guide with:\n  - Question creation guidelines\n  - Answer verification strategies\n  - XML format specifications\n  - Example questions and answers\n  - Running an evaluation with the provided scripts\n"},"category":"official","lastSynced":"2026-02-20T01:53:14.323Z","seo":{"title":{"zh":"MCP Builder 指南 - 创建高质量 MCP 服务器","ja":"MCP ビルダー ガイド - 高品質 MCP サーバーの作成","ko":"MCP 빌더 가이드 - 고품질 MCP 서버 생성","es":"Guía de creación de servidores MCP de alta calidad","fr":"Guide de création de serveurs MCP de haute qualité","de":"Leitfaden zur Erstellung von hochwertigen MCP-Servern","pt":"Guia de Desenvolvimento de Servidores MCP","ru":"Руководство по созданию серверов MCP","ar":"دليل بناء خوادم بروتوكول السياق النموذجي","en":"mcp-builder"},"description":{"zh":"MCP Builder 是一个创建高质量 MCP 服务器的指南，用于集成外部 API 或服务。了解 MCP 服务器开发的四个主要阶段","ja":"MCP ビルダーは、外部 API またはサービスを統合するための高品質な MCP サーバーの作成ガイドです。MCP サーバー開発の 4 つの主要段階をご紹介します","ko":"MCP 빌더는 외부 API 또는 서비스를 통합하기 위한 고품질 MCP 서버를 생성하기 위한 가이드입니다. MCP 서버 개발의 4가지 주요 단계를紹介합니다","es":"La guía oficial para crear servidores MCP de alta calidad que permiten a los LLM interactuar con servicios externos","fr":"Le guide officiel pour créer des serveurs MCP de haute qualité qui permettent aux LLM d''interagir avec des services externes","de":"Der offizielle Leitfaden zur Erstellung von hochwertigen MCP-Servern, die es LLMs ermöglichen, mit externen Diensten zu interagieren","pt":"O MCP Builder é uma ferramenta para criar servidores MCP que permitem a interação entre LLMs e serviços externos","ru":"MCP Builder - это инструмент для создания серверов MCP, позволяющих взаимодействовать между LLM и внешними сервисами","ar":"MCP Builder هو أداة لبناء خوادم بروتوكول السياق النموذجي التي تمكن التفاعل بين النماذج اللغوية الكبيرة والخدمات الخارجية","en":"Guide for creating high-quality MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. Use whe..."},"definition":{"en":"Guide for creating high-quality MCP (Model Context Protocol) servers that enable LLMs to interact with external services through well-designed tools. Use when building MCP servers to integrate external APIs or services, whether in Python (FastMCP) or Node/TypeScript (MCP SDK)."},"features":{"zh":["创建高质量 MCP 服务器","集成外部 API 或服务","支持 Python (FastMCP) 和 Node/TypeScript (MCP SDK)","四个主要阶段的开发指南","提高大语言模型的实用性"],"ja":["ハイコ質なMCPサーバーの作成","外部 API またはサービスの統合","Python (FastMCP) と Node/TypeScript (MCP SDK) のサポート","4 つの主要段階の開発ガイド","大規模言語モデルの実用性の向上"],"ko":["고품질 MCP 서버 생성","외부 API 또는 서비스 통합","Python (FastMCP) 및 Node/TypeScript (MCP SDK) 지원","4가지 주요 단계의 개발 가이드","대규모 언어 모델의 실용성 향상"],"es":["Integración de APIs y servicios externos","Diseño de herramientas de flujo de trabajo personalizadas","Compatibilidad con Python y Node/TypeScript","Guía paso a paso para la creación de servidores MCP","Optimización para LLMs y servicios en la nube"],"fr":["Intégration d''API et de services externes","Conception d''outils de workflow personnalisés","Compatibilité avec Python et Node/TypeScript","Guide étape par étape pour la création de serveurs MCP","Optimisation pour les LLM et les services cloud"],"de":["Integration von APIs und externen Diensten","Entwurf von benutzerdefinierten Workflow-Tools","Kompatibilität mit Python und Node/TypeScript","Schritt-für-Schritt-Anleitung zur Erstellung von MCP-Servern","Optimierung für LLMs und Cloud-Dienste"],"pt":["Criação de servidores MCP de alta qualidade","Integração com APIs e serviços externos","Suporte a Python e Node/TypeScript","Ferramentas de design de fluxo de trabalho","Otimização para LLMs"],"ru":["Создание серверов MCP высокого качества","Интеграция с внешними API и сервисами","Поддержка Python и Node/TypeScript","Инструменты для проектирования рабочего процесса","Оптимизация для LLM"],"ar":["إنشاء خوادم بروتوكول السياق النموذجي عالية الجودة","الاندماج مع الخدمات الخارجية والواجهات البرمجية","دعم لغات Python و Node/TypeScript","أدوات تصميم سير العمل","تحسين الأداء للنماذج اللغوية الكبيرة"]},"keywords":{"zh":["MCP 服务器","大语言模型","外部服务","API 集成","Python","Node/TypeScript","MCP Builder","服务器开发"],"ja":["MCP サーバー","大規模言語モデル","外部サービス","API 統合","Python","Node/TypeScript","MCP ビルダー","サーバー開発"],"ko":["MCP 서버","대규모 언어 모델","외부 서비스","API 통합","Python","Node/TypeScript","MCP 빌더","서버 개발"],"es":["servidores MCP","LLMs","integración de APIs","diseño de herramientas de flujo de trabajo","Python","Node/TypeScript","servicios en la nube","optimización de servidores","creación de servidores MCP"],"fr":["serveurs MCP","LLMs","intégration d''API","conception d''outils de workflow","Python","Node/TypeScript","services cloud","optimisation de serveurs","création de serveurs MCP"],"de":["MCP-Server","LLMs","API-Integration","Entwurf von Workflow-Tools","Python","Node/TypeScript","Cloud-Dienste","Server-Optimierung","Erstellung von MCP-Servern"],"pt":["MCP Builder","Desenvolvimento de servidores MCP","Integração com APIs","LLMs","Python","Node/TypeScript","Servidores MCP de alta qualidade"],"ru":["MCP Builder","Создание серверов MCP","Интеграция с внешними API","LLM","Python","Node/TypeScript","Серверы MCP высокого качества"],"ar":["MCP Builder","بناء خوادم بروتوكول السياق النموذجي","الاندماج مع الخدمات الخارجية","النماذج اللغوية الكبيرة","Python","Node/TypeScript","خوادم بروتوكول السياق النموذجي عالية الجودة"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing to integrate external services with LLMs through Model Context Protocol servers.","zh":"非常适合需要通过模型上下文协议服务器将外部服务集成到大语言模型的AI代理。","ja":"LLMと外部サービスをモデルコンテキストプロトコルサーバーを介して統合する必要があるAIエージェントに最適です。","ko":"LLM과 외부 서비스를 모델 컨텍스트 프로토콜 서버를 통해 통합해야 하는 AI 에이전트에게 최적입니다.","es":"Perfecto para agentes de IA que necesitan integrar servicios externos con LLM a través de servidores de protocolo de contexto de modelo.","fr":"Parfait pour les agents IA ayant besoin d''intégrer des services externes avec des LLM via des serveurs de protocole de contexte de modèle.","de":"Perfekt für KI-Agenten, die externe Dienste mit LLMs über Model Context Protocol-Server integrieren müssen.","pt":"Perfeito para Agentes de IA que precisam integrar serviços externos com LLMs por meio de servidores do Protocolo de Contexto de Modelo.","ru":"Идеально для агентов ИИ, которым необходимо интегрировать внешние сервисы с LLM через серверы протокола контекста модели.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يحتاجون إلى دمج الخدمات الخارجية مع LLMs من خلال خادم بروتوكول سياق النموذج."},"recommendation":{"en":"Empowers agents to create high-quality MCP servers that enable seamless interactions between LLMs and external APIs or services, utilizing tools like FastMCP in Python or MCP SDK in Node/TypeScript, and leveraging well-designed workflow tools for optimal API coverage.","zh":"赋予代理创建高质量的MCP服务器的能力，使得LLM和外部API或服务之间能够实现无缝交互，利用Python中的FastMCP或Node/TypeScript中的MCP SDK等工具，并利用设计良好的工作流工具以实现最佳的API覆盖。","ja":"エージェントが、LLMと外部APIまたはサービスとのシームレスな相互作用を可能にする、高品質のMCPサーバーを作成できるようにします。PythonのFastMCPやNode/TypeScriptのMCP SDKなどのツールを使用し、最適なAPIカバレッジのためのうまく設計されたワークフロー ツールを活用します。","ko":"에이전트가 LLM과 외부 API 또는 서비스 간의無縫 상호 작용을 가능하게 하는 높은 품질의 MCP 서버를 생성할 수 있도록 합니다. Python의 FastMCP 또는 Node/TypeScript의 MCP SDK와 같은 도구를 사용하고, 최적의 API 커버리지에 대한 잘 설계된 워크플로 도구를 활용합니다.","es":"Habilita a los agentes a crear servidores MCP de alta calidad que permiten interacciones sin problemas entre LLM y APIs o servicios externos, utilizando herramientas como FastMCP en Python o MCP SDK en Node/TypeScript, y aprovechando herramientas de flujo de trabajo bien diseñadas para una cobertura óptima de API.","fr":"Permet aux agents de créer des serveurs MCP de haute qualité qui permettent des interactions sans accroc entre les LLM et les API ou services externes, en utilisant des outils comme FastMCP en Python ou MCP SDK en Node/TypeScript, et en exploitant des outils de workflow bien conçus pour une couverture API optimale.","de":"Ermöglicht es Agenten, hochwertige MCP-Server zu erstellen, die eine nahtlose Interaktion zwischen LLM und externen APIs oder Diensten ermöglichen, indem Tools wie FastMCP in Python oder MCP SDK in Node/TypeScript verwendet werden und gut konzipierte Workflow-Tools für eine optimale API-Abdeckung genutzt werden.","pt":"Habilita agentes a criarem servidores MCP de alta qualidade que permitem interações perfeitas entre LLMs e APIs ou serviços externos, utilizando ferramentas como FastMCP em Python ou MCP SDK em Node/TypeScript e aproveitando ferramentas de fluxo de trabalho bem projetadas para cobertura de API ótima.","ru":"Наделяет агентов возможностью создавать высококачественные серверы MCP, которые обеспечивают бесперебойное взаимодействие между LLM и внешними API или сервисами, используя инструменты, такие как FastMCP на Python или MCP SDK на Node/TypeScript, и используя хорошо спроектированные инструменты рабочего процесса для оптимального охвата API.","ar":"يُمنح الوكيل القدرة على إنشاء خادم MCP عالي الجودة يسمح بالتفاعلات السلسة بين LLMs وواجهات برمجة التطبيقات أو الخدمات الخارجية، باستخدام أدوات مثل FastMCP في Python أو MCP SDK في Node/TypeScript ، واستخدام أدوات سير العمل المصممة جيدًا لتغطية API المثالية."},"useCases":{"en":["Building MCP servers to integrate external APIs","Designing workflow tools for LLMs to accomplish real-world tasks","Developing high-quality MCP servers with optimal API coverage"],"zh":["构建MCP服务器以集成外部API","为LLM设计工作流工具以执行实际任务","开发具有最佳API覆盖的高质量MCP服务器"],"ja":["外部APIを統合するMCPサーバーの構築","実世界のタスクを実行するためのLLM用のワークフロー ツールの設計","最適なAPIカバレッジのある高品質のMCPサーバーの開発"],"ko":["외부 API를 통합하는 MCP 서버 구축","실제 작업을 수행하기 위한 LLM을 위한 워크플로 도구 설계","최적의 API 커버리지가 있는 고품질 MCP 서버 개발"],"es":["Construir servidores MCP para integrar APIs externas","Diseñar herramientas de flujo de trabajo para LLM para realizar tareas del mundo real","Desarrollar servidores MCP de alta calidad con cobertura óptima de API"],"fr":["Créer des serveurs MCP pour intégrer des API externes","Concevoir des outils de workflow pour les LLM pour accomplir des tâches du monde réel","Développer des serveurs MCP de haute qualité avec une couverture API optimale"],"de":["MCP-Server zum Integrieren externer APIs erstellen","Workflow-Tools für LLMs zur Erledigung von Realweltaufgaben entwerfen","Hochwertige MCP-Server mit optimaler API-Abdeckung entwickeln"],"pt":["Construir servidores MCP para integrar APIs externas","Projetar ferramentas de fluxo de trabalho para LLMs realizar tarefas do mundo real","Desenvolver servidores MCP de alta qualidade com cobertura de API ótima"],"ru":["Создание серверов MCP для интеграции внешних API","Разработка инструментов рабочего процесса для LLM для выполнения реальных задач","Разработка высококачественных серверов MCP с оптимальным охватом API"],"ar":["بناء خوادم MCP لدمج واجهات برمجة التطبيقات الخارجية","تصميم أدوات سير العمل لتحقيق LLMs للمهام العالية في العالم الحقيقي","تطوير خوادم MCP عالية الجودة مع تغطية API مثالية"]},"limitations":{"en":["Requires knowledge of Model Context Protocol","Limited to Python and Node/TypeScript implementations","Dependent on quality of external APIs or services integrated"],"zh":["需要模型上下文协议的知识","仅限Python和Node/TypeScript实现","依赖于集成的外部API或服务的质量"],"ja":["モデルコンテキストプロトコルの知識が必要","PythonとNode/TypeScriptへの実装のみ","統合された外部APIまたはサービスの品質に依存"],"ko":["모델 컨텍스트 프로토콜에 대한 지식이 필요","Python 및 Node/TypeScript 구현만","통합된 외부 API 또는 서비스의 품질에 의존"],"es":["Requiere conocimiento del Protocolo de Contexto de Modelo","Limitado a implementaciones en Python y Node/TypeScript","Dependiente de la calidad de las APIs o servicios externos integrados"],"fr":["Nécessite des connaissances du Protocole de Contexte de Modèle","Limité aux implémentations Python et Node/TypeScript","Dépend de la qualité des API ou services externes intégrés"],"de":["Benötigt Kenntnisse des Model Context Protocol","Begrenzt auf Python- und Node/TypeScript-Implementierungen","Abhängig von der Qualität der integrierten externen APIs oder Dienste"],"pt":["Requer conhecimento do Protocolo de Contexto de Modelo","Limitado a implementações em Python e Node/TypeScript","Dependente da qualidade das APIs ou serviços externos integrados"],"ru":["Требует знания протокола контекста модели","Ограничен реализациями на Python и Node/TypeScript","Зависит от качества внешних API или сервисов, интегрированных"],"ar":["يتطلب معرفة بروتوكول سياق النموذج","محدود بالتنفيذات في Python و Node/TypeScript ","يعتمد على جودة واجهات برمجة التطبيقات أو الخدمات الخارجية المدمجة"]},"version":3},"contentHash":"0f4592dcb53cf2b5d6b7febee6b4152018b565551a1c29e3c612f57b218ab295","repoEtag":"W/\"5456759f24524b9171780a611a3970c1ae87a3d09576f2945661ad98ce4c37da\"","qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/skill-creator', 'official', 'anthropics', 'skills', 'anthropics/skills', 'skill-creator', 71981, 7353, 80, '2026-02-20T01:43:22Z', '2026-02-20T01:56:09.851Z', 'd57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b', '{"id":"anthropics/skills/skill-creator","name":"skill-creator","description":{"zh":"本指南提供了创建有效技能的指导，帮助开发者扩展Claude的能力","ja":"このガイドでは、開発者がClaudeの機能を拡張するための効果的なスキルを作成する方法について説明します","ko":"이 가이드는 개발자가 Claude의 기능을 확장하는 효과적인 스킬을 생성하는 방법에 대해 설명합니다","es":"El creador de habilidades es una guía para desarrolladores que buscan crear habilidades personalizadas para ampliar las capacidades de Claude","fr":"Le créateur de compétences est un guide pour les développeurs qui souhaitent créer des compétences personnalisées pour étendre les capacités de Claude","de":"Der Fähigkeits-Ersteller ist ein Leitfaden für Entwickler, die benutzerdefinierte Fähigkeiten erstellen möchten, um die Fähigkeiten von Claude zu erweitern","pt":"O Criador de Habilidades fornece orientação para criar habilidades eficazes que estendem as capacidades de Claude. Aprenda a criar pacotes modulares e autocontidos.","ru":"Создатель Навыков предоставляет руководство по созданию эффективных навыков, которые расширяют возможности Claude. Узнайте, как создать модульные и самодостаточные пакеты.","ar":"مبتكر المهارات يقدم إرشادات لإنشاء مهارات فعالة تمتد قدرات برنامج Claude. تعلم كيفية إنشاء حزم مودулярية ومتضمنة ذاتيًا.","en":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"skill-creator","description":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations.","bodyPreview":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi","body":"# Skill Creator\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-step procedures for specific domains\n2. Tool integrations - Instructions for working with specific file formats or APIs\n3. Domain expertise - Company-specific knowledge, schemas, business logic\n4. Bundled resources - Scripts, references, and assets for complex and repetitive tasks\n\n## Core Principles\n\n### Concise is Key\n\nThe context window is a public good. Skills share the context window with everything else Claude needs: system prompt, conversation history, other Skills'' metadata, and the actual user request.\n\n**Default assumption: Claude is already very smart.** Only add context Claude doesn''t already have. Challenge each piece of information: \"Does Claude really need this explanation?\" and \"Does this paragraph justify its token cost?\"\n\nPrefer concise examples over verbose explanations.\n\n### Set Appropriate Degrees of Freedom\n\nMatch the level of specificity to the task''s fragility and variability:\n\n**High freedom (text-based instructions)**: Use when multiple approaches are valid, decisions depend on context, or heuristics guide the approach.\n\n**Medium freedom (pseudocode or scripts with parameters)**: Use when a preferred pattern exists, some variation is acceptable, or configuration affects behavior.\n\n**Low freedom (specific scripts, few parameters)**: Use when operations are fragile and error-prone, consistency is critical, or a specific sequence must be followed.\n\nThink of Claude as exploring a path: a narrow bridge with cliffs needs specific guardrails (low freedom), while an open field allows many routes (high freedom).\n\n### Anatomy of a Skill\n\nEvery skill consists of a required SKILL.md file and optional bundled resources:\n\n```\nskill-name/\n├── SKILL.md (required)\n│   ├── YAML frontmatter metadata (required)\n│   │   ├── name: (required)\n│   │   ├── description: (required)\n│   │   └── compatibility: (optional, rarely needed)\n│   └── Markdown instructions (required)\n└── Bundled Resources (optional)\n    ├── scripts/          - Executable code (Python/Bash/etc.)\n    ├── references/       - Documentation intended to be loaded into context as needed\n    └── assets/           - Files used in output (templates, icons, fonts, etc.)\n```\n\n#### SKILL.md (required)\n\nEvery SKILL.md consists of:\n\n- **Frontmatter** (YAML): Contains `name` and `description` fields (required), plus optional fields like `license`, `metadata`, and `compatibility`. Only `name` and `description` are read by Claude to determine when the skill triggers, so be clear and comprehensive about what the skill is and when it should be used. The `compatibility` field is for noting environment requirements (target product, system packages, etc.) but most skills don''t need it.\n- **Body** (Markdown): Instructions and guidance for using the skill. Only loaded AFTER the skill triggers (if at all).\n\n#### Bundled Resources (optional)\n\n##### Scripts (`scripts/`)\n\nExecutable code (Python/Bash/etc.) for tasks that require deterministic reliability or are repeatedly rewritten.\n\n- **When to include**: When the same code is being rewritten repeatedly or deterministic reliability is needed\n- **Example**: `scripts/rotate_pdf.py` for PDF rotation tasks\n- **Benefits**: Token efficient, deterministic, may be executed without loading into context\n- **Note**: Scripts may still need to be read by Claude for patching or environment-specific adjustments\n\n##### References (`references/`)\n\nDocumentation and reference material intended to be loaded as needed into context to inform Claude''s process and thinking.\n\n- **When to include**: For documentation that Claude should reference while working\n- **Examples**: `references/finance.md` for financial schemas, `references/mnda.md` for company NDA template, `references/policies.md` for company policies, `references/api_docs.md` for API specifications\n- **Use cases**: Database schemas, API documentation, domain knowledge, company policies, detailed workflow guides\n- **Benefits**: Keeps SKILL.md lean, loaded only when Claude determines it''s needed\n- **Best practice**: If files are large (>10k words), include grep search patterns in SKILL.md\n- **Avoid duplication**: Information should live in either SKILL.md or references files, not both. Prefer references files for detailed information unless it''s truly core to the skill—this keeps SKILL.md lean while making information discoverable without hogging the context window. Keep only essential procedural instructions and workflow guidance in SKILL.md; move detailed reference material, schemas, and examples to references files.\n\n##### Assets (`assets/`)\n\nFiles not intended to be loaded into context, but rather used within the output Claude produces.\n\n- **When to include**: When the skill needs files that will be used in the final output\n- **Examples**: `assets/logo.png` for brand assets, `assets/slides.pptx` for PowerPoint templates, `assets/frontend-template/` for HTML/React boilerplate, `assets/font.ttf` for typography\n- **Use cases**: Templates, images, icons, boilerplate code, fonts, sample documents that get copied or modified\n- **Benefits**: Separates output resources from documentation, enables Claude to use files without loading them into context\n\n#### What to Not Include in a Skill\n\nA skill should only contain essential files that directly support its functionality. Do NOT create extraneous documentation or auxiliary files, including:\n\n- README.md\n- INSTALLATION_GUIDE.md\n- QUICK_REFERENCE.md\n- CHANGELOG.md\n- etc.\n\nThe skill should only contain the information needed for an AI agent to do the job at hand. It should not contain auxilary context about the process that went into creating it, setup and testing procedures, user-facing documentation, etc. Creating additional documentation files just adds clutter and confusion.\n\n### Progressive Disclosure Design Principle\n\nSkills use a three-level loading system to manage context efficiently:\n\n1. **Metadata (name + description)** - Always in context (~100 words)\n2. **SKILL.md body** - When skill triggers (<5k words)\n3. **Bundled resources** - As needed by Claude (Unlimited because scripts can be executed without reading into context window)\n\n#### Progressive Disclosure Patterns\n\nKeep SKILL.md body to the essentials and under 500 lines to minimize context bloat. Split content into separate files when approaching this limit. When splitting out content into other files, it is very important to reference them from SKILL.md and describe clearly when to read them, to ensure the reader of the skill knows they exist and when to use them.\n\n**Key principle:** When a skill supports multiple variations, frameworks, or options, keep only the core workflow and selection guidance in SKILL.md. Move variant-specific details (patterns, examples, configuration) into separate reference files.\n\n**Pattern 1: High-level guide with references**\n\n```markdown\n# PDF Processing\n\n## Quick start\n\nExtract text with pdfplumber:\n[code example]\n\n## Advanced features\n\n- **Form filling**: See [FORMS.md](FORMS.md) for complete guide\n- **API reference**: See [REFERENCE.md](REFERENCE.md) for all methods\n- **Examples**: See [EXAMPLES.md](EXAMPLES.md) for common patterns\n```\n\nClaude loads FORMS.md, REFERENCE.md, or EXAMPLES.md only when needed.\n\n**Pattern 2: Domain-specific organization**\n\nFor Skills with multiple domains, organize content by domain to avoid loading irrelevant context:\n\n```\nbigquery-skill/\n├── SKILL.md (overview and navigation)\n└── reference/\n    ├── finance.md (revenue, billing metrics)\n    ├── sales.md (opportunities, pipeline)\n    ├── product.md (API usage, features)\n    └── marketing.md (campaigns, attribution)\n```\n\nWhen a user asks about sales metrics, Claude only reads sales.md.\n\nSimilarly, for skills supporting multiple frameworks or variants, organize by variant:\n\n```\ncloud-deploy/\n├── SKILL.md (workflow + provider selection)\n└── references/\n    ├── aws.md (AWS deployment patterns)\n    ├── gcp.md (GCP deployment patterns)\n    └── azure.md (Azure deployment patterns)\n```\n\nWhen the user chooses AWS, Claude only reads aws.md.\n\n**Pattern 3: Conditional details**\n\nShow basic content, link to advanced content:\n\n```markdown\n# DOCX Processing\n\n## Creating documents\n\nUse docx-js for new documents. See [DOCX-JS.md](DOCX-JS.md).\n\n## Editing documents\n\nFor simple edits, modify the XML directly.\n\n**For tracked changes**: See [REDLINING.md](REDLINING.md)\n**For OOXML details**: See [OOXML.md](OOXML.md)\n```\n\nClaude reads REDLINING.md or OOXML.md only when the user needs those features.\n\n**Important guidelines:**\n\n- **Avoid deeply nested references** - Keep references one level deep from SKILL.md. All reference files should link directly from SKILL.md.\n- **Structure longer reference files** - For files longer than 100 lines, include a table of contents at the top so Claude can see the full scope when previewing.\n\n## Skill Creation Process\n\nSkill creation involves these steps:\n\n1. Understand the skill with concrete examples\n2. Plan reusable skill contents (scripts, references, assets)\n3. Initialize the skill (run init_skill.py)\n4. Edit the skill (implement resources and write SKILL.md)\n5. Package the skill (run package_skill.py)\n6. Iterate based on real usage\n\nFollow these steps in order, skipping only if there is a clear reason why they are not applicable.\n\n### Step 1: Understanding the Skill with Concrete Examples\n\nSkip this step only when the skill''s usage patterns are already clearly understood. It remains valuable even when working with an existing skill.\n\nTo create an effective skill, clearly understand concrete examples of how the skill will be used. This understanding can come from either direct user examples or generated examples that are validated with user feedback.\n\nFor example, when building an image-editor skill, relevant questions include:\n\n- \"What functionality should the image-editor skill support? Editing, rotating, anything else?\"\n- \"Can you give some examples of how this skill would be used?\"\n- \"I can imagine users asking for things like ''Remove the red-eye from this image'' or ''Rotate this image''. Are there other ways you imagine this skill being used?\"\n- \"What would a user say that should trigger this skill?\"\n\nTo avoid overwhelming users, avoid asking too many questions in a single message. Start with the most important questions and follow up as needed for better effectiveness.\n\nConclude this step when there is a clear sense of the functionality the skill should support.\n\n### Step 2: Planning the Reusable Skill Contents\n\nTo turn concrete examples into an effective skill, analyze each example by:\n\n1. Considering how to execute on the example from scratch\n2. Identifying what scripts, references, and assets would be helpful when executing these workflows repeatedly\n\nExample: When building a `pdf-editor` skill to handle queries like \"Help me rotate this PDF,\" the analysis shows:\n\n1. Rotating a PDF requires re-writing the same code each time\n2. A `scripts/rotate_pdf.py` script would be helpful to store in the skill\n\nExample: When designing a `frontend-webapp-builder` skill for queries like \"Build me a todo app\" or \"Build me a dashboard to track my steps,\" the analysis shows:\n\n1. Writing a frontend webapp requires the same boilerplate HTML/React each time\n2. An `assets/hello-world/` template containing the boilerplate HTML/React project files would be helpful to store in the skill\n\nExample: When building a `big-query` skill to handle queries like \"How many users have logged in today?\" the analysis shows:\n\n1. Querying BigQuery requires re-discovering the table schemas and relationships each time\n2. A `references/schema.md` file documenting the table schemas would be helpful to store in the skill\n\nTo establish the skill''s contents, analyze each concrete example to create a list of the reusable resources to include: scripts, references, and assets.\n\n### Step 3: Initializing the Skill\n\nAt this point, it is time to actually create the skill.\n\nSkip this step only if the skill being developed already exists, and iteration or packaging is needed. In this case, continue to the next step.\n\nWhen creating a new skill from scratch, always run the `init_skill.py` script. The script conveniently generates a new template skill directory that automatically includes everything a skill requires, making the skill creation process much more efficient and reliable.\n\nUsage:\n\n```bash\nscripts/init_skill.py <skill-name> --path <output-directory>\n```\n\nThe script:\n\n- Creates the skill directory at the specified path\n- Generates a SKILL.md template with proper frontmatter and TODO placeholders\n- Creates example resource directories: `scripts/`, `references/`, and `assets/`\n- Adds example files in each directory that can be customized or deleted\n\nAfter initialization, customize or remove the generated SKILL.md and example files as needed.\n\n### Step 4: Edit the Skill\n\nWhen editing the (newly-generated or existing) skill, remember that the skill is being created for another instance of Claude to use. Include information that would be beneficial and non-obvious to Claude. Consider what procedural knowledge, domain-specific details, or reusable assets would help another Claude instance execute these tasks more effectively.\n\n#### Learn Proven Design Patterns\n\nConsult these helpful guides based on your skill''s needs:\n\n- **Multi-step processes**: See references/workflows.md for sequential workflows and conditional logic\n- **Specific output formats or quality standards**: See references/output-patterns.md for template and example patterns\n\nThese files contain established best practices for effective skill design.\n\n#### Start with Reusable Skill Contents\n\nTo begin implementation, start with the reusable resources identified above: `scripts/`, `references/`, and `assets/` files. Note that this step may require user input. For example, when implementing a `brand-guidelines` skill, the user may need to provide brand assets or templates to store in `assets/`, or documentation to store in `references/`.\n\nAdded scripts must be tested by actually running them to ensure there are no bugs and that the output matches what is expected. If there are many similar scripts, only a representative sample needs to be tested to ensure confidence that they all work while balancing time to completion.\n\nAny example files and directories not needed for the skill should be deleted. The initialization script creates example files in `scripts/`, `references/`, and `assets/` to demonstrate structure, but most skills won''t need all of them.\n\n#### Update SKILL.md\n\n**Writing Guidelines:** Always use imperative/infinitive form.\n\n##### Frontmatter\n\nWrite the YAML frontmatter with `name` and `description`:\n\n- `name`: The skill name\n- `description`: This is the primary triggering mechanism for your skill, and helps Claude understand when to use the skill.\n  - Include both what the Skill does and specific triggers/contexts for when to use it.\n  - Include all \"when to use\" information here - Not in the body. The body is only loaded after triggering, so \"When to Use This Skill\" sections in the body are not helpful to Claude.\n  - Example description for a `docx` skill: \"Comprehensive document creation, editing, and analysis with support for tracked changes, comments, formatting preservation, and text extraction. Use when Claude needs to work with professional documents (.docx files) for: (1) Creating new documents, (2) Modifying or editing content, (3) Working with tracked changes, (4) Adding comments, or any other document tasks\"\n\nDo not include any other fields in YAML frontmatter.\n\n##### Body\n\nWrite instructions for using the skill and its bundled resources.\n\n### Step 5: Packaging a Skill\n\nOnce development of the skill is complete, it must be packaged into a distributable .skill file that gets shared with the user. The packaging process automatically validates the skill first to ensure it meets all requirements:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder>\n```\n\nOptional output directory specification:\n\n```bash\nscripts/package_skill.py <path/to/skill-folder> ./dist\n```\n\nThe packaging script will:\n\n1. **Validate** the skill automatically, checking:\n\n   - YAML frontmatter format and required fields\n   - Skill naming conventions and directory structure\n   - Description completeness and quality\n   - File organization and resource references\n\n2. **Package** the skill if validation passes, creating a .skill file named after the skill (e.g., `my-skill.skill`) that includes all files and maintains the proper directory structure for distribution. The .skill file is a zip file with a .skill extension.\n\nIf validation fails, the script will report the errors and exit without creating a package. Fix any validation errors and run the packaging command again.\n\n### Step 6: Iterate\n\nAfter testing the skill, users may request improvements. Often this happens right after using the skill, with fresh context of how the skill performed.\n\n**Iteration workflow:**\n\n1. Use the skill on real tasks\n2. Notice struggles or inefficiencies\n3. Identify how SKILL.md or bundled resources should be updated\n4. Implement changes and test again\n"},"category":"official","lastSynced":"2026-02-20T01:56:09.851Z","seo":{"title":{"zh":"技能创建指南 - 扩展Claude能力","ja":"スキル作成ガイド - Claudeの機能を拡張","ko":"스킬 생성 가이드 - Claude 기능 확장","es":"Creador de habilidades para desarrolladores","fr":"Créateur de compétences pour développeurs","de":"Fähigkeits-Ersteller für Entwickler","pt":"Criador de Habilidades: Guia para Desenvolvedores","ru":"Создатель Навыков: Руководство для Разработчиков","ar":"مبتكر المهارات: دليل للمطورين","en":"skill-creator"},"description":{"zh":"本指南提供了创建有效技能的指导，帮助开发者扩展Claude的能力","ja":"このガイドでは、開発者がClaudeの機能を拡張するための効果的なスキルを作成する方法について説明します","ko":"이 가이드는 개발자가 Claude의 기능을 확장하는 효과적인 스킬을 생성하는 방법에 대해 설명합니다","es":"El creador de habilidades es una guía para desarrolladores que buscan crear habilidades personalizadas para ampliar las capacidades de Claude","fr":"Le créateur de compétences est un guide pour les développeurs qui souhaitent créer des compétences personnalisées pour étendre les capacités de Claude","de":"Der Fähigkeits-Ersteller ist ein Leitfaden für Entwickler, die benutzerdefinierte Fähigkeiten erstellen möchten, um die Fähigkeiten von Claude zu erweitern","pt":"O Criador de Habilidades fornece orientação para criar habilidades eficazes que estendem as capacidades de Claude. Aprenda a criar pacotes modulares e autoco...","ru":"Создатель Навыков предоставляет руководство по созданию эффективных навыков, которые расширяют возможности Claude. Узнайте, как создать модульные и самодоста...","ar":"مبتكر المهارات يقدم إرشادات لإنشاء مهارات فعالة تمتد قدرات برنامج Claude. تعلم كيفية إنشاء حزم مودулярية ومتضمنة ذاتيًا.","en":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capab..."},"definition":{"en":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations."},"features":{"zh":["提供专门的知识和工作流","扩展Claude的能力","支持工具集成","模块化、自包含的包","易于创建和更新"],"ja":["専門知識とワークフローを提供","Claudeの機能を拡張","ツールの統合をサポート","モジュール化された自包含パッケージ","簡単に作成および更新"],"ko":["전문 지식과 워크플로 제공","Claude의 기능 확장","도구 통합 지원","모듈화된 자체 포함 패키지","쉽게 생성 및 업데이트"],"es":["Guía para crear habilidades personalizadas","Amplía las capacidades de Claude con conocimientos especializados","Permite la integración de flujos de trabajo y herramientas","Facilita la creación de habilidades para dominios específicos","Ofrece una forma de transformar a Claude en un agente especializado"],"fr":["Guide pour créer des compétences personnalisées","Étend les capacités de Claude avec des connaissances spécialisées","Permet l''intégration de flux de travail et d''outils","Facilite la création de compétences pour des domaines spécifiques","Offre un moyen de transformer Claude en un agent spécialisé"],"de":["Anleitung zum Erstellen benutzerdefinierter Fähigkeiten","Erweitert die Fähigkeiten von Claude mit spezialisierten Kenntnissen","Ermöglicht die Integration von Workflows und Tools","Erleichtert die Erstellung von Fähigkeiten für spezifische Domänen","Bietet eine Möglichkeit, Claude in einen spezialisierten Agenten zu verwandeln"],"pt":["Criação de habilidades personalizadas","Extensão das capacidades de Claude","Pacotes modulares e autocontidos","Conhecimento especializado","Workflows especializados"],"ru":["Создание индивидуальных навыков","Расширение возможностей Claude","Модульные и самодостаточные пакеты","Специализированные знания","Специализированные рабочие процессы"],"ar":["إنشاء مهارات مخصصة","توسيع قدرات برنامج Claude","حزم مودулярية ومتضمنة ذاتيًا","معرفة متخصصة","عمليات عمل متخصصة"]},"keywords":{"zh":["技能创建","Claude扩展","模块化包","自包含包","工具集成","开发者指南"],"ja":["スキル作成","Claude拡張","モジュール化パッケージ","自包含パッケージ","ツール統合","開発者ガイド"],"ko":["스킬 생성","Claude 확장","모듈화 패키지","자체 포함 패키지","도구 통합","개발자 가이드"],"es":["creador de habilidades","desarrollo de habilidades","ampliación de capacidades","conocimientos especializados","flujos de trabajo","integración de herramientas","desarrollo de software","IA y machine learning"],"fr":["créateur de compétences","développement de compétences","extension de capacités","connaissances spécialisées","flux de travail","intégration d''outils","développement de logiciels","IA et apprentissage automatique"],"de":["Fähigkeits-Ersteller","Fähigkeits-Entwicklung","Fähigkeits-Erweiterung","spezialisierte Kenntnisse","Workflows","Tool-Integration","Software-Entwicklung","KI und Machine Learning"],"pt":["criador de habilidades","desenvolvedores","Claude","habilidades personalizadas","conhecimento especializado","workflows especializados"],"ru":["создатель навыков","разработчики","Claude","индивидуальные навыки","специализированные знания","специализированные рабочие процессы"],"ar":["مبتكر المهارات","المطورين","برنامج Claude","مهارات مخصصة","معرفة متخصصة","عمليات عمل متخصصة"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing to extend Claude''s capabilities with specialized knowledge and workflows.","zh":"非常适合需要通过专门知识和工作流扩展 Claude 功能的开发人员代理。","ja":"Claude の機能を専門知識とワークフローで拡張する必要がある開発者エージェントに最適です。","ko":"클라우드의 기능을 전문 지식과 워크플로우로 확장해야 하는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan ampliar las capacidades de Claude con conocimientos y flujos de trabajo especializados.","fr":"Parfait pour les agents de développement qui ont besoin d''étendre les capacités de Claude avec des connaissances et des flux de travail spécialisés.","de":"Perfekt für Entwickleragenten, die Claudes Fähigkeiten mit spezialisierten Kenntnissen und Workflows erweitern müssen.","pt":"Perfeito para Agentes de Desenvolvedores que precisam estender as capacidades do Claude com conhecimento especializado e fluxos de trabalho.","ru":"Идеально подходит для агентов-разработчиков, которым необходимо расширить возможности Claude с помощью специализированных знаний и рабочих процессов.","ar":"مثالي لوسائل وكلاء المطورين الذين يحتاجون إلى توسيع قدرات كلود مع المعارف المتخصصة والعمليات العمال"},"recommendation":{"en":"Empowers agents to create modular, self-contained packages that integrate specialized workflows, tools, and procedural knowledge, effectively transforming Claude into a specialized agent using multi-step workflows and tool integrations.","zh":"赋予代理创建模块化、自包含的软件包的能力，这些软件包集成了专门的工作流、工具和程序知识，有效地将 Claude 转变为使用多步骤工作流和工具集成的专用代理。","ja":"エージェントがモジュール化された自己完結型のパッケージを作成できるようにし、これらのパッケージは専門のワークフロー、ツール、および手続き知識を統合し、Claude をマルチステップのワークフローとツールの統合を使用する専用エージェントに効果的に変換します。","ko":"에이전트가 모듈화된 자체 완결형 패키지를 생성할 수 있도록 해줌으로써 Claude를 다중 단계 워크플로우와 툴 통합을 사용하는 전문 에이전트로 효과적으로 변환하며, 이러한 패키지는 전문 워크플로우, 툴 및 절차 지식을 통합합니다.","es":"Permite a los agentes crear paquetes modulares y autocontenidos que integran flujos de trabajo especializados, herramientas y conocimientos procedimentales, transformando efectivamente a Claude en un agente especializado mediante flujos de trabajo de varios pasos y la integración de herramientas.","fr":"Permet aux agents de créer des packages modulaires et autocontenus qui intègrent des flux de travail spécialisés, des outils et des connaissances procédurales, transformant effectivement Claude en un agent spécialisé en utilisant des flux de travail à plusieurs étapes et des intégrations d''outils.","de":"Ermöglicht es Agenten, modulare, selbstenthaltene Pakete zu erstellen, die spezialisierte Workflows, Tools und prozedurales Wissen integrieren, und verwandelt Claude damit effektiv in einen spezialisierten Agenten unter Verwendung von Mehrschritt-Workflows und Tool-Integrationen.","pt":"Habilita os agentes a criar pacotes modulares, autocontidos que integram fluxos de trabalho especializados, ferramentas e conhecimento procedural, transformando efetivamente o Claude em um agente especializado usando fluxos de trabalho em várias etapas e integrações de ferramentas.","ru":"Позволяет агентам создавать модульные, самодостаточные пакеты, которые интегрируют специализированные рабочие процессы, инструменты и процедурные знания, эффективно превращая Claude в специализированного агента с использованием многоступенчатых рабочих процессов и интеграций инструментов.","ar":"تمكّن الوكلاء من إنشاء حزم موديولاريّة، مُحكمة الذات تُدمج عمليات عمل متخصصة وأدوات ومعارف إجرائية، وتحوّل كلود بطريقة فعّالة إلى وكيل متخصص باستخدام عمليات عمل متعدّدة المراحل وتكاملات أدوات"},"useCases":{"en":["Creating domain-specific skills for Claude","Updating existing skills with new workflows and tools","Integrating specialized knowledge into Claude''s capabilities"],"zh":["为 Claude 创建领域特定技能","使用新工作流和工具更新现有技能","将专门知识集成到 Claude 的功能中"],"ja":["Claude 用のドメイン固有スキルを作成する","新しいワークフローとツールを使用して既存のスキルを更新する","専門知識を Claude の機能に統合する"],"ko":["클라우드의 도메인 특정 스킬 생성","새로운 워크플로우와 툴을 사용하여 기존 스킬 업데이트","전문 지식을 클라우드의 기능에 통합"],"es":["Crear habilidades específicas del dominio para Claude","Actualizar habilidades existentes con nuevos flujos de trabajo y herramientas","Integrar conocimientos especializados en las capacidades de Claude"],"fr":["Créer des compétences spécifiques au domaine pour Claude","Mettre à jour les compétences existantes avec de nouveaux flux de travail et outils","Intégrer des connaissances spécialisées dans les capacités de Claude"],"de":["Erstellung von domänenspezifischen Fähigkeiten für Claude","Aktualisierung bestehender Fähigkeiten mit neuen Workflows und Tools","Integration von spezialisiertem Wissen in Claudes Fähigkeiten"],"pt":["Criar habilidades específicas de domínio para o Claude","Atualizar habilidades existentes com novos fluxos de trabalho e ferramentas","Integrar conhecimento especializado nas capacidades do Claude"],"ru":["Создание домен-специфических навыков для Claude","Обновление существующих навыков с новыми рабочими процессами и инструментами","Интеграция специализированных знаний в возможности Claude"],"ar":["إنشاء مهارات محددة للنطاق لمساعد كلود","تحديث المهارات الحالية مع عمليات عمل جديدة وأدوات","تكامل المعارف المتخصصة في إمكانيات كلود"]},"limitations":{"en":["Requires understanding of Claude''s architecture and skill development guidelines","Limited to extending Claude''s capabilities within its existing framework"],"zh":["需要了解 Claude 的架构和技能开发指南","仅限于在现有框架内扩展 Claude 的功能"],"ja":["Claude のアーキテクチャとスキル開発ガイドラインを理解する必要がある","Claude の機能を既存のフレームワーク内で拡張することのみに限定される"],"ko":["클라우드의 아키텍처와 스킬 개발 가이드라인을 이해해야 함","클라우드의 기능을 기존 프레임워크 내에서 확장하는 것만으로 제한됨"],"es":["Requiere comprensión de la arquitectura de Claude y las directrices de desarrollo de habilidades","Limitado a ampliar las capacidades de Claude dentro de su marco existente"],"fr":["Nécessite une compréhension de l''architecture de Claude et des lignes directrices de développement de compétences","Limité à l''extension des capacités de Claude dans son cadre existant"],"de":["Benötigt ein Verständnis von Claudes Architektur und den Richtlinien für die Entwicklung von Fähigkeiten","Begrenzt auf die Erweiterung von Claudes Fähigkeiten innerhalb seines bestehenden Rahmens"],"pt":["Exige compreensão da arquitetura do Claude e diretrizes de desenvolvimento de habilidades","Limitado à extensão das capacidades do Claude dentro de sua estrutura existente"],"ru":["Требует понимания архитектуры Claude и руководств по разработке навыков","Ограничен расширением возможностей Claude в рамках его существующей структуры"],"ar":["يتطلب فهمًا لهيئة كلود ومرشدات تطوير المهارات","محدود بتوسيع إمكانيات كلود داخل إطارها الحالي"]},"version":3},"contentHash":"d57b6e3a44535b9c0ef454dad5c86f5df78185fc80a65c7092885b4b5e10f81b","repoEtag":"W/\"5456759f24524b9171780a611a3970c1ae87a3d09576f2945661ad98ce4c37da\"","qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/theme-factory', 'official', 'anthropics', 'skills', 'anthropics/skills', 'theme-factory', 71981, 7353, 80, '2026-02-20T01:43:22Z', '2026-02-20T01:58:21.543Z', 'c35893e221e28895c52143cc11bf30e41a44817796b39d4b15727dadc9796552', '{"id":"anthropics/skills/theme-factory","name":"theme-factory","description":{"zh":"主题工厂是一款专业的文档和幻灯片样式工具，提供10种预设主题和自定义选项。","ja":"テーマファクトリーは、ディスプレイとドキュメントのスタイリングツールです。10種類の事前設定されたテーマとカスタマイズオプションを提供します。","ko":"테마 팩토리는 전문적인 문서 및 프레젠테이션 스타일링 도구입니다. 10가지의 프리셋 테마와 사용자 정의 옵션을 제공합니다.","es":"La Fábrica de temas es una herramienta para dar estilo a artefactos como diapositivas, documentos y páginas de destino con 10 temas preestablecidos","fr":"L''usine de thèmes est un outil pour styliser des artefacts tels que des diapositives, des documents et des pages de destination avec 10 thèmes prédéfinis","de":"Die Theme-Factory ist ein Tool zum Stylen von Artefakten wie Folien, Dokumenten und Zielseiten mit 10 vorgegebenen Themen","pt":"A Fábrica de Temas é uma ferramenta para estilizar artefatos com temas personalizados. Oferece 10 temas pré-definidos e a opção de criar novos temas.","ru":"Фабрика Тем - это инструмент для стилизации артефактов с помощью персонализированных тем. Предлагает 10 предустановленных тем и возможность создания новых тем.","ar":"مصنع السمات هو أداة لتعديل العناصر باستخدام سمات مخصصة. يوفر 10 سمات محددة مسبقا وخيارات لإنشاء سمات جديدة.","en":"Toolkit for styling artifacts with a theme. These artifacts can be slides, docs, reportings, HTML landing pages, etc. There are 10 pre-set themes with colors/fonts that you can apply to any artifact that has been creating, or can generate a new theme on-the-fly."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"theme-factory","description":"Toolkit for styling artifacts with a theme. These artifacts can be slides, docs, reportings, HTML landing pages, etc. There are 10 pre-set themes with colors/fonts that you can apply to any artifact that has been creating, or can generate a new theme on-the-fly.","bodyPreview":"# Theme Factory Skill\n\nThis skill provides a curated collection of professional font and color themes themes, each with carefully selected color palettes and font pairings. Once a theme is chosen, it can be applied to any artifact.\n\n## Purpose\n\nTo apply consistent, professional styling to presentation slide decks, use this skill. Each theme includes:\n- A cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- A distinct visual identity suitable for differe","body":"# Theme Factory Skill\n\nThis skill provides a curated collection of professional font and color themes themes, each with carefully selected color palettes and font pairings. Once a theme is chosen, it can be applied to any artifact.\n\n## Purpose\n\nTo apply consistent, professional styling to presentation slide decks, use this skill. Each theme includes:\n- A cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- A distinct visual identity suitable for different contexts and audiences\n\n## Usage Instructions\n\nTo apply styling to a slide deck or other artifact:\n\n1. **Show the theme showcase**: Display the `theme-showcase.pdf` file to allow users to see all available themes visually. Do not make any modifications to it; simply show the file for viewing.\n2. **Ask for their choice**: Ask which theme to apply to the deck\n3. **Wait for selection**: Get explicit confirmation about the chosen theme\n4. **Apply the theme**: Once a theme has been chosen, apply the selected theme''s colors and fonts to the deck/artifact\n\n## Themes Available\n\nThe following 10 themes are available, each showcased in `theme-showcase.pdf`:\n\n1. **Ocean Depths** - Professional and calming maritime theme\n2. **Sunset Boulevard** - Warm and vibrant sunset colors\n3. **Forest Canopy** - Natural and grounded earth tones\n4. **Modern Minimalist** - Clean and contemporary grayscale\n5. **Golden Hour** - Rich and warm autumnal palette\n6. **Arctic Frost** - Cool and crisp winter-inspired theme\n7. **Desert Rose** - Soft and sophisticated dusty tones\n8. **Tech Innovation** - Bold and modern tech aesthetic\n9. **Botanical Garden** - Fresh and organic garden colors\n10. **Midnight Galaxy** - Dramatic and cosmic deep tones\n\n## Theme Details\n\nEach theme is defined in the `themes/` directory with complete specifications including:\n- Cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- Distinct visual identity suitable for different contexts and audiences\n\n## Application Process\n\nAfter a preferred theme is selected:\n1. Read the corresponding theme file from the `themes/` directory\n2. Apply the specified colors and fonts consistently throughout the deck\n3. Ensure proper contrast and readability\n4. Maintain the theme''s visual identity across all slides\n\n## Create your Own Theme\nTo handle cases where none of the existing themes work for an artifact, create a custom theme. Based on provided inputs, generate a new theme similar to the ones above. Give the theme a similar name describing what the font/color combinations represent. Use any basic description provided to choose appropriate colors/fonts. After generating the theme, show it for review and verification. Following that, apply the theme as described above.\n"},"category":"official","lastSynced":"2026-02-20T01:58:21.543Z","seo":{"title":{"zh":"主题工厂 - 一款专业的文档和幻灯片样式工具","ja":"テーマファクトリー - ディスプレイとドキュメントのスタイリングツール","ko":"테마 팩토리 - 전문적인 문서 및 프레젠테이션 스타일링 도구","es":"Fábrica de temas para desarrolladores","fr":"Usine de thèmes pour développeurs","de":"Theme-Factory für Entwickler","pt":"Fábrica de Temas: Personalize Seus Artefatos","ru":"Фабрика Тем: Настройте Свои Артефакты","ar":"مصنع السمات: قم بتعديل عناصرك","en":"theme-factory"},"description":{"zh":"主题工厂是一款专业的文档和幻灯片样式工具，提供10种预设主题和自定义选项。","ja":"テーマファクトリーは、ディスプレイとドキュメントのスタイリングツールです。10種類の事前設定されたテーマとカスタマイズオプションを提供します。","ko":"테마 팩토리는 전문적인 문서 및 프레젠테이션 스타일링 도구입니다. 10가지의 프리셋 테마와 사용자 정의 옵션을 제공합니다.","es":"La Fábrica de temas es una herramienta para dar estilo a artefactos como diapositivas, documentos y páginas de destino con 10 temas preestablecidos","fr":"L''usine de thèmes est un outil pour styliser des artefacts tels que des diapositives, des documents et des pages de destination avec 10 thèmes prédéfinis","de":"Die Theme-Factory ist ein Tool zum Stylen von Artefakten wie Folien, Dokumenten und Zielseiten mit 10 vorgegebenen Themen","pt":"A Fábrica de Temas é uma ferramenta para estilizar artefatos com temas personalizados. Oferece 10 temas pré-definidos e a opção de criar novos temas.","ru":"Фабрика Тем - это инструмент для стилизации артефактов с помощью персонализированных тем. Предлагает 10 предустановленных тем и возможность создания новых тем.","ar":"مصنع السمات هو أداة لتعديل العناصر باستخدام سمات مخصصة. يوفر 10 سمات محددة مسبقا وخيارات لإنشاء سمات جديدة.","en":"Toolkit for styling artifacts with a theme. These artifacts can be slides, docs, reportings, HTML landing pages, etc. There are 10 pre-set themes with colors..."},"definition":{"en":"Toolkit for styling artifacts with a theme. These artifacts can be slides, docs, reportings, HTML landing pages, etc. There are 10 pre-set themes with colors/fonts that you can apply to any artifact that has been creating, or can generate a new theme on-the-fly."},"features":{"zh":["10种预设主题","自定义主题选项","支持文档和幻灯片样式","专业的字体和颜色搭配","易于使用的界面"],"ja":["10種類の事前設定されたテーマ","カスタマイズオプション","ディスプレイとドキュメントのスタイリングをサポート","プロフェッショナルなフォントとカラーコンビネーション","使いやすいインターフェイス"],"ko":["10가지의 프리셋 테마","사용자 정의 옵션","문서 및 프레젠테이션 스타일링 지원","전문적인 글꼴과 색상 조합","사용하기 쉬운 인터페이스"],"es":["10 temas preestablecidos con paletas de colores y fuentes","Personalización en tiempo real de temas","Aplicación de temas a diapositivas, documentos y páginas de destino","Compatibilidad con diferentes tipos de artefactos","Diseño de temas coherentes y profesionales"],"fr":["10 thèmes prédéfinis avec des palettes de couleurs et des polices","Personnalisation en temps réel des thèmes","Application de thèmes à des diapositives, des documents et des pages de destination","Compatibilité avec différents types d''artefacts","Conception de thèmes cohérents et professionnels"],"de":["10 vorgegebene Themen mit Farbpaletten und Schriftarten","Echtzeit-Anpassung von Themen","Anwendung von Themen auf Folien, Dokumente und Zielseiten","Kompatibilität mit verschiedenen Arten von Artefakten","Entwurf von kohärenten und professionellen Themen"],"pt":["10 temas pré-definidos","Criação de novos temas personalizados","Aplicação de estilos visuais consistentes","Paletas de cores personalizadas","Pares de fontes personalizadas"],"ru":["10 предустановленных тем","Создание новых персонализированных тем","Применение последовательных визуальных стилей","Персонализированные цветовые палитры","Персонализированные пары шрифтов"],"ar":["10 سمات محددة مسبقا","إنشاء سمات جديدة مخصصة","تطبيق أساليب بصرية متسقة","لوحات الألوان المخصصة","أزواج الخطوط المخصصة"]},"keywords":{"zh":["主题工厂","文档样式","幻灯片样式","预设主题","自定义主题","专业字体","颜色搭配","开发者工具"],"ja":["テーマファクトリー","ディスプレイスタイリング","ドキュメントスタイリング","事前設定されたテーマ","カスタマイズオプション","プロフェッショナルなフォント","カラーコンビネーション","開発者ツール"],"ko":["테마 팩토리","문서 스타일링","프레젠테이션 스타일링","프리셋 테마","사용자 정의 옵션","전문적인 글꼴","색상 조합","개발자 도구"],"es":["fábrica de temas","estilo de artefactos","temas preestablecidos","personalización en tiempo real","diapositivas","documentos","páginas de destino","desarrollo web","diseño de temas"],"fr":["usine de thèmes","style d''artefacts","thèmes prédéfinis","personnalisation en temps réel","diapositives","documents","pages de destination","développement web","conception de thèmes"],"de":["Theme-Factory","Styling von Artefakten","vorgegebene Themen","Echtzeit-Anpassung","Folien","Dokumente","Zielseiten","Webentwicklung","Themen-Design"],"pt":["fábrica de temas","estilização de artefatos","temas personalizados","estilos visuais","paletas de cores","pares de fontes","desenvolvimento de software"],"ru":["фабрика тем","стилизация артефактов","персонализированные темы","визуальные стили","цветовые палитры","пары шрифтов","разработка программного обеспечения"],"ar":["مصنع السمات","تعديل العناصر","سمات مخصصة","أساليب بصرية","لوحات الألوان","أزواج الخطوط","تطوير البرمجيات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Presentation Agents needing consistent, professional styling for slides, documents, and HTML landing pages.","zh":"非常适合需要为幻灯片、文档和HTML登陆页面提供一致、专业样式的演示代理。","ja":"プレゼンテーションエージェントがスライド、ドキュメント、HTMLランディングページに一貫したプロフェッショナルなスタイリングを必要とする場合に最適です。","ko":"프레젠테이션 에이전트가 슬라이드, 문서 및 HTML 랜딩 페이지에 일관된 전문가적인 스타일링이 필요한 경우에 적합합니다.","es":"Perfecto para agentes de presentación que necesitan un estilo consistente y profesional para diapositivas, documentos y páginas de aterrizaje HTML.","fr":"Parfait pour les agents de présentation ayant besoin d''un style cohérent et professionnel pour les diapositives, les documents et les pages de destination HTML.","de":"Perfekt für Präsentationsagenten, die ein konsistentes, professionelles Styling für Folien, Dokumente und HTML-Landingpages benötigen.","pt":"Perfeito para Agentes de Apresentação que necessitam de um estilo consistente e profissional para slides, documentos e páginas de destino em HTML.","ru":"Идеально для агентов презентаций, которым требуется последовательный и профессиональный стиль для слайдов, документов и страниц приземления HTML.","ar":"مثالي للوكلاء الذين يحتاجون إلى أسلوب متسقและมِهني لشرائح العرض والوثائق وصفحات الهبوط HTML."},"recommendation":{"en":"Empowers agents to apply cohesive color palettes with hex codes and complementary font pairings for headers and body text, generating a distinct visual identity using HTML and CSS, and supporting various file formats such as .pptx, .docx, and .html.","zh":"赋予代理应用统一的色彩调色板和头部及正文文本的补充字体配对，使用HTML和CSS生成独特的视觉身份，并支持各种文件格式，如.pptx、.docx和.html。","ja":"ヘッダーとボディテキストの補完的なフォントペアリングと16進コードを使用して一貫した色のパレットを適用できるようにエージェントをEmpowerし、HTMLとCSSを使用して独自の視覚的なアイデンティティを生成し、.pptx、.docx、.htmlなどのさまざまなファイル形式をサポートします。","ko":"헤더 및 본문 텍스트의 보완적 폰트 페어링과 16진 코드를 사용하여 일관된 색상 팔레트를 적용할 수 있도록 에이전트를 강화하고 HTML 및 CSS를 사용하여 고유한 시각적 정체성을 생성하며 .pptx, .docx, .html 등의 다양한 파일 형식을 지원합니다.","es":"Permite a los agentes aplicar paletas de colores coherentes con códigos hex y pares de fuentes complementarios para encabezados y texto del cuerpo, generando una identidad visual distintiva utilizando HTML y CSS, y admitiendo varios formatos de archivo como .pptx, .docx y .html.","fr":"Permet aux agents d''appliquer des palettes de couleurs cohérentes avec des codes hex et des paires de polices complémentaires pour les en-têtes et le texte du corps, générant une identité visuelle distinctive en utilisant HTML et CSS, et prenant en charge divers formats de fichiers tels que .pptx, .docx et .html.","de":"Ermächtigt Agenten, kohärente Farbpaletten mit Hex-Codes und komplementären Schriftarten für Überschriften und Fließtext anzuwenden, um eine deutliche visuelle Identität unter Verwendung von HTML und CSS zu erzeugen und verschiedene Dateiformate wie .pptx, .docx und .html zu unterstützen.","pt":"Permite que os agentes apliquem paletas de cores coerentes com códigos hex e pares de fontes complementares para cabeçalhos e texto do corpo, gerando uma identidade visual distinta usando HTML e CSS, e suportando vários formatos de arquivo, como .pptx, .docx e .html.","ru":"Позволяет агентам применять сплоченные цветовые палитры с шестнадцатеричными кодами и дополнительными парами шрифтов для заголовков и текста, генерируя особую визуальную идентичность с помощью HTML и CSS, и поддерживая различные форматы файлов, такие как .pptx, .docx и .html.","ar":"تمكن الوكلاء من تطبيق لوحات ألوان متسقة مع أكواد سداسية عشرية وأزواج خطوط مکملة للرؤوس والنص الجسمي، مما يولد هوية بصرية متميزة باستخدام HTML و CSS، ودعم صيغ ملفات مختلفة مثل .pptx و .docx و .html."},"useCases":{"en":["Styling presentation slide decks with pre-set themes","Generating new themes on-the-fly for unique visual identities","Applying consistent branding to reporting and documentation"],"zh":["使用预设主题样式化演示幻灯片","生成新的主题以创建独特的视觉身份","将一致的品牌应用于报告和文档"],"ja":["事前設定されたテーマでプレゼンテーションスライドをスタイリングする","一意の視覚的なアイデンティティを生成するために新しいテーマを生成する","報告書や文書に一貫したブランディングを適用する"],"ko":["사전 설정된 테마로 프레젠테이션 슬라이드를 스타일링하기","고유한 시각적 정체성을 생성하기 위해 새로운 테마를 생성하기","보고서 및 문서에 일관된 브랜딩을 적용하기"],"es":["Estilismo de diapositivas de presentación con temas preestablecidos","Generación de nuevos temas sobre la marcha para identidades visuales únicas","Aplicación de una marca consistente a informes y documentación"],"fr":["Personnalisation de diapositives de présentation avec des thèmes prédéfinis","Génération de nouveaux thèmes en temps réel pour des identités visuelles uniques","Application d''une marque cohérente à la création de rapports et à la documentation"],"de":["Styling von Präsentationsfolien mit voreingestellten Themen","Erzeugung neuer Themen auf Abruf für einzigartige visuelle Identitäten","Anwendung einer konsistenten Markenidentität auf Berichterstattung und Dokumentation"],"pt":["Estilizar conjuntos de slides de apresentação com temas pré-definidos","Gerar novos temas em tempo real para identidades visuais únicas","Aplicar marcação consistente em relatórios e documentação"],"ru":["Оформление наборов слайдов презентации с предустановленными темами","Генерация новых тем на лету для уникальных визуальных идентичностей","Применение последовательного брендинга к отчетам и документации"],"ar":["تجسيد شرائح العرض مع السمات المحددة مسبقا","توليد سمات جديدة في الوقت الفعلي لهويات بصرية فريدة","تطبيق العلامة التجارية المتسقة على التقارير والتوثيق"]},"limitations":{"en":["Limited to 10 pre-set themes without custom theme import functionality","Requires artifacts to be created or generated before applying themes"],"zh":["仅限10个预设主题，且无自定义主题导入功能","需要在应用主题之前创建或生成构件"],"ja":["カスタムテーマのインポート機能なしで10個の事前設定されたテーマに限定される","アーティファクトを作成または生成してからテーマを適用する必要がある"],"ko":["사용자 정의 테마 가져오기 기능 없이 10개의 사전 설정된 테마로 제한됨","아티팩트를 생성하거나 생성한 후에 테마를 적용해야 함"],"es":["Limitado a 10 temas preestablecidos sin funcionalidad de importación de temas personalizados","Requiere que los artefactos se creen o generen antes de aplicar los temas"],"fr":["Limité à 10 thèmes prédéfinis sans fonctionnalité d''importation de thèmes personnalisés","Nécessite la création ou la génération d''artefacts avant d''appliquer les thèmes"],"de":["Begrenzt auf 10 voreingestellte Themen ohne Funktionalität zum Importieren benutzerdefinierter Themen","Benötigt die Erstellung oder Generierung von Artefakten, bevor Themen angewendet werden können"],"pt":["Limitado a 10 temas pré-definidos sem funcionalidade de importação de tema personalizado","Exige que os artefatos sejam criados ou gerados antes de aplicar os temas"],"ru":["Ограничен 10 предустановленными темами без функции импорта пользовательской темы","Требует создания или генерации артефактов перед применением тем"],"ar":["محدود بـ 10 سمات محددة مسبقا بدون وظيفة استيرادسمة مخصصة","يتطلب إنشاء أو توليد القطع الفنية قبل تطبيق السمات"]},"version":3},"contentHash":"c35893e221e28895c52143cc11bf30e41a44817796b39d4b15727dadc9796552","repoEtag":"W/\"5456759f24524b9171780a611a3970c1ae87a3d09576f2945661ad98ce4c37da\"","qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/xlsx', 'official', 'anthropics', 'skills', 'anthropics/skills', 'xlsx', 71981, 7353, 80, '2026-02-20T01:43:22Z', '2026-02-20T02:01:50.580Z', 'dd316db7785a6be12966c2a2d848931fbf5f518b3cdb0a66fa62ee835ead1cfc', '{"id":"anthropics/skills/xlsx","name":"xlsx","description":{"zh":"xlsx,.csv,.tsv","ja":"xlsx.csv.tsv","ko":"xlsx, .csv, .tsv ","es":"La habilidad xlsx permite editar y crear archivos de hoja de cálculo de manera profesional, asegurando la consistencia y precisión de los datos","fr":"La compétence xlsx permet d''éditer et de créer des fichiers de tableur de manière professionnelle, assurant la cohérence et la précision des données","de":"Die Fähigkeit xlsx ermöglicht die professionelle Bearbeitung und Erstellung von Tabellenkalkulationsdateien, sicherstellend, dass die Daten konsistent und präzise sind","pt":"Nossas habilidades xlsx permitem que você trabalhe com planilhas de forma eficiente. Crie, edite e converta arquivos de planilha com facilidade.","ru":"Наши навыки xlsx позволяют вам работать с таблицами эффективно. Создавайте, редактируйте и конвертируйте файлы таблиц с легкостью.","ar":"تسمح لنا مهارات xlsx بالعمل مع الجداول بسهولة. أنشئ وعدل واقم بسهولة ملفات الجداول.","en":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing .xlsx, .xlsm, .csv, or .tsv file (e.g., adding columns, computing formulas, formatting, charting, cleaning messy data); create a new spreads..."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"xlsx","description":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing .xlsx, .xlsm, .csv, or .tsv file (e.g., adding columns, computing formulas, formatting, charting, cleaning messy data); create a new spreadsheet from scratch or from other data sources; or convert between tabular file formats. Trigger especially when the user references a spreadsheet file by name or path — even casually (like \\the xlsx in my downloads\\) — and wants something done to it or produced from it. Also trigger for cleaning or restructuring messy tabular data files (malformed rows, misplaced headers, junk data) into proper spreadsheets. The deliverable must be a spreadsheet file. Do NOT trigger when the primary deliverable is a Word document, HTML report, standalone Python script, database pipeline, or Google Sheets API integration, even if tabular data is involved.","bodyPreview":"# Requirements for Outputs\n\n## All Excel files\n\n### Professional Font\n- Use a consistent, professional font (e.g., Arial, Times New Roman) for all deliverables unless otherwise instructed by the user\n\n### Zero Formula Errors\n- Every Excel model MUST be delivered with ZERO formula errors (#REF!, #DIV/0!, #VALUE!, #N/A, #NAME?)\n\n### Preserve Existing Templates (when updating templates)\n- Study and EXACTLY match existing format, style, and conventions when modifying files\n- Never impose standardize","body":"# Requirements for Outputs\n\n## All Excel files\n\n### Professional Font\n- Use a consistent, professional font (e.g., Arial, Times New Roman) for all deliverables unless otherwise instructed by the user\n\n### Zero Formula Errors\n- Every Excel model MUST be delivered with ZERO formula errors (#REF!, #DIV/0!, #VALUE!, #N/A, #NAME?)\n\n### Preserve Existing Templates (when updating templates)\n- Study and EXACTLY match existing format, style, and conventions when modifying files\n- Never impose standardized formatting on files with established patterns\n- Existing template conventions ALWAYS override these guidelines\n\n## Financial models\n\n### Color Coding Standards\nUnless otherwise stated by the user or existing template\n\n#### Industry-Standard Color Conventions\n- **Blue text (RGB: 0,0,255)**: Hardcoded inputs, and numbers users will change for scenarios\n- **Black text (RGB: 0,0,0)**: ALL formulas and calculations\n- **Green text (RGB: 0,128,0)**: Links pulling from other worksheets within same workbook\n- **Red text (RGB: 255,0,0)**: External links to other files\n- **Yellow background (RGB: 255,255,0)**: Key assumptions needing attention or cells that need to be updated\n\n### Number Formatting Standards\n\n#### Required Format Rules\n- **Years**: Format as text strings (e.g., \"2024\" not \"2,024\")\n- **Currency**: Use $#,##0 format; ALWAYS specify units in headers (\"Revenue ($mm)\")\n- **Zeros**: Use number formatting to make all zeros \"-\", including percentages (e.g., \"$#,##0;($#,##0);-\")\n- **Percentages**: Default to 0.0% format (one decimal)\n- **Multiples**: Format as 0.0x for valuation multiples (EV/EBITDA, P/E)\n- **Negative numbers**: Use parentheses (123) not minus -123\n\n### Formula Construction Rules\n\n#### Assumptions Placement\n- Place ALL assumptions (growth rates, margins, multiples, etc.) in separate assumption cells\n- Use cell references instead of hardcoded values in formulas\n- Example: Use =B5*(1+$B$6) instead of =B5*1.05\n\n#### Formula Error Prevention\n- Verify all cell references are correct\n- Check for off-by-one errors in ranges\n- Ensure consistent formulas across all projection periods\n- Test with edge cases (zero values, negative numbers)\n- Verify no unintended circular references\n\n#### Documentation Requirements for Hardcodes\n- Comment or in cells beside (if end of table). Format: \"Source: [System/Document], [Date], [Specific Reference], [URL if applicable]\"\n- Examples:\n  - \"Source: Company 10-K, FY2024, Page 45, Revenue Note, [SEC EDGAR URL]\"\n  - \"Source: Company 10-Q, Q2 2025, Exhibit 99.1, [SEC EDGAR URL]\"\n  - \"Source: Bloomberg Terminal, 8/15/2025, AAPL US Equity\"\n  - \"Source: FactSet, 8/20/2025, Consensus Estimates Screen\"\n\n# XLSX creation, editing, and analysis\n\n## Overview\n\nA user may ask you to create, edit, or analyze the contents of an .xlsx file. You have different tools and workflows available for different tasks.\n\n## Important Requirements\n\n**LibreOffice Required for Formula Recalculation**: You can assume LibreOffice is installed for recalculating formula values using the `scripts/recalc.py` script. The script automatically configures LibreOffice on first run, including in sandboxed environments where Unix sockets are restricted (handled by `scripts/office/soffice.py`)\n\n## Reading and analyzing data\n\n### Data analysis with pandas\nFor data analysis, visualization, and basic operations, use **pandas** which provides powerful data manipulation capabilities:\n\n```python\nimport pandas as pd\n\n# Read Excel\ndf = pd.read_excel(''file.xlsx'')  # Default: first sheet\nall_sheets = pd.read_excel(''file.xlsx'', sheet_name=None)  # All sheets as dict\n\n# Analyze\ndf.head()      # Preview data\ndf.info()      # Column info\ndf.describe()  # Statistics\n\n# Write Excel\ndf.to_excel(''output.xlsx'', index=False)\n```\n\n## Excel File Workflows\n\n## CRITICAL: Use Formulas, Not Hardcoded Values\n\n**Always use Excel formulas instead of calculating values in Python and hardcoding them.** This ensures the spreadsheet remains dynamic and updateable.\n\n### ❌ WRONG - Hardcoding Calculated Values\n```python\n# Bad: Calculating in Python and hardcoding result\ntotal = df[''Sales''].sum()\nsheet[''B10''] = total  # Hardcodes 5000\n\n# Bad: Computing growth rate in Python\ngrowth = (df.iloc[-1][''Revenue''] - df.iloc[0][''Revenue'']) / df.iloc[0][''Revenue'']\nsheet[''C5''] = growth  # Hardcodes 0.15\n\n# Bad: Python calculation for average\navg = sum(values) / len(values)\nsheet[''D20''] = avg  # Hardcodes 42.5\n```\n\n### ✅ CORRECT - Using Excel Formulas\n```python\n# Good: Let Excel calculate the sum\nsheet[''B10''] = ''=SUM(B2:B9)''\n\n# Good: Growth rate as Excel formula\nsheet[''C5''] = ''=(C4-C2)/C2''\n\n# Good: Average using Excel function\nsheet[''D20''] = ''=AVERAGE(D2:D19)''\n```\n\nThis applies to ALL calculations - totals, percentages, ratios, differences, etc. The spreadsheet should be able to recalculate when source data changes.\n\n## Common Workflow\n1. **Choose tool**: pandas for data, openpyxl for formulas/formatting\n2. **Create/Load**: Create new workbook or load existing file\n3. **Modify**: Add/edit data, formulas, and formatting\n4. **Save**: Write to file\n5. **Recalculate formulas (MANDATORY IF USING FORMULAS)**: Use the scripts/recalc.py script\n   ```bash\n   python scripts/recalc.py output.xlsx\n   ```\n6. **Verify and fix any errors**: \n   - The script returns JSON with error details\n   - If `status` is `errors_found`, check `error_summary` for specific error types and locations\n   - Fix the identified errors and recalculate again\n   - Common errors to fix:\n     - `#REF!`: Invalid cell references\n     - `#DIV/0!`: Division by zero\n     - `#VALUE!`: Wrong data type in formula\n     - `#NAME?`: Unrecognized formula name\n\n### Creating new Excel files\n\n```python\n# Using openpyxl for formulas and formatting\nfrom openpyxl import Workbook\nfrom openpyxl.styles import Font, PatternFill, Alignment\n\nwb = Workbook()\nsheet = wb.active\n\n# Add data\nsheet[''A1''] = ''Hello''\nsheet[''B1''] = ''World''\nsheet.append([''Row'', ''of'', ''data''])\n\n# Add formula\nsheet[''B2''] = ''=SUM(A1:A10)''\n\n# Formatting\nsheet[''A1''].font = Font(bold=True, color=''FF0000'')\nsheet[''A1''].fill = PatternFill(''solid'', start_color=''FFFF00'')\nsheet[''A1''].alignment = Alignment(horizontal=''center'')\n\n# Column width\nsheet.column_dimensions[''A''].width = 20\n\nwb.save(''output.xlsx'')\n```\n\n### Editing existing Excel files\n\n```python\n# Using openpyxl to preserve formulas and formatting\nfrom openpyxl import load_workbook\n\n# Load existing file\nwb = load_workbook(''existing.xlsx'')\nsheet = wb.active  # or wb[''SheetName''] for specific sheet\n\n# Working with multiple sheets\nfor sheet_name in wb.sheetnames:\n    sheet = wb[sheet_name]\n    print(f\"Sheet: {sheet_name}\")\n\n# Modify cells\nsheet[''A1''] = ''New Value''\nsheet.insert_rows(2)  # Insert row at position 2\nsheet.delete_cols(3)  # Delete column 3\n\n# Add new sheet\nnew_sheet = wb.create_sheet(''NewSheet'')\nnew_sheet[''A1''] = ''Data''\n\nwb.save(''modified.xlsx'')\n```\n\n## Recalculating formulas\n\nExcel files created or modified by openpyxl contain formulas as strings but not calculated values. Use the provided `scripts/recalc.py` script to recalculate formulas:\n\n```bash\npython scripts/recalc.py <excel_file> [timeout_seconds]\n```\n\nExample:\n```bash\npython scripts/recalc.py output.xlsx 30\n```\n\nThe script:\n- Automatically sets up LibreOffice macro on first run\n- Recalculates all formulas in all sheets\n- Scans ALL cells for Excel errors (#REF!, #DIV/0!, etc.)\n- Returns JSON with detailed error locations and counts\n- Works on both Linux and macOS\n\n## Formula Verification Checklist\n\nQuick checks to ensure formulas work correctly:\n\n### Essential Verification\n- [ ] **Test 2-3 sample references**: Verify they pull correct values before building full model\n- [ ] **Column mapping**: Confirm Excel columns match (e.g., column 64 = BL, not BK)\n- [ ] **Row offset**: Remember Excel rows are 1-indexed (DataFrame row 5 = Excel row 6)\n\n### Common Pitfalls\n- [ ] **NaN handling**: Check for null values with `pd.notna()`\n- [ ] **Far-right columns**: FY data often in columns 50+ \n- [ ] **Multiple matches**: Search all occurrences, not just first\n- [ ] **Division by zero**: Check denominators before using `/` in formulas (#DIV/0!)\n- [ ] **Wrong references**: Verify all cell references point to intended cells (#REF!)\n- [ ] **Cross-sheet references**: Use correct format (Sheet1!A1) for linking sheets\n\n### Formula Testing Strategy\n- [ ] **Start small**: Test formulas on 2-3 cells before applying broadly\n- [ ] **Verify dependencies**: Check all cells referenced in formulas exist\n- [ ] **Test edge cases**: Include zero, negative, and very large values\n\n### Interpreting scripts/recalc.py Output\nThe script returns JSON with error details:\n```json\n{\n  \"status\": \"success\",           // or \"errors_found\"\n  \"total_errors\": 0,              // Total error count\n  \"total_formulas\": 42,           // Number of formulas in file\n  \"error_summary\": {              // Only present if errors found\n    \"#REF!\": {\n      \"count\": 2,\n      \"locations\": [\"Sheet1!B5\", \"Sheet1!C10\"]\n    }\n  }\n}\n```\n\n## Best Practices\n\n### Library Selection\n- **pandas**: Best for data analysis, bulk operations, and simple data export\n- **openpyxl**: Best for complex formatting, formulas, and Excel-specific features\n\n### Working with openpyxl\n- Cell indices are 1-based (row=1, column=1 refers to cell A1)\n- Use `data_only=True` to read calculated values: `load_workbook(''file.xlsx'', data_only=True)`\n- **Warning**: If opened with `data_only=True` and saved, formulas are replaced with values and permanently lost\n- For large files: Use `read_only=True` for reading or `write_only=True` for writing\n- Formulas are preserved but not evaluated - use scripts/recalc.py to update values\n\n### Working with pandas\n- Specify data types to avoid inference issues: `pd.read_excel(''file.xlsx'', dtype={''id'': str})`\n- For large files, read specific columns: `pd.read_excel(''file.xlsx'', usecols=[''A'', ''C'', ''E''])`\n- Handle dates properly: `pd.read_excel(''file.xlsx'', parse_dates=[''date_column''])`\n\n## Code Style Guidelines\n**IMPORTANT**: When generating Python code for Excel operations:\n- Write minimal, concise Python code without unnecessary comments\n- Avoid verbose variable names and redundant operations\n- Avoid unnecessary print statements\n\n**For Excel files themselves**:\n- Add comments to cells with complex formulas or important assumptions\n- Document data sources for hardcoded values\n- Include notes for key calculations and model sections"},"category":"official","lastSynced":"2026-02-20T02:01:50.580Z","seo":{"title":{"zh":"xlsx ","ja":"xlsx","ko":"xlsx ","es":"Habilidad xlsx: Edición y Creación de Archivos de Hoja de...","fr":"Compétence xlsx: Édition et Création de Fichiers de Tableur","de":"Fähigkeit xlsx: Bearbeitung und Erstellung von Tabellenka...","pt":"Habilidades xlsx: Trabalhe com Planilhas","ru":"Навыки xlsx: Работа с Таблицами","ar":"مهارات xlsx: العمل مع الجداول","en":"xlsx"},"description":{"zh":"xlsx,.csv,.tsv","ja":"xlsx.csv.tsv","ko":"xlsx, .csv, .tsv ","es":"La habilidad xlsx permite editar y crear archivos de hoja de cálculo de manera profesional, asegurando la consistencia y precisión de los datos","fr":"La compétence xlsx permet d''éditer et de créer des fichiers de tableur de manière professionnelle, assurant la cohérence et la précision des données","de":"Die Fähigkeit xlsx ermöglicht die professionelle Bearbeitung und Erstellung von Tabellenkalkulationsdateien, sicherstellend, dass die Daten konsistent und pr...","pt":"Nossas habilidades xlsx permitem que você trabalhe com planilhas de forma eficiente. Crie, edite e converta arquivos de planilha com facilidade.","ru":"Наши навыки xlsx позволяют вам работать с таблицами эффективно. Создавайте, редактируйте и конвертируйте файлы таблиц с легкостью.","ar":"تسمح لنا مهارات xlsx بالعمل مع الجداول بسهولة. أنشئ وعدل واقم بسهولة ملفات الجداول.","en":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing ..."},"definition":{"en":"Use this skill any time a spreadsheet file is the primary input or output. This means any task where the user wants to: open, read, edit, or fix an existing .xlsx, .xlsm, .csv, or .tsv file (e.g., adding columns, computing formulas, formatting, charting, cleaning messy data); create a new spreadsheet from scratch or from other data sources; or convert between tabular file formats. Trigger especially when the user references a spreadsheet file by name or path — even casually (like \\the xlsx in my downloads\\) — and wants something done to it or produced from it. Also trigger for cleaning or restructuring messy tabular data files (malformed rows, misplaced headers, junk data) into proper spreadsheets. The deliverable must be a spreadsheet file. Do NOT trigger when the primary deliverable is a Word document, HTML report, standalone Python script, database pipeline, or Google Sheets API integration, even if tabular data is involved."},"features":{"zh":["xlsx",".csv",".tsv","Excel","Arial","Times New Roman"],"ja":["xlsx",".csv",".tsv","Excel","Arial","Times New Roman"],"ko":["xlsx",".csv",".tsv","Excel","Arial","Times New Roman"],"es":["Edición de archivos de hoja de cálculo existentes","Creación de nuevos archivos de hoja de cálculo","Conversión entre formatos de archivo tabulares","Limpieza y reestructuración de datos","Uso de fuentes profesionales y consistentes","Evitación de errores de fórmula"],"fr":["Édition de fichiers de tableur existants","Création de nouveaux fichiers de tableur","Conversion entre les formats de fichier tabulaires","Nettoyage et réorganisation des données","Utilisation de polices professionnelles et cohérentes","Évitement des erreurs de formule"],"de":["Bearbeitung von bestehenden Tabellenkalkulationsdateien","Erstellung von neuen Tabellenkalkulationsdateien","Konvertierung zwischen Tabellenkalkulationsdateiformaten","Reinigung und Umstrukturierung von Daten","Verwendung von professionellen und konsistenten Schriftarten","Vermeidung von Formel-fehlern"],"pt":["Criação de planilhas","Edição de planilhas","Conversão de arquivos de planilha","Limpeza de dados","Formatação de células","Cálculo de fórmulas"],"ru":["Создание таблиц","Редактирование таблиц","Конвертация файлов таблиц","Очистка данных","Форматирование ячеек","Расчет формул"],"ar":["إنشاء جداول","تعديل جداول","تحويل ملفات الجداول","تنظيف البيانات","تنسيق الخلايا","حساب الصيغ"]},"keywords":{"zh":["xlsx","Excel","csv","tsv","Arial","Times New Roman","formula errors","template"],"ja":["xlsx","Excel","csv","tsv","Arial","Times New Roman","formula errors","template"],"ko":["xlsx","Excel","csv","tsv","Arial","Times New Roman","formula errors","template"],"es":["habilidad xlsx","edición de hoja de cálculo","creación de hoja de cálculo","conversión de formato de archivo","limpieza de datos","reestructuración de datos","fuentes profesionales","evitación de errores de fórmula"],"fr":["compétence xlsx","édition de tableur","création de tableur","conversion de format de fichier","nettoyage de données","réorganisation de données","polices professionnelles","évitement des erreurs de formule"],"de":["Fähigkeit xlsx","Bearbeitung von Tabellenkalkulationsdateien","Erstellung von Tabellenkalkulationsdateien","Konvertierung von Tabellenkalkulationsdateiformaten","Reinigung von Daten","Umstrukturierung von Daten","professionelle Schriftarten","Vermeidung von Formel-fehlern"],"pt":["habilidades xlsx","planilhas xlsx","editar planilhas","conversão de planilhas","limpeza de dados","formatação de células","cálculo de fórmulas","desenvolvimento de planilhas"],"ru":["навыки xlsx","таблицы xlsx","редактирование таблиц","конвертация таблиц","очистка данных","форматирование ячеек","расчет формул","разработка таблиц"],"ar":["مهارات xlsx","جداول xlsx","تعديل جداول","تحويل جداول","تنظيف البيانات","تنسيق الخلايا","حساب الصيغ","تطوير الجداول"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing robust spreadsheet manipulation and transformation capabilities.","zh":"非常适合需要强大的电子表格操作和转换能力的数据分析代理。","ja":"データ分析エージェントが強力なスプレッドシート操作と変換機能を必要とする場合に最適です。","ko":"로부스트한 스프레드시트 조작 및 변환 기능이 필요한 데이터 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis de datos que necesitan capacidades robustas de manipulación y transformación de hojas de cálculo.","fr":"Parfait pour les agents d''analyse de données ayant besoin de capacités robustes de manipulation et de transformation de tableurs.","de":"Perfekt für Data-Analytics-Agents, die robuste Tabellenkalkulations- und Transformationsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de capacidades robustas de manipulação e transformação de planilhas.","ru":"Идеально подходит для агентов анализа данных, которым требуются надежные возможности манипулирования и преобразования электронных таблиц.","ar":"مثالي لويبوتات تحليل البيانات التي تحتاج إلى قدرات قوية لتعديل وتحويل الجداول الإلكترونية."},"recommendation":{"en":"Empowers agents to programmatically handle complex Excel operations including reading, editing, and formatting .xlsx/.xlsm files, cleaning messy tabular data, converting between formats, and ensuring zero formula errors while maintaining professional font consistency and preserving existing template structures.","zh":"赋予代理程序化处理复杂的Excel操作的能力，包括读取、编辑和格式化.xlsx/.xlsm文件，清理混乱的表格数据，转换格式，并确保零公式错误，同时保持专业字体的一致性和保留现有的模板结构。","ja":"エージェントがプログラムで複雑なExcel操作を処理できるようにします。これには、.xlsx/.xlsmファイルの読み取り、編集、フォーマット、不正な表形式データのクリーンアップ、形式の変換、ゼロの式エラーの保証、およびプロのフォントの一貫性の維持と既存のテンプレート構造の保存が含まれます。","ko":"에이전트가 복잡한 엑셀 작업을 프로그램으로 처리할 수 있도록 합니다. 이는 .xlsx/.xlsm 파일의 읽기, 편집, 형식 지정, 잘못된 표 형식 데이터의 정리, 형식 변환, 영 수식 오류 보장 및 전문가용 글꼴 일관성 유지 및 기존 템플릿 구조 보존을 포함합니다.","es":"Permite a los agentes manejar operaciones de Excel complejas de forma programática, incluyendo la lectura, edición y formato de archivos .xlsx/.xlsm, la limpieza de datos tabulares desordenados, la conversión entre formatos y la garantía de cero errores de fórmula mientras se mantiene la consistencia de la fuente profesional y se preservan las estructuras de plantilla existentes.","fr":"Permet aux agents de gérer de manière programmatique des opérations Excel complexes, notamment la lecture, l''édition et le formatage de fichiers .xlsx/.xlsm, le nettoyage de données tabulaires désordonnées, la conversion entre formats et la garantie de zéro erreur de formule tout en maintenant la cohérence de la police professionnelle et en préservant les structures de modèles existants.","de":"Ermöglicht es Agenten, komplexe Excel-Operationen programmgesteuert zu handhaben, einschließlich Lesen, Bearbeiten und Formatieren von .xlsx/.xlsm-Dateien, Reinigen von unordentlichen Tabellendaten, Umwandeln zwischen Formaten und Gewährleisten von null Formelfehlern unter Beibehaltung der professionellen Schriftkonsistenz und Erhaltung bestehender Vorlagenstrukturen.","pt":"Habilita os agentes a lidar programaticamente com operações complexas do Excel, incluindo leitura, edição e formatação de arquivos .xlsx/.xlsm, limpeza de dados tabulares desorganizados, conversão entre formatos e garantia de zero erros de fórmula, mantendo a consistência da fonte profissional e preservando as estruturas de modelo existentes.","ru":"Наделяет агентов возможностью программно обрабатывать сложные операции Excel, включая чтение, редактирование и форматирование файлов .xlsx/.xlsm, очистку неорганизованных табличных данных, конвертацию между форматами и обеспечение отсутствия ошибок формул при сохранении профессиональной согласованности шрифтов и сохранении существующих структур шаблонов.","ar":"تمكين الوكلاء من التعامل برمجيًا مع عمليات إكسل المعقدة بما في ذلك قراءة وتحرير وتنسيق ملفات .xlsx/.xlsm، تنظيف البيانات الجدولية المتضخمة، وتحويل الصيغ، وضمان عدم وجود أخطاء في الصيغ مع الحفاظ على اتساق الخطوط الاحترافية والحفاظ على هياكل النماذج الحالية."},"useCases":{"en":["Cleaning malformed spreadsheet data with misplaced headers","Converting between .csv/.tsv and .xlsx formats","Adding calculated columns and fixing formula errors","Applying consistent professional formatting to financial models","Restructuring messy tabular files into organized spreadsheets"],"zh":["清理格式不正确的电子表格数据，包括误放置的标题","在.csv/.tsv和.xlsx格式之间进行转换","添加计算列并修复公式错误","将一致的专业格式应用于财务模型","将混乱的表格文件重新组织成有组织的电子表格"],"ja":["不正な形式のスプレッドシートデータをクリーンアップし、ヘッダーを誤って配置したものを含む",".csv/.tsvと.xlsx形式の間で変換する","計算列を追加し、式のエラーを修正する","財務モデルに一貫したプロのフォーマットを適用する","不正な表形式ファイルを整理されたスプレッドシートに再構成する"],"ko":["잘못된 형식의 스프레드시트 데이터를 정리하고, 잘못된 위치에 있는 헤더를 포함하여",".csv/.tsv와 .xlsx 형식 사이에서 변환하기","계산列을 추가하고 수식 오류를 수정하기","금융 모델에 일관된 전문가용 형식 적용하기","잘못된 표 형식 파일을 조직화된 스프레드시트로 재구성하기"],"es":["Limpieza de datos de hoja de cálculo con encabezados mal colocados","Conversión entre formatos .csv/.tsv y .xlsx","Adición de columnas calculadas y corrección de errores de fórmula","Aplicación de formato profesional consistente a modelos financieros","Reestructuración de archivos tabulares desordenados en hojas de cálculo organizadas"],"fr":["Nettoyage de données de tableur avec en-têtes mal placés","Conversion entre les formats .csv/.tsv et .xlsx","Ajout de colonnes calculées et correction d''erreurs de formule","Application d''un formatage professionnel cohérent aux modèles financiers","Réorganisation de fichiers tabulaires désordonnés en tableurs organisés"],"de":["Reinigung von Tabellendaten mit falsch platzierten Überschriften","Umwandlung zwischen .csv/.tsv- und .xlsx-Formaten","Hinzufügen von berechneten Spalten und Korrektur von Formelfehlern","Anwenden eines konsistenten professionellen Formatierungs auf Finanzmodelle","Umstrukturierung von unordentlichen Tabellendateien in organisierte Tabellen"],"pt":["Limpar dados de planilha com cabeçalhos mal posicionados","Converter entre formatos .csv/.tsv e .xlsx","Adicionar colunas calculadas e corrigir erros de fórmula","Aplicar formatação profissional consistente a modelos financeiros","Reestruturar arquivos tabulares desorganizados em planilhas organizadas"],"ru":["Очистка данных электронных таблиц с неправильно размещенными заголовками","Конвертация между форматами .csv/.tsv и .xlsx","Добавление вычисляемых столбцов и исправление ошибок формул","Применение последовательного профессионального форматирования к финансовым моделям","Переструктуризация неорганизованных табличных файлов в организованные электронные таблицы"],"ar":["تنظيف بيانات الجداول الإلكترونية مع عناوين مفقودة","تحويل بين صيغ .csv/.tsv و .xlsx","إضافة أعمدة محسوبة وتصحيح أخطاء الصيغ","تطبيق تنسيق احترافي متسق على نماذج مالية","إعادة بناء الملفات الجدولية المتضخمة في جداول إلكترونية منظمات"]},"limitations":{"en":["Requires local file system access for spreadsheet operations","Limited to traditional Excel formats (.xlsx, .xlsm, .csv, .tsv)","No native Google Sheets API integration support"],"zh":["需要本地文件系统访问权限以进行电子表格操作","仅限于传统的Excel格式（.xlsx, .xlsm, .csv, .tsv）","不支持Google Sheets API的本地集成"],"ja":["スプレッドシート操作を行うためにローカルファイルシステムへのアクセスが必要","従来のExcel形式（.xlsx, .xlsm, .csv, .tsv）に限定される","Google Sheets APIのネイティブ統合サポートなし"],"ko":["스프레드시트 작업을 수행하기 위해 로컬 파일 시스템 액세스가 필요함","전통적인 엑셀 형식(.xlsx, .xlsm, .csv, .tsv)으로 제한됨","구글 시트 API 네이티브 통합 지원 없음"],"es":["Requiere acceso al sistema de archivos local para operaciones de hoja de cálculo","Limitado a formatos de Excel tradicionales (.xlsx, .xlsm, .csv, .tsv)","No hay soporte de integración nativa de la API de Google Sheets"],"fr":["Nécessite un accès au système de fichiers local pour les opérations de tableur","Limité aux formats Excel traditionnels (.xlsx, .xlsm, .csv, .tsv)","Aucun support d''intégration native de l''API Google Sheets"],"de":["Benötigt Zugriff auf das lokale Dateisystem für Tabellenkalkulationsoperationen","Begrenzt auf traditionelle Excel-Formate (.xlsx, .xlsm, .csv, .tsv)","Keine native Unterstützung für Google Sheets API-Integration"],"pt":["Requer acesso ao sistema de arquivos local para operações de planilha","Limitado a formatos tradicionais do Excel (.xlsx, .xlsm, .csv, .tsv)","Sem suporte nativo à API do Google Sheets"],"ru":["Требует доступа к локальной файловой системе для операций с электронными таблицами","Ограничен традиционными форматами Excel (.xlsx, .xlsm, .csv, .tsv)","Не имеет встроенной поддержки API Google Sheets"],"ar":["يتطلب الوصول إلى نظام الملفات المحلي لعمليات الجداول الإلكترونية","محدود بالصيغ التقليدية لإكسل (.xlsx, .xlsm, .csv, .tsv)","بدون دعم مدمج ل-API الجدول الإلكتروني لجوجل"]},"version":3},"contentHash":"dd316db7785a6be12966c2a2d848931fbf5f518b3cdb0a66fa62ee835ead1cfc","repoEtag":"W/\"5456759f24524b9171780a611a3970c1ae87a3d09576f2945661ad98ce4c37da\"","qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/docx', 'official', 'anthropics', 'skills', 'anthropics/skills', 'docx', 71980, 7353, 75, '2026-02-20T01:38:00Z', '2026-02-20T01:48:10.845Z', '71cfc398ee05221f21fddc797ea5523a59278feb3447c681db92fa9130ad2da3', '{"id":"anthropics/skills/docx","name":"docx","description":{"zh":"DOCX 技术允许开发者创建、编辑和分析 Word 文档，支持多种任务，如文档转换和内容提取","ja":"DOCX 技術は、開発者がワード文書を作成、編集、分析できるようにし、文書の変換やコンテンツの抽出など多くのタスクをサポートする","ko":"DOCX 기술은 개발자가 워드 문서를 생성, 편집 및 분석할 수 있도록 하며 문서 변환 및 콘텐츠 추출 등 다양한 작업을 지원","es":"El skill DOCX permite crear, leer, editar y manipular documentos Word (.docx) con facilidad, incluyendo la creación de informes, memorandos y cartas","fr":"Le skill DOCX permet de créer, lire, éditer et manipuler des documents Word (.docx) avec facilité, y compris la création de rapports, de mémorandums et de lettres","de":"Das DOCX-Skill ermöglicht die Erstellung, das Lesen, die Bearbeitung und die Manipulation von Word-Dokumenten (.docx) mit Leichtigkeit, einschließlich der Erstellung von Berichten, Memoranden und Briefen","pt":"O skill DOCX permite criar, ler, editar e manipular arquivos Word (.docx) com facilidade, incluindo formatação e extração de conteúdo","ru":"Навык DOCX позволяет создавать, читать, редактировать и манипулировать файлами Word (.docx) с легкостью, включая форматирование и извлечение содержимого","ar":"مهارة DOCX تمكن من إنشاء وقراءة وتحرير ومعالجة مستندات Word (.docx) بسهولة، بما في ذلك التنسيق واستخراج المحتوى","en":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files). Triggers include: any mention of \\Word doc\\, \\word document\\, \\.docx\\, or requests to produce professional documents with formatting like tables of contents, headings, page numbers, or letter..."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71980,"forks":7353,"updatedAt":"2026-02-20T01:38:00Z","topics":["agent-skills"],"skillMd":{"name":"docx","description":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files). Triggers include: any mention of \\Word doc\\, \\word document\\, \\.docx\\, or requests to produce professional documents with formatting like tables of contents, headings, page numbers, or letterheads. Also use when extracting or reorganizing content from .docx files, inserting or replacing images in documents, performing find-and-replace in Word files, working with tracked changes or comments, or converting content into a polished Word document. If the user asks for a \\report\\, \\memo\\, \\letter\\, \\template\\, or similar deliverable as a Word or .docx file, use this skill. Do NOT use for PDFs, spreadsheets, Google Docs, or general coding tasks unrelated to document generation.","bodyPreview":"# DOCX creation, editing, and analysis\n\n## Overview\n\nA .docx file is a ZIP archive containing XML files.\n\n## Quick Reference\n\n| Task | Approach |\n|------|----------|\n| Read/analyze content | `pandoc` or unpack for raw XML |\n| Create new document | Use `docx-js` - see Creating New Documents below |\n| Edit existing document | Unpack → edit XML → repack - see Editing Existing Documents below |\n\n### Converting .doc to .docx\n\nLegacy `.doc` files must be converted before editing:\n\n```bash\npython scrip","body":"# DOCX creation, editing, and analysis\n\n## Overview\n\nA .docx file is a ZIP archive containing XML files.\n\n## Quick Reference\n\n| Task | Approach |\n|------|----------|\n| Read/analyze content | `pandoc` or unpack for raw XML |\n| Create new document | Use `docx-js` - see Creating New Documents below |\n| Edit existing document | Unpack → edit XML → repack - see Editing Existing Documents below |\n\n### Converting .doc to .docx\n\nLegacy `.doc` files must be converted before editing:\n\n```bash\npython scripts/office/soffice.py --headless --convert-to docx document.doc\n```\n\n### Reading Content\n\n```bash\n# Text extraction with tracked changes\npandoc --track-changes=all document.docx -o output.md\n\n# Raw XML access\npython scripts/office/unpack.py document.docx unpacked/\n```\n\n### Converting to Images\n\n```bash\npython scripts/office/soffice.py --headless --convert-to pdf document.docx\npdftoppm -jpeg -r 150 document.pdf page\n```\n\n### Accepting Tracked Changes\n\nTo produce a clean document with all tracked changes accepted (requires LibreOffice):\n\n```bash\npython scripts/accept_changes.py input.docx output.docx\n```\n\n---\n\n## Creating New Documents\n\nGenerate .docx files with JavaScript, then validate. Install: `npm install -g docx`\n\n### Setup\n```javascript\nconst { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,\n        Header, Footer, AlignmentType, PageOrientation, LevelFormat, ExternalHyperlink,\n        TableOfContents, HeadingLevel, BorderStyle, WidthType, ShadingType,\n        VerticalAlign, PageNumber, PageBreak } = require(''docx'');\n\nconst doc = new Document({ sections: [{ children: [/* content */] }] });\nPacker.toBuffer(doc).then(buffer => fs.writeFileSync(\"doc.docx\", buffer));\n```\n\n### Validation\nAfter creating the file, validate it. If validation fails, unpack, fix the XML, and repack.\n```bash\npython scripts/office/validate.py doc.docx\n```\n\n### Page Size\n\n```javascript\n// CRITICAL: docx-js defaults to A4, not US Letter\n// Always set page size explicitly for consistent results\nsections: [{\n  properties: {\n    page: {\n      size: {\n        width: 12240,   // 8.5 inches in DXA\n        height: 15840   // 11 inches in DXA\n      },\n      margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } // 1 inch margins\n    }\n  },\n  children: [/* content */]\n}]\n```\n\n**Common page sizes (DXA units, 1440 DXA = 1 inch):**\n\n| Paper | Width | Height | Content Width (1\" margins) |\n|-------|-------|--------|---------------------------|\n| US Letter | 12,240 | 15,840 | 9,360 |\n| A4 (default) | 11,906 | 16,838 | 9,026 |\n\n**Landscape orientation:** docx-js swaps width/height internally, so pass portrait dimensions and let it handle the swap:\n```javascript\nsize: {\n  width: 12240,   // Pass SHORT edge as width\n  height: 15840,  // Pass LONG edge as height\n  orientation: PageOrientation.LANDSCAPE  // docx-js swaps them in the XML\n},\n// Content width = 15840 - left margin - right margin (uses the long edge)\n```\n\n### Styles (Override Built-in Headings)\n\nUse Arial as the default font (universally supported). Keep titles black for readability.\n\n```javascript\nconst doc = new Document({\n  styles: {\n    default: { document: { run: { font: \"Arial\", size: 24 } } }, // 12pt default\n    paragraphStyles: [\n      // IMPORTANT: Use exact IDs to override built-in styles\n      { id: \"Heading1\", name: \"Heading 1\", basedOn: \"Normal\", next: \"Normal\", quickFormat: true,\n        run: { size: 32, bold: true, font: \"Arial\" },\n        paragraph: { spacing: { before: 240, after: 240 }, outlineLevel: 0 } }, // outlineLevel required for TOC\n      { id: \"Heading2\", name: \"Heading 2\", basedOn: \"Normal\", next: \"Normal\", quickFormat: true,\n        run: { size: 28, bold: true, font: \"Arial\" },\n        paragraph: { spacing: { before: 180, after: 180 }, outlineLevel: 1 } },\n    ]\n  },\n  sections: [{\n    children: [\n      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(\"Title\")] }),\n    ]\n  }]\n});\n```\n\n### Lists (NEVER use unicode bullets)\n\n```javascript\n// ❌ WRONG - never manually insert bullet characters\nnew Paragraph({ children: [new TextRun(\"• Item\")] })  // BAD\nnew Paragraph({ children: [new TextRun(\"\\u2022 Item\")] })  // BAD\n\n// ✅ CORRECT - use numbering config with LevelFormat.BULLET\nconst doc = new Document({\n  numbering: {\n    config: [\n      { reference: \"bullets\",\n        levels: [{ level: 0, format: LevelFormat.BULLET, text: \"•\", alignment: AlignmentType.LEFT,\n          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },\n      { reference: \"numbers\",\n        levels: [{ level: 0, format: LevelFormat.DECIMAL, text: \"%1.\", alignment: AlignmentType.LEFT,\n          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },\n    ]\n  },\n  sections: [{\n    children: [\n      new Paragraph({ numbering: { reference: \"bullets\", level: 0 },\n        children: [new TextRun(\"Bullet item\")] }),\n      new Paragraph({ numbering: { reference: \"numbers\", level: 0 },\n        children: [new TextRun(\"Numbered item\")] }),\n    ]\n  }]\n});\n\n// ⚠️ Each reference creates INDEPENDENT numbering\n// Same reference = continues (1,2,3 then 4,5,6)\n// Different reference = restarts (1,2,3 then 1,2,3)\n```\n\n### Tables\n\n**CRITICAL: Tables need dual widths** - set both `columnWidths` on the table AND `width` on each cell. Without both, tables render incorrectly on some platforms.\n\n```javascript\n// CRITICAL: Always set table width for consistent rendering\n// CRITICAL: Use ShadingType.CLEAR (not SOLID) to prevent black backgrounds\nconst border = { style: BorderStyle.SINGLE, size: 1, color: \"CCCCCC\" };\nconst borders = { top: border, bottom: border, left: border, right: border };\n\nnew Table({\n  width: { size: 9360, type: WidthType.DXA }, // Always use DXA (percentages break in Google Docs)\n  columnWidths: [4680, 4680], // Must sum to table width (DXA: 1440 = 1 inch)\n  rows: [\n    new TableRow({\n      children: [\n        new TableCell({\n          borders,\n          width: { size: 4680, type: WidthType.DXA }, // Also set on each cell\n          shading: { fill: \"D5E8F0\", type: ShadingType.CLEAR }, // CLEAR not SOLID\n          margins: { top: 80, bottom: 80, left: 120, right: 120 }, // Cell padding (internal, not added to width)\n          children: [new Paragraph({ children: [new TextRun(\"Cell\")] })]\n        })\n      ]\n    })\n  ]\n})\n```\n\n**Table width calculation:**\n\nAlways use `WidthType.DXA` — `WidthType.PERCENTAGE` breaks in Google Docs.\n\n```javascript\n// Table width = sum of columnWidths = content width\n// US Letter with 1\" margins: 12240 - 2880 = 9360 DXA\nwidth: { size: 9360, type: WidthType.DXA },\ncolumnWidths: [7000, 2360]  // Must sum to table width\n```\n\n**Width rules:**\n- **Always use `WidthType.DXA`** — never `WidthType.PERCENTAGE` (incompatible with Google Docs)\n- Table width must equal the sum of `columnWidths`\n- Cell `width` must match corresponding `columnWidth`\n- Cell `margins` are internal padding - they reduce content area, not add to cell width\n- For full-width tables: use content width (page width minus left and right margins)\n\n### Images\n\n```javascript\n// CRITICAL: type parameter is REQUIRED\nnew Paragraph({\n  children: [new ImageRun({\n    type: \"png\", // Required: png, jpg, jpeg, gif, bmp, svg\n    data: fs.readFileSync(\"image.png\"),\n    transformation: { width: 200, height: 150 },\n    altText: { title: \"Title\", description: \"Desc\", name: \"Name\" } // All three required\n  })]\n})\n```\n\n### Page Breaks\n\n```javascript\n// CRITICAL: PageBreak must be inside a Paragraph\nnew Paragraph({ children: [new PageBreak()] })\n\n// Or use pageBreakBefore\nnew Paragraph({ pageBreakBefore: true, children: [new TextRun(\"New page\")] })\n```\n\n### Table of Contents\n\n```javascript\n// CRITICAL: Headings must use HeadingLevel ONLY - no custom styles\nnew TableOfContents(\"Table of Contents\", { hyperlink: true, headingStyleRange: \"1-3\" })\n```\n\n### Headers/Footers\n\n```javascript\nsections: [{\n  properties: {\n    page: { margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } // 1440 = 1 inch\n  },\n  headers: {\n    default: new Header({ children: [new Paragraph({ children: [new TextRun(\"Header\")] })] })\n  },\n  footers: {\n    default: new Footer({ children: [new Paragraph({\n      children: [new TextRun(\"Page \"), new TextRun({ children: [PageNumber.CURRENT] })]\n    })] })\n  },\n  children: [/* content */]\n}]\n```\n\n### Critical Rules for docx-js\n\n- **Set page size explicitly** - docx-js defaults to A4; use US Letter (12240 x 15840 DXA) for US documents\n- **Landscape: pass portrait dimensions** - docx-js swaps width/height internally; pass short edge as `width`, long edge as `height`, and set `orientation: PageOrientation.LANDSCAPE`\n- **Never use `\\n`** - use separate Paragraph elements\n- **Never use unicode bullets** - use `LevelFormat.BULLET` with numbering config\n- **PageBreak must be in Paragraph** - standalone creates invalid XML\n- **ImageRun requires `type`** - always specify png/jpg/etc\n- **Always set table `width` with DXA** - never use `WidthType.PERCENTAGE` (breaks in Google Docs)\n- **Tables need dual widths** - `columnWidths` array AND cell `width`, both must match\n- **Table width = sum of columnWidths** - for DXA, ensure they add up exactly\n- **Always add cell margins** - use `margins: { top: 80, bottom: 80, left: 120, right: 120 }` for readable padding\n- **Use `ShadingType.CLEAR`** - never SOLID for table shading\n- **TOC requires HeadingLevel only** - no custom styles on heading paragraphs\n- **Override built-in styles** - use exact IDs: \"Heading1\", \"Heading2\", etc.\n- **Include `outlineLevel`** - required for TOC (0 for H1, 1 for H2, etc.)\n\n---\n\n## Editing Existing Documents\n\n**Follow all 3 steps in order.**\n\n### Step 1: Unpack\n```bash\npython scripts/office/unpack.py document.docx unpacked/\n```\nExtracts XML, pretty-prints, merges adjacent runs, and converts smart quotes to XML entities (`&#x201C;` etc.) so they survive editing. Use `--merge-runs false` to skip run merging.\n\n### Step 2: Edit XML\n\nEdit files in `unpacked/word/`. See XML Reference below for patterns.\n\n**Use \"Claude\" as the author** for tracked changes and comments, unless the user explicitly requests use of a different name.\n\n**Use the Edit tool directly for string replacement. Do not write Python scripts.** Scripts introduce unnecessary complexity. The Edit tool shows exactly what is being replaced.\n\n**CRITICAL: Use smart quotes for new content.** When adding text with apostrophes or quotes, use XML entities to produce smart quotes:\n```xml\n<!-- Use these entities for professional typography -->\n<w:t>Here&#x2019;s a quote: &#x201C;Hello&#x201D;</w:t>\n```\n| Entity | Character |\n|--------|-----------|\n| `&#x2018;` | ‘ (left single) |\n| `&#x2019;` | ’ (right single / apostrophe) |\n| `&#x201C;` | “ (left double) |\n| `&#x201D;` | ” (right double) |\n\n**Adding comments:** Use `comment.py` to handle boilerplate across multiple XML files (text must be pre-escaped XML):\n```bash\npython scripts/comment.py unpacked/ 0 \"Comment text with &amp; and &#x2019;\"\npython scripts/comment.py unpacked/ 1 \"Reply text\" --parent 0  # reply to comment 0\npython scripts/comment.py unpacked/ 0 \"Text\" --author \"Custom Author\"  # custom author name\n```\nThen add markers to document.xml (see Comments in XML Reference).\n\n### Step 3: Pack\n```bash\npython scripts/office/pack.py unpacked/ output.docx --original document.docx\n```\nValidates with auto-repair, condenses XML, and creates DOCX. Use `--validate false` to skip.\n\n**Auto-repair will fix:**\n- `durableId` >= 0x7FFFFFFF (regenerates valid ID)\n- Missing `xml:space=\"preserve\"` on `<w:t>` with whitespace\n\n**Auto-repair won''t fix:**\n- Malformed XML, invalid element nesting, missing relationships, schema violations\n\n### Common Pitfalls\n\n- **Replace entire `<w:r>` elements**: When adding tracked changes, replace the whole `<w:r>...</w:r>` block with `<w:del>...<w:ins>...` as siblings. Don''t inject tracked change tags inside a run.\n- **Preserve `<w:rPr>` formatting**: Copy the original run''s `<w:rPr>` block into your tracked change runs to maintain bold, font size, etc.\n\n---\n\n## XML Reference\n\n### Schema Compliance\n\n- **Element order in `<w:pPr>`**: `<w:pStyle>`, `<w:numPr>`, `<w:spacing>`, `<w:ind>`, `<w:jc>`, `<w:rPr>` last\n- **Whitespace**: Add `xml:space=\"preserve\"` to `<w:t>` with leading/trailing spaces\n- **RSIDs**: Must be 8-digit hex (e.g., `00AB1234`)\n\n### Tracked Changes\n\n**Insertion:**\n```xml\n<w:ins w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:t>inserted text</w:t></w:r>\n</w:ins>\n```\n\n**Deletion:**\n```xml\n<w:del w:id=\"2\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:delText>deleted text</w:delText></w:r>\n</w:del>\n```\n\n**Inside `<w:del>`**: Use `<w:delText>` instead of `<w:t>`, and `<w:delInstrText>` instead of `<w:instrText>`.\n\n**Minimal edits** - only mark what changes:\n```xml\n<!-- Change \"30 days\" to \"60 days\" -->\n<w:r><w:t>The term is </w:t></w:r>\n<w:del w:id=\"1\" w:author=\"Claude\" w:date=\"...\">\n  <w:r><w:delText>30</w:delText></w:r>\n</w:del>\n<w:ins w:id=\"2\" w:author=\"Claude\" w:date=\"...\">\n  <w:r><w:t>60</w:t></w:r>\n</w:ins>\n<w:r><w:t> days.</w:t></w:r>\n```\n\n**Deleting entire paragraphs/list items** - when removing ALL content from a paragraph, also mark the paragraph mark as deleted so it merges with the next paragraph. Add `<w:del/>` inside `<w:pPr><w:rPr>`:\n```xml\n<w:p>\n  <w:pPr>\n    <w:numPr>...</w:numPr>  <!-- list numbering if present -->\n    <w:rPr>\n      <w:del w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\"/>\n    </w:rPr>\n  </w:pPr>\n  <w:del w:id=\"2\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n    <w:r><w:delText>Entire paragraph content being deleted...</w:delText></w:r>\n  </w:del>\n</w:p>\n```\nWithout the `<w:del/>` in `<w:pPr><w:rPr>`, accepting changes leaves an empty paragraph/list item.\n\n**Rejecting another author''s insertion** - nest deletion inside their insertion:\n```xml\n<w:ins w:author=\"Jane\" w:id=\"5\">\n  <w:del w:author=\"Claude\" w:id=\"10\">\n    <w:r><w:delText>their inserted text</w:delText></w:r>\n  </w:del>\n</w:ins>\n```\n\n**Restoring another author''s deletion** - add insertion after (don''t modify their deletion):\n```xml\n<w:del w:author=\"Jane\" w:id=\"5\">\n  <w:r><w:delText>deleted text</w:delText></w:r>\n</w:del>\n<w:ins w:author=\"Claude\" w:id=\"10\">\n  <w:r><w:t>deleted text</w:t></w:r>\n</w:ins>\n```\n\n### Comments\n\nAfter running `comment.py` (see Step 2), add markers to document.xml. For replies, use `--parent` flag and nest markers inside the parent''s.\n\n**CRITICAL: `<w:commentRangeStart>` and `<w:commentRangeEnd>` are siblings of `<w:r>`, never inside `<w:r>`.**\n\n```xml\n<!-- Comment markers are direct children of w:p, never inside w:r -->\n<w:commentRangeStart w:id=\"0\"/>\n<w:del w:id=\"1\" w:author=\"Claude\" w:date=\"2025-01-01T00:00:00Z\">\n  <w:r><w:delText>deleted</w:delText></w:r>\n</w:del>\n<w:r><w:t> more text</w:t></w:r>\n<w:commentRangeEnd w:id=\"0\"/>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"0\"/></w:r>\n\n<!-- Comment 0 with reply 1 nested inside -->\n<w:commentRangeStart w:id=\"0\"/>\n  <w:commentRangeStart w:id=\"1\"/>\n  <w:r><w:t>text</w:t></w:r>\n  <w:commentRangeEnd w:id=\"1\"/>\n<w:commentRangeEnd w:id=\"0\"/>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"0\"/></w:r>\n<w:r><w:rPr><w:rStyle w:val=\"CommentReference\"/></w:rPr><w:commentReference w:id=\"1\"/></w:r>\n```\n\n### Images\n\n1. Add image file to `word/media/`\n2. Add relationship to `word/_rels/document.xml.rels`:\n```xml\n<Relationship Id=\"rId5\" Type=\".../image\" Target=\"media/image1.png\"/>\n```\n3. Add content type to `[Content_Types].xml`:\n```xml\n<Default Extension=\"png\" ContentType=\"image/png\"/>\n```\n4. Reference in document.xml:\n```xml\n<w:drawing>\n  <wp:inline>\n    <wp:extent cx=\"914400\" cy=\"914400\"/>  <!-- EMUs: 914400 = 1 inch -->\n    <a:graphic>\n      <a:graphicData uri=\".../picture\">\n        <pic:pic>\n          <pic:blipFill><a:blip r:embed=\"rId5\"/></pic:blipFill>\n        </pic:pic>\n      </a:graphicData>\n    </a:graphic>\n  </wp:inline>\n</w:drawing>\n```\n\n---\n\n## Dependencies\n\n- **pandoc**: Text extraction\n- **docx**: `npm install -g docx` (new documents)\n- **LibreOffice**: PDF conversion (auto-configured for sandboxed environments via `scripts/office/soffice.py`)\n- **Poppler**: `pdftoppm` for images\n"},"category":"official","lastSynced":"2026-02-20T01:48:10.845Z","seo":{"title":{"zh":"DOCX 技术：创建、编辑和分析 Word 文档","ja":"DOCX 技術：ワード文書の作成、編集、分析","ko":"DOCX 기술: 워드 문서 만들기, 편집 및 분석","es":"Creación y edición de documentos DOCX","fr":"Création et édition de documents DOCX","de":"Erstellung und Bearbeitung von DOCX-Dokumenten","pt":"Crie e Edite Arquivos DOCX com Fácil","ru":"Создание и редактирование файлов DOCX","ar":"إنشاء وتحرير مستندات DOCX","en":"docx"},"description":{"zh":"DOCX 技术允许开发者创建、编辑和分析 Word 文档，支持多种任务，如文档转换和内容提取","ja":"DOCX 技術は、開発者がワード文書を作成、編集、分析できるようにし、文書の変換やコンテンツの抽出など多くのタスクをサポートする","ko":"DOCX 기술은 개발자가 워드 문서를 생성, 편집 및 분석할 수 있도록 하며 문서 변환 및 콘텐츠 추출 등 다양한 작업을 지원","es":"El skill DOCX permite crear, leer, editar y manipular documentos Word (.docx) con facilidad, incluyendo la creación de informes, memorandos y cartas","fr":"Le skill DOCX permet de créer, lire, éditer et manipuler des documents Word (.docx) avec facilité, y compris la création de rapports, de mémorandums et de le...","de":"Das DOCX-Skill ermöglicht die Erstellung, das Lesen, die Bearbeitung und die Manipulation von Word-Dokumenten (.docx) mit Leichtigkeit, einschließlich der Er...","pt":"O skill DOCX permite criar, ler, editar e manipular arquivos Word (.docx) com facilidade, incluindo formatação e extração de conteúdo","ru":"Навык DOCX позволяет создавать, читать, редактировать и манипулировать файлами Word (.docx) с легкостью, включая форматирование и извлечение содержимого","ar":"مهارة DOCX تمكن من إنشاء وقراءة وتحرير ومعالجة مستندات Word (.docx) بسهولة، بما في ذلك التنسيق واستخراج المحتوى","en":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files). Triggers include: any mention of \\Word doc\\, \\word ..."},"definition":{"en":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files). Triggers include: any mention of \\Word doc\\, \\word document\\, \\.docx\\, or requests to produce professional documents with formatting like tables of contents, headings, page numbers, or letterheads. Also use when extracting or reorganizing content from .docx files, inserting or replacing images in documents, performing find-and-replace in Word files, working with tracked changes or comments, or converting content into a polished Word document. If the user asks for a \\report\\, \\memo\\, \\letter\\, \\template\\, or similar deliverable as a Word or .docx file, use this skill. Do NOT use for PDFs, spreadsheets, Google Docs, or general coding tasks unrelated to document generation."},"features":{"zh":["创建新文档","编辑现有文档","文档转换","内容提取","支持多种任务"],"ja":["新規文書の作成","既存文書の編集","文書の変換","コンテンツの抽出","多くのタスクをサポート"],"ko":["새 문서 생성","기존 문서 편집","문서 변환","콘텐츠 추출","여러 작업 지원"],"es":["Creación de documentos Word (.docx)","Edición de documentos existentes","Extracción y reorganización de contenido","Inserción y reemplazo de imágenes","Búsqueda y reemplazo de texto"],"fr":["Création de documents Word (.docx)","Édition de documents existants","Extraction et réorganisation de contenu","Insertion et remplacement d''images","Recherche et remplacement de texte"],"de":["Erstellung von Word-Dokumenten (.docx)","Bearbeitung von bestehenden Dokumenten","Extraktion und Reorganisation von Inhalten","Einfügen und Ersetzen von Bildern","Suchen und Ersetzen von Text"],"pt":["Criação de novos documentos DOCX","Edição de documentos existentes","Extração de conteúdo de arquivos DOCX","Formatação de texto e imagens","Inserção de tabelas e cabeçalhos"],"ru":["Создание новых документов DOCX","Редактирование существующих документов","Извлечение содержимого из файлов DOCX","Форматирование текста и изображений","Вставка таблиц и заголовков"],"ar":["إنشاء مستندات DOCX جديدة","تحرير المستندات الحالية","استخراج المحتوى من ملفات DOCX","تنسيق النص والصور","إدراج الجداول والترويسات"]},"keywords":{"zh":["DOCX 技术","Word 文档","文档创建","文档编辑","文档分析","文档转换","内容提取"],"ja":["DOCX 技術","ワード文書","文書の作成","文書の編集","文書の分析","文書の変換","コンテンツの抽出"],"ko":["DOCX 기술","워드 문서","문서 생성","문서 편집","문서 분석","문서 변환","콘텐츠 추출"],"es":["DOCX","Word","creación de documentos","edición de documentos","manipulación de documentos","informes","memorandos","cartas","plantillas"],"fr":["DOCX","Word","création de documents","édition de documents","manipulation de documents","rapports","mémorandums","lettres","modèles"],"de":["DOCX","Word","Erstellung von Dokumenten","Bearbeitung von Dokumenten","Manipulation von Dokumenten","Berichte","Memoranden","Briefe","Vorlagen"],"pt":["docx","arquivos word","criação de documentos","edição de arquivos","formatação de texto","extração de conteúdo","bibliotecas docx-js","pandoc"],"ru":["docx","файлы word","создание документов","редактирование файлов","форматирование текста","извлечение содержимого","библиотеки docx-js","pandoc"],"ar":["docx","ملفات وورد","إنشاء مستندات","تحرير الملفات","تنسيق النص","استخراج المحتوى","مكتبات docx-js","pandoc"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced .docx file manipulation capabilities.","zh":"非常适合需要高级 .docx 文件操作能力的文档分析代理。","ja":"ドキュメント分析エージェントが高度な .docx ファイル操作機能を必要とする場合に最適です。","ko":"고급 .docx 파일 조작 기능이 필요한 문서 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis de documentos que necesitan capacidades avanzadas de manipulación de archivos .docx.","fr":"Parfait pour les agents d''analyse de documents nécessitant des capacités avancées de manipulation de fichiers .docx.","de":"Perfekt für Dokumentenanalyse-Agents, die erweiterte .docx-Dateimanipulationsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades avançadas de manipulação de arquivos .docx.","ru":"Идеально подходит для агентов анализа документов, которым требуются продвинутые возможности манипулирования файлами .docx.","ar":"مثالي لعميل تحليل المستندات الذين يحتاجون إلى إمكانيات متقدمة لتعديل ملفات .docx."},"recommendation":{"en":"Empowers agents to create, read, edit, and manipulate Word documents (.docx files) using libraries like `docx-js` and `pandoc`, enabling tasks such as tracked changes, comments, and formatting like tables of contents and headings.","zh":"使代理能够使用诸如 `docx-js` 和 `pandoc` 之类的库创建、读取、编辑和操作 Word 文档 (.docx 文件)，从而实现诸如跟踪更改、注释和格式化（如目录和标题）等任务。","ja":"エージェントが `docx-js` や `pandoc` などのライブラリを使用して、Word ドキュメント (.docx ファイル) を作成、読み取り、編集、および操作できるようにし、変更の追跡、コメント、書式設定（目录や見出しなど）などのタスクを実行できるようにします。","ko":"에이전트가 `docx-js` 및 `pandoc`와 같은 라이브러리를 사용하여 워드 문서 (.docx 파일)를 생성, 읽기, 편집 및 조작할 수 있도록 하여 변경 사항 추적, 주석 및 서식 지정(목차 및 제목 등)과 같은 작업을 수행할 수 있습니다.","es":"Habilita a los agentes a crear, leer, editar y manipular documentos de Word (.docx) utilizando bibliotecas como `docx-js` y `pandoc`, lo que permite tareas como cambios rastreados, comentarios y formato como tablas de contenido y títulos.","fr":"Permet aux agents de créer, lire, éditer et manipuler des documents Word (.docx) en utilisant des bibliothèques comme `docx-js` et `pandoc`, ce qui permet des tâches telles que les modifications suivies, les commentaires et la mise en forme comme les tables des matières et les titres.","de":"Ermöglicht es den Agents, Word-Dokumente (.docx-Dateien) mithilfe von Bibliotheken wie `docx-js` und `pandoc` zu erstellen, zu lesen, zu bearbeiten und zu manipulieren, wodurch Aufgaben wie nachverfolgte Änderungen, Kommentare und Formatierungen wie Inhaltsverzeichnisse und Überschriften ermöglicht werden.","pt":"Permite que os agentes criem, leiam, editem e manipulem documentos do Word (.docx) usando bibliotecas como `docx-js` e `pandoc`, habilitando tarefas como alterações rastreadas, comentários e formatação como tabelas de conteúdo e títulos.","ru":"Позволяет агентам создавать, читать, редактировать и манипулировать документами Word (.docx) с помощью библиотек như `docx-js` и `pandoc`, что позволяет выполнять задачи, такие как отслеживаемые изменения, комментарии и форматирование, например, таблицы содержания и заголовки.","ar":"يمكن للوكيل إنشاء وقراءة وتحرير وتنقيح مستندات وورد (.docx) باستخدام مكتبات مثل `docx-js` و `pandoc` ، وتمكين المهام مثل التغييرات المتبعة والتعليقات والتخطيط مثل جداول المحتوى والعناوين."},"useCases":{"en":["Automating report generation in .docx format","Editing existing Word documents with precise control over XML structure","Converting legacy .doc files to .docx for compatibility"],"zh":["自动以 .docx 格式生成报告","使用精确的 XML 结构控制编辑现有的 Word 文档","将传统的 .doc 文件转换为 .docx 以实现兼容性"],"ja":[".docx 形式のレポートの自動生成","正確な XML 構造の制御を使用して既存の Word ドキュメントを編集",".doc ファイルを .docx に変換して互換性を確保"],"ko":[".docx 형식의 보고서 자동 생성","정확한 XML 구조 제어를 사용하여 기존 워드 문서 편집","호환성을 위해 레거시 .doc 파일을 .docx로 변환"],"es":["Automatización de la generación de informes en formato .docx","Edición de documentos de Word existentes con un control preciso sobre la estructura XML","Conversión de archivos .doc heredados a .docx para la compatibilidad"],"fr":["Automatisation de la génération de rapports au format .docx","Édition de documents Word existants avec un contrôle précis sur la structure XML","Conversion de fichiers .doc hérités en .docx pour la compatibilité"],"de":["Automatisierung der Berichtsgenerierung im .docx-Format","Bearbeitung bestehender Word-Dokumente mit präziser Kontrolle über die XML-Struktur","Konvertierung von Legacy-.doc-Dateien in .docx für die Kompatibilität"],"pt":["Automatizar a geração de relatórios no formato .docx","Editar documentos do Word existentes com controle preciso sobre a estrutura XML","Converter arquivos legados .doc para .docx para compatibilidade"],"ru":["Автоматизировать генерацию отчетов в формате .docx","Редактировать существующие документы Word с точным контролем над структурой XML","Преобразовывать устаревшие файлы .doc в .docx для совместимости"],"ar":["تحسين توليد التقارير في تنسيق .docx","تحرير المستندات الحالية لبرنامج وورد مع التحكم الدقيق على هيكل إكس إم إل","تحويل الملفات القديمة .doc إلى .docx للتوافق"]},"limitations":{"en":["Limited to .docx files, excluding PDFs, spreadsheets, and Google Docs","Requires unpacking and repacking for raw XML editing","Python scripting required for certain conversions and edits"],"zh":["仅限 .docx 文件，不包括 PDF、电子表格和 Google 文档","需要解包和重新打包以进行原始 XML 编辑","某些转换和编辑需要 Python 脚本"],"ja":[".docx ファイルのみ、PDF、スプレッドシート、および Google ドキュメントは除く","生の XML 編集のためにアンパッキングおよびリパッキングが必要","特定の変換および編集には Python スクリプトが必要"],"ko":[".docx 파일만 해당, PDF, 스프레드시트 및 Google 문서는 제외","원시 XML 편집을 위해 언패킹 및 리패킹이 필요","특정 변환 및 편집에는 Python 스크립트가 필요"],"es":["Limitado a archivos .docx, excluyendo PDF, hojas de cálculo y Google Docs","Requiere desempaque y reempaque para edición de XML cruda","Se requiere scripting de Python para ciertas conversiones y ediciones"],"fr":["Limité aux fichiers .docx, à l''exclusion des PDF, des tableurs et de Google Docs","Nécessite le dépaquetage et le reconditionnement pour l''édition XML brute","Des scripts Python sont nécessaires pour certaines conversions et éditions"],"de":["Begrenzt auf .docx-Dateien, Ausschluss von PDF, Tabellenkalkulationen und Google Docs","Erfordert Entpacken und Neuverpacken für rohe XML-Bearbeitung","Python-Skripting ist für bestimmte Konvertierungen und Bearbeitungen erforderlich"],"pt":["Limitado a arquivos .docx, excluindo PDFs, planilhas e Google Docs","Requer desempacotamento e reempacotamento para edição de XML bruta","Requer script em Python para conversões e edições específicas"],"ru":["Ограничен файлами .docx, исключая PDF, электронные таблицы и Google Docs","Требует распаковки и упаковки для редактирования сырого XML","Требует скрипта на Python для определенных преобразований и редактирований"],"ar":["محدود بملفات .docx ، باستثناء المستندات المحمولة وورقة البيانات و مستندات جوجل","يتطلب فك الحزمة وإعادة الحزمة لتعديل إكس إم إل الخام","يتطلب سكريبت بايثون لتحويلات وتنقيحات معينة"]},"version":3},"contentHash":"71cfc398ee05221f21fddc797ea5523a59278feb3447c681db92fa9130ad2da3","repoEtag":"W/\"76d69a3a3bb3abe2a601cefe1745ab33d5b89bce596aefbe206b5cf70e5967b9\"","qualityScore":75}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/pdf', 'official', 'anthropics', 'skills', 'anthropics/skills', 'pdf', 71981, 7353, 75, '2026-02-20T01:43:22Z', '2026-02-20T01:54:06.325Z', '9f78b8359fbd4943ad260a7a1e436e5a96503406d6c34e99f69223d647d85b9c', '{"id":"anthropics/skills/pdf","name":"pdf","description":{"zh":"PDF Python ","ja":"PDF Python ","ko":"PDF Python ","es":"Esta guía cubre operaciones esenciales de procesamiento de PDF con Python y herramientas de línea de comandos","fr":"Ce guide couvre les opérations essentielles de traitement de PDF avec Python et les outils de ligne de commande","de":"Diese Anleitung deckt grundlegende PDF-Verarbeitungsoperationen mit Python und Kommandozeilen-Tools ab","pt":"Este guia aborda operações essenciais de processamento de PDF usando bibliotecas Python e ferramentas de linha de comando.","ru":"Это руководство охватывает основные операции обработки PDF с использованием библиотек Python и командной строки.","ar":"يدرس هذا الدليل عمليات معالجة PDF الأساسية باستخدام مكتبات Python وأدوات سطر الأوامر.","en":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multiple PDFs into one, splitting PDFs apart, rotating pages, adding watermarks, creating new PDFs, filling PDF forms, encrypting/decrypting PDFs, ..."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":71981,"forks":7353,"updatedAt":"2026-02-20T01:43:22Z","topics":["agent-skills"],"skillMd":{"name":"pdf","description":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multiple PDFs into one, splitting PDFs apart, rotating pages, adding watermarks, creating new PDFs, filling PDF forms, encrypting/decrypting PDFs, extracting images, and OCR on scanned PDFs to make them searchable. If the user mentions a .pdf file or asks to produce one, use this skill.","bodyPreview":"# PDF Processing Guide\n\n## Overview\n\nThis guide covers essential PDF processing operations using Python libraries and command-line tools. For advanced features, JavaScript libraries, and detailed examples, see REFERENCE.md. If you need to fill out a PDF form, read FORMS.md and follow its instructions.\n\n## Quick Start\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Read a PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"Pages: {len(reader.pages)}\")\n\n# Extract text\ntext = \"\"\nfor page in reader.","body":"# PDF Processing Guide\n\n## Overview\n\nThis guide covers essential PDF processing operations using Python libraries and command-line tools. For advanced features, JavaScript libraries, and detailed examples, see REFERENCE.md. If you need to fill out a PDF form, read FORMS.md and follow its instructions.\n\n## Quick Start\n\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Read a PDF\nreader = PdfReader(\"document.pdf\")\nprint(f\"Pages: {len(reader.pages)}\")\n\n# Extract text\ntext = \"\"\nfor page in reader.pages:\n    text += page.extract_text()\n```\n\n## Python Libraries\n\n### pypdf - Basic Operations\n\n#### Merge PDFs\n```python\nfrom pypdf import PdfWriter, PdfReader\n\nwriter = PdfWriter()\nfor pdf_file in [\"doc1.pdf\", \"doc2.pdf\", \"doc3.pdf\"]:\n    reader = PdfReader(pdf_file)\n    for page in reader.pages:\n        writer.add_page(page)\n\nwith open(\"merged.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n#### Split PDF\n```python\nreader = PdfReader(\"input.pdf\")\nfor i, page in enumerate(reader.pages):\n    writer = PdfWriter()\n    writer.add_page(page)\n    with open(f\"page_{i+1}.pdf\", \"wb\") as output:\n        writer.write(output)\n```\n\n#### Extract Metadata\n```python\nreader = PdfReader(\"document.pdf\")\nmeta = reader.metadata\nprint(f\"Title: {meta.title}\")\nprint(f\"Author: {meta.author}\")\nprint(f\"Subject: {meta.subject}\")\nprint(f\"Creator: {meta.creator}\")\n```\n\n#### Rotate Pages\n```python\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\npage = reader.pages[0]\npage.rotate(90)  # Rotate 90 degrees clockwise\nwriter.add_page(page)\n\nwith open(\"rotated.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### pdfplumber - Text and Table Extraction\n\n#### Extract Text with Layout\n```python\nimport pdfplumber\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for page in pdf.pages:\n        text = page.extract_text()\n        print(text)\n```\n\n#### Extract Tables\n```python\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    for i, page in enumerate(pdf.pages):\n        tables = page.extract_tables()\n        for j, table in enumerate(tables):\n            print(f\"Table {j+1} on page {i+1}:\")\n            for row in table:\n                print(row)\n```\n\n#### Advanced Table Extraction\n```python\nimport pandas as pd\n\nwith pdfplumber.open(\"document.pdf\") as pdf:\n    all_tables = []\n    for page in pdf.pages:\n        tables = page.extract_tables()\n        for table in tables:\n            if table:  # Check if table is not empty\n                df = pd.DataFrame(table[1:], columns=table[0])\n                all_tables.append(df)\n\n# Combine all tables\nif all_tables:\n    combined_df = pd.concat(all_tables, ignore_index=True)\n    combined_df.to_excel(\"extracted_tables.xlsx\", index=False)\n```\n\n### reportlab - Create PDFs\n\n#### Basic PDF Creation\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.pdfgen import canvas\n\nc = canvas.Canvas(\"hello.pdf\", pagesize=letter)\nwidth, height = letter\n\n# Add text\nc.drawString(100, height - 100, \"Hello World!\")\nc.drawString(100, height - 120, \"This is a PDF created with reportlab\")\n\n# Add a line\nc.line(100, height - 140, 400, height - 140)\n\n# Save\nc.save()\n```\n\n#### Create PDF with Multiple Pages\n```python\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak\nfrom reportlab.lib.styles import getSampleStyleSheet\n\ndoc = SimpleDocTemplate(\"report.pdf\", pagesize=letter)\nstyles = getSampleStyleSheet()\nstory = []\n\n# Add content\ntitle = Paragraph(\"Report Title\", styles[''Title''])\nstory.append(title)\nstory.append(Spacer(1, 12))\n\nbody = Paragraph(\"This is the body of the report. \" * 20, styles[''Normal''])\nstory.append(body)\nstory.append(PageBreak())\n\n# Page 2\nstory.append(Paragraph(\"Page 2\", styles[''Heading1'']))\nstory.append(Paragraph(\"Content for page 2\", styles[''Normal'']))\n\n# Build PDF\ndoc.build(story)\n```\n\n#### Subscripts and Superscripts\n\n**IMPORTANT**: Never use Unicode subscript/superscript characters (₀₁₂₃₄₅₆₇₈₉, ⁰¹²³⁴⁵⁶⁷⁸⁹) in ReportLab PDFs. The built-in fonts do not include these glyphs, causing them to render as solid black boxes.\n\nInstead, use ReportLab''s XML markup tags in Paragraph objects:\n```python\nfrom reportlab.platypus import Paragraph\nfrom reportlab.lib.styles import getSampleStyleSheet\n\nstyles = getSampleStyleSheet()\n\n# Subscripts: use <sub> tag\nchemical = Paragraph(\"H<sub>2</sub>O\", styles[''Normal''])\n\n# Superscripts: use <super> tag\nsquared = Paragraph(\"x<super>2</super> + y<super>2</super>\", styles[''Normal''])\n```\n\nFor canvas-drawn text (not Paragraph objects), manually adjust font the size and position rather than using Unicode subscripts/superscripts.\n\n## Command-Line Tools\n\n### pdftotext (poppler-utils)\n```bash\n# Extract text\npdftotext input.pdf output.txt\n\n# Extract text preserving layout\npdftotext -layout input.pdf output.txt\n\n# Extract specific pages\npdftotext -f 1 -l 5 input.pdf output.txt  # Pages 1-5\n```\n\n### qpdf\n```bash\n# Merge PDFs\nqpdf --empty --pages file1.pdf file2.pdf -- merged.pdf\n\n# Split pages\nqpdf input.pdf --pages . 1-5 -- pages1-5.pdf\nqpdf input.pdf --pages . 6-10 -- pages6-10.pdf\n\n# Rotate pages\nqpdf input.pdf output.pdf --rotate=+90:1  # Rotate page 1 by 90 degrees\n\n# Remove password\nqpdf --password=mypassword --decrypt encrypted.pdf decrypted.pdf\n```\n\n### pdftk (if available)\n```bash\n# Merge\npdftk file1.pdf file2.pdf cat output merged.pdf\n\n# Split\npdftk input.pdf burst\n\n# Rotate\npdftk input.pdf rotate 1east output rotated.pdf\n```\n\n## Common Tasks\n\n### Extract Text from Scanned PDFs\n```python\n# Requires: pip install pytesseract pdf2image\nimport pytesseract\nfrom pdf2image import convert_from_path\n\n# Convert PDF to images\nimages = convert_from_path(''scanned.pdf'')\n\n# OCR each page\ntext = \"\"\nfor i, image in enumerate(images):\n    text += f\"Page {i+1}:\\n\"\n    text += pytesseract.image_to_string(image)\n    text += \"\\n\\n\"\n\nprint(text)\n```\n\n### Add Watermark\n```python\nfrom pypdf import PdfReader, PdfWriter\n\n# Create watermark (or load existing)\nwatermark = PdfReader(\"watermark.pdf\").pages[0]\n\n# Apply to all pages\nreader = PdfReader(\"document.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    page.merge_page(watermark)\n    writer.add_page(page)\n\nwith open(\"watermarked.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n### Extract Images\n```bash\n# Using pdfimages (poppler-utils)\npdfimages -j input.pdf output_prefix\n\n# This extracts all images as output_prefix-000.jpg, output_prefix-001.jpg, etc.\n```\n\n### Password Protection\n```python\nfrom pypdf import PdfReader, PdfWriter\n\nreader = PdfReader(\"input.pdf\")\nwriter = PdfWriter()\n\nfor page in reader.pages:\n    writer.add_page(page)\n\n# Add password\nwriter.encrypt(\"userpassword\", \"ownerpassword\")\n\nwith open(\"encrypted.pdf\", \"wb\") as output:\n    writer.write(output)\n```\n\n## Quick Reference\n\n| Task | Best Tool | Command/Code |\n|------|-----------|--------------|\n| Merge PDFs | pypdf | `writer.add_page(page)` |\n| Split PDFs | pypdf | One page per file |\n| Extract text | pdfplumber | `page.extract_text()` |\n| Extract tables | pdfplumber | `page.extract_tables()` |\n| Create PDFs | reportlab | Canvas or Platypus |\n| Command line merge | qpdf | `qpdf --empty --pages ...` |\n| OCR scanned PDFs | pytesseract | Convert to image first |\n| Fill PDF forms | pdf-lib or pypdf (see FORMS.md) | See FORMS.md |\n\n## Next Steps\n\n- For advanced pypdfium2 usage, see REFERENCE.md\n- For JavaScript libraries (pdf-lib), see REFERENCE.md\n- If you need to fill out a PDF form, follow the instructions in FORMS.md\n- For troubleshooting guides, see REFERENCE.md\n"},"category":"official","lastSynced":"2026-02-20T01:54:06.325Z","seo":{"title":{"zh":"PDF ","ja":"PDF","ko":"PDF ","es":"Procesamiento de PDF: Guía Técnica","fr":"Traitement de PDF: Guide Technique","de":"PDF-Verarbeitung: Technische Anleitung","pt":"Processamento de PDF: Guia de Referência","ru":"Обработка PDF: Руководство","ar":"معالجة PDF: دليل مرجعي","en":"pdf"},"description":{"zh":"PDF Python ","ja":"PDF Python ","ko":"PDF Python ","es":"Esta guía cubre operaciones esenciales de procesamiento de PDF con Python y herramientas de línea de comandos","fr":"Ce guide couvre les opérations essentielles de traitement de PDF avec Python et les outils de ligne de commande","de":"Diese Anleitung deckt grundlegende PDF-Verarbeitungsoperationen mit Python und Kommandozeilen-Tools ab","pt":"Este guia aborda operações essenciais de processamento de PDF usando bibliotecas Python e ferramentas de linha de comando.","ru":"Это руководство охватывает основные операции обработки PDF с использованием библиотек Python и командной строки.","ar":"يدرس هذا الدليل عمليات معالجة PDF الأساسية باستخدام مكتبات Python وأدوات سطر الأوامر.","en":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multipl..."},"definition":{"en":"Use this skill whenever the user wants to do anything with PDF files. This includes reading or extracting text/tables from PDFs, combining or merging multiple PDFs into one, splitting PDFs apart, rotating pages, adding watermarks, creating new PDFs, filling PDF forms, encrypting/decrypting PDFs, extracting images, and OCR on scanned PDFs to make them searchable. If the user mentions a .pdf file or asks to produce one, use this skill."},"features":{"zh":["PDF ","PDF ","PDF ","PDF ","PDF "],"ja":["PDF","PDF","PDF","PDF","PDF"],"ko":["PDF ","PDF ","PDF ","PDF ","PDF "],"es":["Lectura y extracción de texto de PDFs","Combinación y división de PDFs","Rotación de páginas y adición de marcas de agua","Creación de nuevos PDFs y extracción de imágenes","Cifrado y descifrado de PDFs","Reconocimiento óptico de caracteres en PDFs escaneados"],"fr":["Lecture et extraction de texte de PDF","Combinaison et division de PDF","Rotation de pages et ajout de filigranes","Création de nouveaux PDF et extraction d''images","Chiffrement et déchiffrement de PDF","Reconnaissance optique de caractères dans les PDF scannés"],"de":["Lesen und Extrahieren von Text aus PDF-Dateien","Kombinieren und Teilen von PDF-Dateien","Seiten drehen und Wasserzeichen hinzufügen","Erstellen neuer PDF-Dateien und Bildextraktion","Verschlüsseln und Entschlüsseln von PDF-Dateien","Optische Zeichenerkennung in gescannten PDF-Dateien"],"pt":["Leitura e extração de texto de PDFs","Combinação e divisão de PDFs","Adição de marcas d''água","Criação de novos PDFs","Preenchimento de formulários PDF","OCR em PDFs digitalizados"],"ru":["Чтение и извлечение текста из PDF","Объединение и разделение PDF","Добавление водяных знаков","Создание новых PDF","Заполнение форм PDF","OCR в сканированных PDF"],"ar":["قراءة و استخراج النص من ملفات PDF","دمج و افصل ملفات PDF","إضافة علامات مائية","إنشاء ملفات PDF جديدة","ملء استمارات PDF","OCR في ملفات PDF الممسوحة ضوئيا"]},"keywords":{"zh":["PDF ","PDF Python","PDF ","PDF ","PDF ","PDF "],"ja":["PDF","PDF Python","PDF","PDF","PDF","PDF"],"ko":["PDF ","PDF Python","PDF ","PDF ","PDF ","PDF "],"es":["procesamiento de PDF","Python PDF","herramientas de línea de comandos para PDF","extracción de texto de PDF","combinación de PDF","división de PDF","seguridad de PDF","reconocimiento óptico de caracteres"],"fr":["traitement de PDF","Python PDF","outils de ligne de commande pour PDF","extraction de texte de PDF","combinaison de PDF","division de PDF","sécurité de PDF","reconnaissance optique de caractères"],"de":["PDF-Verarbeitung","Python PDF","Kommandozeilen-Tools für PDF","Textextraktion aus PDF-Dateien","Kombinieren von PDF-Dateien","Teilen von PDF-Dateien","PDF-Sicherheit","optische Zeichenerkennung"],"pt":["processamento de pdf","python pdf","javascript pdf","extração de texto pdf","combinação de pdfs","criação de pdfs","preenchimento de formulários pdf","ocr pdf"],"ru":["обработка pdf","python pdf","javascript pdf","извлечение текста pdf","объединение pdf","создание pdf","заполнение форм pdf","ocr pdf"],"ar":["معالجة pdf","python pdf","javascript pdf","استخراج النص من pdf","دمج ملفات pdf","إنشاء ملفات pdf","ملء استمارات pdf","ocr pdf"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced PDF processing capabilities using Python libraries like pypdf.","zh":"非常适合需要使用 Python 库（如 pypdf）进行高级 PDF 处理的文档分析代理。","ja":"Python ライブラリ（pypdf など）を使用した高度な PDF 処理機能が必要なドキュメント分析エージェントに最適です。","ko":"Python 라이브러리(pypdf 등)를 사용한 고급 PDF 처리 기능이 필요한 문서 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de Análisis de Documentos que necesitan capacidades de procesamiento de PDF avanzadas utilizando bibliotecas de Python como pypdf.","fr":"Parfait pour les agents d''analyse de documents nécessitant des capacités de traitement de PDF avancées en utilisant des bibliothèques Python comme pypdf.","de":"Perfekt für Dokumentenanalyse-Agents, die erweiterte PDF-Verarbeitungsfunktionen unter Verwendung von Python-Bibliotheken wie pypdf benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam 